import fs from "node:fs";
import path from "node:path";
import { StopSwitch } from "./ports/StopSwitch.js";

/**
 * A stop request is the presence of a file.
 *
 * A file survives a crash, can be written by another process, and can be
 * checked without asking anything to still be running, which are the three
 * things a kill switch needs.
 */
export class FileStopSwitch implements StopSwitch {
  constructor(private readonly file: string) {}

  isRequested(): boolean {
    return fs.existsSync(this.file);
  }

  reason(): string | null {
    if (!this.isRequested()) return null;
    return fs.readFileSync(this.file, "utf-8").trim() || "no reason given";
  }

  request(reason: string): void {
    fs.mkdirSync(path.dirname(this.file), { recursive: true });
    fs.writeFileSync(this.file, `${reason}\n`, "utf-8");
  }

  clear(): void {
    fs.rmSync(this.file, { force: true });
  }

  watch(onRequested: (reason: string) => void): () => void {
    if (this.isRequested()) {
      onRequested(this.reason() ?? "no reason given");
      return () => {};
    }

    const directory = path.dirname(this.file);
    fs.mkdirSync(directory, { recursive: true });

    // Watching the directory rather than the file, because the file does not
    // exist yet and that is the event worth hearing about. The poll is the
    // fallback for a dropped/coalesced filesystem event, which must not leave
    // a running machine blind to its stop request.
    // Once per request, not once per watcher: a cleared file re-arms it, so a
    // pause after a resume still ends the children of a long `amy run`.
    let closed = false;
    let delivered = false;
    const deliver = () => {
      if (closed) return;
      if (!this.isRequested()) {
        delivered = false;
        return;
      }
      if (delivered) return;
      delivered = true;
      onRequested(this.reason() ?? "no reason given");
    };
    const watcher = fs.watch(directory, (_event, name) => {
      if (name === path.basename(this.file)) deliver();
    });
    const poll = setInterval(deliver, 50);

    return () => {
      closed = true;
      clearInterval(poll);
      watcher.close();
    };
  }
}

import {
  ChildProcess,
  ChildProcessWithoutNullStreams,
  spawn,
} from "node:child_process";
import { CommandResult, CommandRunner, RunOptions } from "./ports/CommandRunner.js";

const DEFAULT_TIMEOUT_MS = 30 * 60 * 1000;

export class NodeCommandRunner implements CommandRunner {
  /**
   * Every child still running.
   *
   * Tracked so a stop request can actually end the work in flight. Refusing
   * to start the next thing is not stopping: an agent call can run for half
   * an hour, and until it is killed nothing has stopped.
   */
  private readonly live = new Set<ChildProcess>();

  /** Ends every child still running, and says how many there were. */
  killAll(signal: NodeJS.Signals = "SIGTERM"): number {
    const running = [...this.live];
    for (const child of running) {
      child.kill(signal);
    }
    return running.length;
  }

  spawn(
    command: string,
    args: readonly string[],
    options: Pick<RunOptions, "cwd" | "env"> = {},
  ): ChildProcessWithoutNullStreams {
    const child = spawn(command, [...args], {
      cwd: options.cwd,
      env: options.env ? { ...process.env, ...options.env } : process.env,
      stdio: ["pipe", "pipe", "pipe"],
    });
    this.live.add(child);
    child.once("close", () => this.live.delete(child));
    return child;
  }

  run(
    command: string,
    args: readonly string[],
    options: RunOptions = {},
  ): Promise<CommandResult> {
    const timeoutMs = options.timeoutMs ?? DEFAULT_TIMEOUT_MS;

    return new Promise((resolve) => {
      const child = this.spawn(command, args, options);

      let stdout = "";
      let stderr = "";
      let settled = false;

      const settle = (exitCode: number | null, extra = ""): void => {
        if (settled) return;
        settled = true;
        clearTimeout(timer);
        resolve({
          ok: exitCode === 0,
          exitCode,
          stdout: options.trim === false ? stdout : stdout.trim(),
          stderr: (stderr + extra).trim(),
        });
      };

      child.stdout.on("data", (data: Buffer) => {
        stdout += data.toString();
      });
      child.stderr.on("data", (data: Buffer) => {
        stderr += data.toString();
      });

      child.on("error", (error) => settle(null, `\ncould not start ${command}: ${error.message}`));
      child.on("close", (code) => settle(code));

      const timer = setTimeout(() => {
        child.kill();
        settle(null, `\n${command} timed out after ${timeoutMs}ms`);
      }, timeoutMs);

      if (options.stdin !== undefined) {
        child.stdin.on("error", () => {});
        child.stdin.end(options.stdin);
      } else {
        child.stdin.end();
      }
    });
  }
}

import { HarnessReply } from "./ports/Harness.js";
import { Notifier } from "./ports/Notifier.js";
import { EventLog } from "./ports/EventLog.js";
import { ActionContext } from "./runtime.js";
import { WorkRecord } from "./work.js";

/** What an action is handed beside its ports: a word to the operator that may be lost. */
export interface ActionDuties {
  /**
   * Says something to the operator about this work, and never lets that cost
   * a move. A channel that fails becomes a `notify.failed` line instead.
   *
   * For what is only worth saying. A message the work depends on — a write
   * handed to the operator, say — goes through `ports.notifier`, which still
   * fails the action, so the look is tried again rather than recorded as said.
   */
  announce(text: string): Promise<void>;
}

/**
 * The ports one action receives, and the word it may say, bound to the work.
 *
 * The errand, note-to-plan and ticket-to-qa each carried the same two
 * closures: one wrote an `agent.run` line after every reply, so the budget
 * could add it up, and one swallowed a failed announcement into a
 * `notify.failed` line. A workflow that forgot the first spent money the
 * ceiling never saw. Both are the host's rules, so the host keeps them.
 *
 * Bound to the work rather than to the mount, because both lines name the
 * record and the state the action ran in, and a port shared by every action
 * cannot know which one is calling it.
 *
 * The ports stay as strict as they were. The engine's rule is that a call may
 * be swallowed only when its failure does not make the saved record a lie, so
 * only `announce` here is, and only because the action chose it.
 */
export function actionPorts<P extends object>(
  ports: P,
  work: ActionContext<WorkRecord, unknown>,
  log: EventLog | undefined,
  now: () => Date,
): { readonly ports: P } & ActionDuties {
  const append = (kind: "agent.run" | "notify.failed", detail: Record<string, unknown>): void => {
    try {
      log?.append({ at: now().toISOString(), kind, workId: work.record.id, state: work.record.state, detail });
    } catch {
      // The engine is what tells the operator its log is broken; two voices
      // for one outage is one too many.
    }
  };

  const attended: Record<string, unknown> = { ...(ports as Record<string, unknown>) };
  const { agent, notifier } = attended;

  if (hasMethod(agent, "ask")) {
    attended.agent = withMethod(agent, "ask", (ask) => async (...args: unknown[]) => {
      const reply = (await ask(...args)) as HarnessReply;
      if (reply?.run) {
        const { run } = reply;
        append("agent.run", {
          harness: run.harness,
          model: run.model,
          outcome: run.outcome,
          durationMs: run.durationMs,
          costSource: run.costSource,
          ...(run.costUsd === undefined ? {} : { costUsd: run.costUsd }),
          ...(run.tokens === undefined ? {} : { tokens: { ...run.tokens } }),
        });
      }
      return reply;
    });
  }

  return {
    ports: attended as P,
    async announce(text) {
      try {
        if (!hasMethod(notifier, "announce")) throw new Error("no notifier is mounted, so nothing can reach you");
        await (notifier as Notifier).announce({ text, workId: work.record.id, state: work.record.state });
      } catch (error) {
        append("notify.failed", { error: error instanceof Error ? error.message : String(error), text });
      }
    },
  };
}

type Method = (...args: unknown[]) => unknown;

function hasMethod<K extends string>(value: unknown, name: K): value is Record<K, Method> {
  return typeof value === "object" && value !== null && typeof (value as Record<string, unknown>)[name] === "function";
}

/**
 * The port with one method replaced and every other member as it was.
 *
 * A proxy rather than a spread: a port built as a class keeps its methods on
 * the prototype, and a spread would drop them while the mount still succeeded.
 * Every member is read with the port itself as the receiver, so an accessor
 * reading a `#private` field still finds it.
 */
function withMethod<T extends object>(port: T, name: string, wrap: (original: Method) => Method): T {
  const replaced = wrap((port as Record<string, Method>)[name]!.bind(port));
  return new Proxy(port, {
    get(target, key) {
      if (key === name) return replaced;
      const value = Reflect.get(target, key, target);
      return typeof value === "function" ? value.bind(target) : value;
    },
  });
}

export type AgentOutcome =
  /** It did the work and said so. */
  | "completed"
  /** It ran and did not succeed. A capability problem, possibly. */
  | "failed"
  /**
   * It was cut off by a quota, not by the work.
   *
   * Kept apart from `failed` because the two want opposite responses: a
   * rate limit is not a capability problem, so a stronger model does not help
   * and another harness does.
   */
  | "rate-limited"
  /** It never really ran: the harness was missing, or it was killed. */
  | "abandoned";

export interface TokenUsage {
  input: number;
  output: number;
  cacheRead: number;
  cacheWrite: number;
  /**
   * The part of `cacheWrite` written with the one-hour time to live, which
   * every price list bills at twice the input rate.
   */
  cacheWrite1h?: number;
}

/**
 * Where a cost figure came from.
 *
 * Lifted from Hermes, which writes `cost_source` next to its
 * `estimated_cost_usd` rather than presenting an estimate as a measurement.
 * Without this field a number computed from a stale price table and a number
 * the harness itself reported are indistinguishable, and a budget cannot tell
 * you which of its two ceilings it actually trusts.
 */
export type CostSource =
  /** The harness said what it cost. It knows the plan and the discounts. */
  | "reported"
  /** Worked out from the token counts and a price table. */
  | "computed"
  /**
   * A subscription covered it, so the run cost no money at all.
   *
   * Not the same as `unknown`: zero here is the right answer rather than a
   * missing one. Hermes reports this as `cost_status: "included"`, and the
   * distinction matters because such a run still spends quota — which is why
   * the token ceiling is the one that stops work on a plan.
   */
  | "included"
  /** Nobody knows. `costUsd` is absent, and that is the honest answer. */
  | "unknown";

export interface AgentRun {
  outcome: AgentOutcome;
  harness: string;
  model: string;
  /**
   * Absent when the harness did not say. Never estimated: a guessed token
   * count that a budget then spends against is worse than no number.
   */
  tokens?: TokenUsage;
  costUsd?: number;
  costSource: CostSource;
  durationMs: number;
  /** How long the provider says a quota wait lasts, when it says. */
  retryAfterMs?: number;
  /** Whatever the harness said, verbatim, because it is the next prompt. */
  output: string;
}

/**
 * What an agent gives back: the thing that was asked for, and the account of
 * what it took to get it.
 *
 * One envelope over a generic value, so the three agent methods each keep
 * their own return type instead of three separate shapes growing three
 * separate accounting fields.
 */
export interface AgentResult<T> {
  value: T;
  run: AgentRun;
}

/** Nothing was spent, or nothing is known about what was. */
export const NO_TOKENS: TokenUsage = { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 };

export function totalTokens(tokens: TokenUsage): number {
  return tokens.input + tokens.output + tokens.cacheRead + tokens.cacheWrite;
}

/** The input side, which is what a long-context threshold is measured against. */
export function inputSideTokens(tokens: TokenUsage): number {
  return tokens.input + tokens.cacheRead + tokens.cacheWrite;
}

/**
 * What a run actually spends, which is not what it reads.
 *
 * A cache read is the *saving*: it is the same context, already paid for,
 * served at a fraction of the price. Counting it against a ceiling inverts
 * the incentive — the better the cache works the bigger this number gets, and
 * the sooner the machine locks itself out for having been efficient.
 *
 * That is not hypothetical. One implement run on this install reported
 * `input: 44, output: 17394, cacheRead: 1839757, cacheWrite: 92769`, which
 * `totalTokens` adds to 1,949,964 — 97.5% of a 2,000,000 per-five-hours
 * ceiling, from a run that cost $0.91 against a $20 ceiling in the same
 * window. One run, and the machine parked itself for five hours.
 *
 * `costUsd` is the ceiling that already knows what cache is worth, because
 * the model specs price the four kinds separately. This one is the quota
 * proxy, and quota is spent on what is generated and freshly sent.
 */
export function billableTokens(tokens: TokenUsage): number {
  return tokens.input + tokens.output;
}

import { BudgetLimits, WindowLimit } from "./ports/Budget.js";

/** The fraction of a ceiling at which new work stops, unless configured. */
export const DEFAULT_STOP_AT = 0.9;

/** The windows a ceiling may be set over, and nothing else is accepted. */
const WINDOWS = ["perFiveHours", "perWeek"] as const;
const MEASURES = ["tokens", "costUsd"] as const;

export type BudgetResult =
  | { ok: true; limits: BudgetLimits }
  | { ok: false; problems: string[] };

/**
 * Reads a `budget` setting, refusing anything it cannot mean.
 *
 * `ConfigSchema` stops at "this is a mapping", because five field types are
 * enough for every other plugin and a nested shape wants its own validation.
 * This is that validation, kept next to the ledger it feeds so the plugin
 * that takes the setting and the command that prints it read one parser.
 */
export function parseBudget(value: unknown): BudgetResult {
  if (value === undefined) return { ok: true, limits: { stopAt: DEFAULT_STOP_AT } };
  if (!isRecord(value)) return { ok: false, problems: ["`budget` must be a mapping"] };

  const problems: string[] = [];
  const limits: BudgetLimits = { stopAt: stopAtIn(value, problems) };

  for (const window of WINDOWS) {
    const given = value[window];
    if (given === undefined) continue;

    const ceiling = windowIn(window, given, problems);
    if (ceiling) limits[window] = ceiling;
  }

  const progress = progressIn(value, problems);
  if (progress) limits.progress = progress;

  for (const field of Object.keys(value)) {
    if (field !== "stopAt" && field !== "progress" && !WINDOWS.includes(field as (typeof WINDOWS)[number])) {
      problems.push(`\`budget.${field}\` is not a window this plugin meters: ${WINDOWS.join(", ")}`);
    }
  }

  return problems.length > 0 ? { ok: false, problems } : { ok: true, limits };
}

/**
 * The fraction of a ceiling at which new work stops.
 *
 * Above one it could never fire, and at or below zero it would never let
 * anything start, so both are typos rather than policies.
 */
function stopAtIn(value: Record<string, unknown>, problems: string[]): number {
  const given = value.stopAt;
  if (given === undefined) return DEFAULT_STOP_AT;

  if (typeof given !== "number" || !Number.isFinite(given) || given <= 0 || given > 1) {
    problems.push("`budget.stopAt` must be a fraction above 0 and at most 1, such as 0.9");
    return DEFAULT_STOP_AT;
  }

  return given;
}

function windowIn(window: string, given: unknown, problems: string[]): WindowLimit | null {
  if (!isRecord(given)) {
    problems.push(`\`budget.${window}\` must be a mapping of tokens and costUsd`);
    return null;
  }

  const ceiling: WindowLimit = {};
  let named = 0;

  for (const measure of MEASURES) {
    const amount = given[measure];
    if (amount === undefined) continue;
    named += 1;

    if (typeof amount !== "number" || !Number.isFinite(amount) || amount < 0) {
      problems.push(`\`budget.${window}.${measure}\` must be a number of ${measure} at or above 0`);
      continue;
    }
    ceiling[measure] = amount;
  }

  for (const field of Object.keys(given)) {
    if (!MEASURES.includes(field as (typeof MEASURES)[number])) {
      problems.push(`\`budget.${window}.${field}\` is not a measure: ${MEASURES.join(", ")}`);
    }
  }

  // A window naming neither measure reads like a budget and is not one. A
  // window that named one badly has already been complained about, and
  // saying it twice would only hide the first line.
  if (named === 0) {
    problems.push(`\`budget.${window}\` sets no ceiling: give it tokens, costUsd, or both`);
  }

  return Object.keys(ceiling).length > 0 ? ceiling : null;
}

function progressIn(
  value: Record<string, unknown>,
  problems: string[],
): { maxUnchanged: number; handoff: "park" } | undefined {
  const given = value.progress;
  if (given === undefined) return undefined;
  if (!isRecord(given)) {
    problems.push("`budget.progress` must be a mapping");
    return undefined;
  }
  const max = given.maxUnchanged === undefined ? 2 : given.maxUnchanged;
  if (!validProgressMax(max)) {
    problems.push("`budget.progress.maxUnchanged` must be a positive integer");
  }
  const handoff = given.handoff === undefined ? "park" : given.handoff;
  if (!isPark(handoff)) problems.push("`budget.progress.handoff` must be `park`");
  progressFieldProblems(given, problems);
  return validProgressMax(max) && isPark(handoff)
    ? { maxUnchanged: max, handoff }
    : undefined;
}

function validProgressMax(value: unknown): value is number {
  return typeof value === "number" && Number.isInteger(value) && value >= 1;
}

function isPark(value: unknown): value is "park" {
  return value === "park";
}

function progressFieldProblems(value: Record<string, unknown>, problems: string[]): void {
  for (const field of Object.keys(value)) {
    if (field !== "maxUnchanged" && field !== "handoff") {
      problems.push(`\`budget.progress.${field}\` is not a progress setting: maxUnchanged, handoff`);
    }
  }
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/** The ceiling configured for one window, if any. */
export function ceilingFor(limits: BudgetLimits, window: string): WindowLimit | undefined {
  return window === "perFiveHours" ? limits.perFiveHours : limits.perWeek;
}

import { billableTokens } from "./agent-run.js";
import { ceilingFor } from "./budget-config.js";
import {
  Budget,
  BudgetDecision,
  BudgetLimits,
  BudgetMeasure,
  WindowLimit,
} from "./ports/Budget.js";
import { Event, EventLog } from "./ports/EventLog.js";

export interface BudgetWindow {
  name: string;
  ms: number;
}

/**
 * The windows a ceiling can be set over.
 *
 * Their durations are fixed because they are not preferences: five hours is
 * the session window a subscription meters, and a week is the other one it
 * meters. What an operator configures is the ceiling in each.
 */
export const BUDGET_WINDOWS: readonly BudgetWindow[] = [
  { name: "perFiveHours", ms: 5 * 60 * 60 * 1000 },
  { name: "perWeek", ms: 7 * 24 * 60 * 60 * 1000 },
];

const MEASURES: readonly BudgetMeasure[] = ["tokens", "costUsd"];

export interface Spend {
  tokens: number;
  /** Only money somebody measured or worked out. See `moneyIn`. */
  costUsd: number;
  runs: number;
  /**
   * How many of those runs nobody could put a price on.
   *
   * `costUsd` above is arithmetically true and, with this above zero,
   * practically a lie: it is the spend of the runs that were priced and not
   * the spend of the window. A reader who is not told how many were left out
   * reads a dollar figure that is lower than the truth by an unknown amount.
   */
  unpriced: number;
  /** The oldest run counted, which is when the window starts to clear. */
  oldestAt?: string;
}

/**
 * What the agent runs since an instant added up to.
 *
 * Read from the log rather than from a counter of its own, because a second
 * tally is a second thing to disagree with what actually happened.
 */
export function spendSince(events: readonly Event[], since: Date): Spend {
  const spend: Spend = { tokens: 0, costUsd: 0, runs: 0, unpriced: 0 };
  const cutoff = since.getTime();

  for (const event of events) {
    if (event.kind !== "agent.run") continue;
    if (new Date(event.at).getTime() < cutoff) continue;

    const detail = event.detail ?? {};
    const price = priceOf(detail);

    spend.runs += 1;
    spend.tokens += tokensIn(detail);
    spend.costUsd += price ?? 0;
    if (price === undefined) spend.unpriced += 1;
    if (!spend.oldestAt || event.at < spend.oldestAt) spend.oldestAt = event.at;
  }

  return spend;
}

/**
 * Whether a run may start, and if not, which ceiling stopped it.
 *
 * Windows are asked in the order they are declared and the first one over
 * its `stopAt` answers, so the same log and the same limits always give the
 * same reason.
 */
export function budgetDecision(
  events: readonly Event[],
  limits: BudgetLimits,
  now: Date,
): BudgetDecision {
  for (const window of BUDGET_WINDOWS) {
    const ceiling = ceilingFor(limits, window.name);
    if (!ceiling) continue;

    const spend = spendSince(events, new Date(now.getTime() - window.ms));
    const refusal = blown(window, ceiling, spend, limits.stopAt, now);
    if (refusal) return refusal;
  }

  return { ok: true };
}

export function hasACeiling(limits: BudgetLimits): boolean {
  return BUDGET_WINDOWS.some((window) => ceilingFor(limits, window.name) !== undefined);
}

/** The budget, read from the event log every time it is asked. */
export class LogBudget implements Budget {
  constructor(
    private readonly log: EventLog,
    private readonly limits: BudgetLimits,
  ) {}

  mayStart(now: Date): BudgetDecision {
    if (!hasACeiling(this.limits)) return { ok: true };

    // Only as far back as the longest window, so the read does not grow with
    // the age of the install.
    const longest = Math.max(...BUDGET_WINDOWS.map((window) => window.ms));
    const since = new Date(now.getTime() - longest);

    return budgetDecision(this.log.read(since), this.limits, now);
  }
}

function blown(
  window: BudgetWindow,
  ceiling: WindowLimit,
  spend: Spend,
  stopAt: number,
  now: Date,
): BudgetDecision | null {
  for (const measure of MEASURES) {
    const limit = measure === "tokens" ? ceiling.tokens : ceiling.costUsd;
    if (limit === undefined) continue;

    const used = measure === "tokens" ? spend.tokens : spend.costUsd;
    if (used < limit * stopAt) continue;

    return {
      ok: false,
      window: window.name,
      measure,
      used,
      limit,
      stopAt,
      retryAfterMs: clearsIn(spend, window, now),
      reason:
        `the ${window.name} budget has spent ${used} of its ${limit} ${measure} ceiling, ` +
        `and new work stops at ${Math.round(stopAt * 100)}%`,
    };
  }

  return null;
}

/**
 * When the window next has room: the moment its oldest run falls out of it.
 *
 * With nothing in the window at all the ceiling itself must be zero, and the
 * whole window is the honest answer.
 */
function clearsIn(spend: Spend, window: BudgetWindow, now: Date): number {
  if (!spend.oldestAt) return window.ms;

  const leaves = new Date(spend.oldestAt).getTime() + window.ms - now.getTime();
  return Math.max(leaves, 1000);
}

function tokensIn(detail: Record<string, unknown>): number {
  const tokens = detail.tokens;
  if (!isRecord(tokens)) return 0;

  // Billable, not total: a cache read is context already paid for, and
  // counting it here parked this machine for five hours after a single run.
  // See `billableTokens`.
  return billableTokens({
    input: numberAt(tokens, "input"),
    output: numberAt(tokens, "output"),
    cacheRead: numberAt(tokens, "cacheRead"),
    cacheWrite: numberAt(tokens, "cacheWrite"),
  });
}

/**
 * What a run cost, or nothing at all, which is a different thing from zero.
 *
 * `unknown` moves the token ceiling and not this one. Adding up a figure
 * nobody measured would invent the number that decides when to stop, so it
 * returns undefined and the window counts it as unpriced instead.
 *
 * `included` is a real zero: the subscription already paid for it, and a
 * window full of those is fully accounted for rather than unknown.
 */
function priceOf(detail: Record<string, unknown>): number | undefined {
  const source = detail.costSource;
  if (source === "included") return 0;
  if (source !== "reported" && source !== "computed") return undefined;

  const cost = detail.costUsd;
  return typeof cost === "number" && Number.isFinite(cost) ? cost : undefined;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function numberAt(record: Record<string, unknown>, field: string): number {
  const value = record[field];
  return typeof value === "number" && Number.isFinite(value) ? value : 0;
}

/**
 * Which build is running.
 *
 * Nothing here reads the environment or the file system. What a build is gets
 * decided by whoever can tell — the CLI, from the stamp `npm pack` wrote into
 * the package — and this is only the shape of the answer and how it is said.
 */
export interface BuildStamp {
  /** The version this was built at, or `dev`. */
  version: string;
  /** The commit it was built from, short, or `dev`. */
  commit: string;
  /** When it was built, ISO 8601, or empty when it was not built. */
  builtAt: string;
  /** True when this is an installed release rather than a checkout. */
  released: boolean;
}

/** What goes on a log line: short, and different for every build. */
export function stampId(stamp: BuildStamp): string {
  return stamp.released ? `${stamp.version}+${stamp.commit}` : "dev";
}

export function stampFrom(
  defined: Partial<Record<"version" | "commit" | "builtAt", string>>,
): BuildStamp {
  const version = defined.version ?? "";
  const commit = defined.commit ?? "";

  // Both, or neither. A half-stamped install would claim to be a release
  // while being unable to say which one, and that is worse than admitting it
  // is a checkout.
  if (!version || !commit) {
    return { version: "dev", commit: "dev", builtAt: "", released: false };
  }

  return { version, commit, builtAt: defined.builtAt ?? "", released: true };
}

/** One line for `amy --version`, which is a different audience to the log. */
export function describeBuild(stamp: BuildStamp): string {
  if (!stamp.released) {
    return "dev (running from source, not an installed build)";
  }

  const when = stamp.builtAt ? `, built ${stamp.builtAt}` : "";
  return `${stamp.version} (${stamp.commit}${when})`;
}

import { Deferred, factoryOf, isDeferred } from "./deferred.js";

/**
 * Thrown through a build whose refusal is already written down, so the
 * builds that were waiting on it fail without each repeating it.
 */
class Refused extends Error {}

interface Entry {
  readonly plugin: string;
  /** What it is, the way a refusal names it: "the `agent` port". */
  readonly what: string;
  readonly build: () => object;
  state: "pending" | "building" | "built" | "failed";
  value?: object;
  /** Where the built object goes, and what has to know it was built. */
  readonly then: ((value: object) => void)[];
}

/**
 * The deferred implementations of one mount.
 *
 * Built once every plugin has registered, each exactly once, and on demand
 * when one reads another — which is what keeps the order plugins are listed
 * in from mattering. One instance per `mount()`, so two hosts in a process
 * never share a build.
 */
export class Builds {
  private readonly entries = new Map<Deferred, Entry>();
  private readonly building: Entry[] = [];
  private open = false;

  constructor(private readonly problems: string[]) {}

  /** Records a deferred implementation, and what to do with what it builds. */
  defer(marker: Deferred, plugin: string, what: string, then: (value: object) => void): void {
    const existing = this.entries.get(marker);
    if (existing) {
      existing.then.push(then);
      return;
    }
    this.entries.set(marker, { plugin, what, build: factoryOf(marker), state: "pending", then: [then] });
  }

  /** Runs `then` with the built object, once there is one. */
  afterBuilt(marker: Deferred, then: (value: object) => void): void {
    const entry = this.entries.get(marker);
    if (!entry) return;
    if (entry.state === "built" && entry.value) then(entry.value);
    else entry.then.push(then);
  }

  /** Whether this value is one of this mount's deferred implementations. */
  holds(value: unknown): value is Deferred {
    return isDeferred(value) && this.entries.has(value);
  }

  /**
   * What a reader receives: the built object, never the factory.
   *
   * Building on demand here is what lets one deferred implementation read
   * another listed after it. Read during `register`, it is refused by name:
   * what it needs may not have registered yet.
   */
  resolve<T>(value: T): T | object {
    if (!this.holds(value)) return value;
    const entry = this.entries.get(value)!;
    if (!this.open) {
      throw new Error(
        `${entry.what} of ${entry.plugin} is built once every plugin has registered; read it when it is used, not in \`register\``,
      );
    }
    return this.get(entry);
  }

  /**
   * A collection as a reader sees it: each deferred member built when it is
   * read, never the factory. Lazily, member by member, so a member that reads
   * a sibling while it builds is not mistaken for one that reads itself.
   */
  collection(members: Map<string, object> | undefined): ReadonlyMap<string, object> {
    return new BuiltCollection(members ?? new Map(), this);
  }

  /** Builds every deferred implementation, in the order it was registered. */
  buildAll(): void {
    this.open = true;
    for (const entry of this.entries.values()) {
      try {
        this.get(entry);
      } catch (error) {
        if (!(error instanceof Refused)) throw error;
      }
    }
  }

  private get(entry: Entry): object {
    if (entry.state === "built") return entry.value!;
    if (entry.state === "failed") throw new Refused(`${entry.what} of ${entry.plugin} could not be built`);
    if (entry.state === "building") this.refuseCycle(entry);

    entry.state = "building";
    this.building.push(entry);
    try {
      const value = built(entry.build());
      entry.value = value;
      entry.state = "built";
      for (const then of entry.then) then(value);
      return value;
    } catch (error) {
      entry.state = "failed";
      // A build that failed because something it read was refused is not a
      // second problem; the first one already names who to fix.
      if (!(error instanceof Refused)) {
        this.problems.push(`${entry.plugin}: failed to mount — ${error instanceof Error ? error.message : String(error)}`);
      }
      throw new Refused(`${entry.what} of ${entry.plugin} could not be built`);
    } finally {
      this.building.pop();
    }
  }

  /** Two (or more) builds that each read the other can never finish. */
  private refuseCycle(entry: Entry): never {
    const circle = this.building.slice(this.building.indexOf(entry));
    const named = circle.map((each) => `${each.plugin} (${each.what})`);
    this.problems.push(
      circle.length === 1
        ? `${named[0]}: reads itself while it is being built`
        : named.length === 2
          ? `${named[0]} and ${named[1]} each need what the other builds, so neither can be built`
          : `${named.slice(0, -1).join(", ")} and ${named.at(-1)} need what each other builds, in a circle, so none of them can be built`,
    );
    throw new Refused(`${entry.what} of ${entry.plugin} is part of a circle`);
  }
}

/** What a build may return: an implementation, and not the promise of one. */
function built(value: unknown): object {
  if ((typeof value !== "object" && typeof value !== "function") || value === null) {
    throw new Error("its deferred build returned nothing to mount");
  }
  const then = (value as { then?: unknown }).then;
  if (typeof then === "function") {
    // Handled before refusing, so a factory that rejects is this refusal and
    // not also an unhandled rejection that takes the host down.
    then.call(value, undefined, () => undefined);
    throw new Error("its deferred build returned a promise; a build returns the implementation itself");
  }
  return value;
}

/** A live view of one collection that builds each member as it is read. */
class BuiltCollection implements ReadonlyMap<string, object> {
  constructor(
    private readonly members: Map<string, object>,
    private readonly builds: Builds,
  ) {}

  get size(): number {
    return this.members.size;
  }

  has(name: string): boolean {
    return this.members.has(name);
  }

  get(name: string): object | undefined {
    const member = this.members.get(name);
    return member === undefined ? undefined : (this.builds.resolve(member) as object);
  }

  keys(): MapIterator<string> {
    return this.members.keys();
  }

  *entries(): MapIterator<[string, object]> {
    for (const name of [...this.members.keys()]) yield [name, this.get(name)!];
  }

  *values(): MapIterator<object> {
    for (const [, value] of this.entries()) yield value;
  }

  [Symbol.iterator](): MapIterator<[string, object]> {
    return this.entries();
  }

  forEach(each: (value: object, name: string, map: ReadonlyMap<string, object>) => void, self?: unknown): void {
    for (const [name, value] of this.entries()) each.call(self, value, name, this);
  }
}

/**
 * A state that calls another workflow, the way code calls a function.
 *
 * The callee runs as a child record kept inside its caller's, with its own
 * id, history and attempts, and only the deepest record in a call is ever
 * observed or decided. See `docs/design/a-workflow-calls-another.md`.
 */

import { PortLookup, declaredBinding, implementationOf, isPortBinding, reaching, runAction } from "./dispatch.js";
import { ActionSpec } from "./actions.js";
import { BranchLeases, LeaseHeld, runningLane } from "./leases.js";
import { ActionContext, ActionImplementation, WorkflowRuntime } from "./runtime.js";
import { Workflow } from "./plugin.js";
import { Worktree } from "./ports/Worktree.js";
import { Action, Lane, Moved, Plan, WorkRecord, applyPlan, looksIn, movedBy } from "./work.js";

const CALL = Symbol.for("@amykit/core/call");
/** The child's own plan, carried on the one its caller's engine is handed. */
const INNER = Symbol.for("@amykit/core/call-inner");
/** The end a child reached, carried on the move its caller makes for it. */
const RETURNED = Symbol.for("@amykit/core/call-returned");
/** A record in a call state that holds no call, entering it now. */
const ENTER = Symbol.for("@amykit/core/call-enter");
/** A record in a fork that started no lanes, starting them now. */
const ENTER_FORK = Symbol.for("@amykit/core/fork-enter");
/** The lane a plan, or an action on it, is a move of. */
const LANE = Symbol.for("@amykit/core/lane");
/**
 * The lanes an action is a move of, outermost first: a lane's own action is
 * `[A]`; one of a lane inside a workflow that lane calls is `[A, B]`. Each fork
 * runs it as its head lane's, and hands the rest on.
 */
const LANE_PATH = Symbol.for("@amykit/core/lane-path");
/** The move to the join, once every lane has ended. */
const JOINED = Symbol.for("@amykit/core/joined");

/**
 * Where a caller's observation keeps its child's.
 *
 * A string rather than a symbol, so a copy of the observation — the testkit
 * keeps one of every look — still carries it.
 */
export const CALLED = "@amykit/called";

/** Where a caller's observation keeps each running lane's, by lane state. */
export const LANED = "@amykit/laned";

/** Where a fork's observation keeps the caller's own world, for what it says before the lanes do. */
const OWN = "@amykit/own";

/**
 * Where the outcome of a look a lane spent waiting on a branch is written:
 * not a try, and looked at again shortly, when the lane holding it may have
 * let it go.
 */
export const LEASE_WAIT = "@amykit/lease-wait";
const LEASE_WAIT_MS = 1_000;

/**
 * What a caller says about one call: what it passes, the callee's settings
 * for this call site, which of the root's ports stand for the callee's needs,
 * and how each return value folds back. Every member is optional.
 */
export interface CallBinding<R extends WorkRecord = WorkRecord, I = unknown, Outs = Record<string, unknown>> {
  readonly input?: (work: R) => I;
  /**
   * The caller's queue is this callee's queue too. A composed root marks its
   * entry call, so work the entry phase discovers begins at the root rather
   * than disappearing because the root has no separate provider.
   */
  readonly discover?: boolean;
  readonly config?: Readonly<Record<string, unknown>>;
  readonly ports?: Readonly<Record<string, string>>;
  readonly output?: { readonly [End in keyof Outs]?: (work: R, out: Outs[End]) => R };
  /**
   * What the caller does on the edge out, as any advance may carry effects:
   * say where the pull request is, say why it was refused. Each runs as one
   * of the caller's own actions.
   */
  readonly effects?: { readonly [End in keyof Outs]?: (work: R, out: Outs[End]) => Action[] };
  /**
   * The commit the callee checks rather than the base, read-only: a lane that
   * checks the caller's work is lent a tree detached at it. Worked out when
   * the call starts, from the caller's record.
   */
  readonly revision?: (work: R) => string | undefined;
  /**
   * The branch the callee writes, when the call site knows it before
   * anything runs. Two lanes of one fork naming the same one are refused at
   * boot; a branch known only at run time is held to a lease instead.
   */
  readonly branch?: string;
}

/** A callee as a caller names it: the workflow, or a function returning it for one defined later. */
export type CalleeReference<C extends object = object> = C | (() => C);

/**
 * A bound call, its caller's record type let go of: the binding was typed
 * where `call` was written, and a declaration's own record type is inferred
 * from its decisions rather than from here.
 */
export interface Call {
  readonly [CALL]: true;
  readonly callee: CalleeReference;
  readonly binding: CallBinding;
}

/** The input and the return values a callee declares, carried for the binding's types only. */
declare const SIGNATURE: unique symbol;
export interface Signature<I = unknown, Outs = Record<string, unknown>> {
  readonly [SIGNATURE]?: { readonly input: I; readonly outputs: Outs };
}

type InputOf<C> = C extends Signature<infer I, Record<string, unknown>> ? I : unknown;
type OutputsOf<C> = C extends Signature<unknown, infer Outs> ? (unknown extends Outs ? Record<string, unknown> : Outs) : Record<string, unknown>;

/**
 * Binds a call state to the workflow it calls.
 *
 * `call(review)` is the whole call when the callee takes nothing and the
 * caller keeps nothing it returns.
 */
export function call<C extends object, R extends WorkRecord = WorkRecord>(
  callee: CalleeReference<C>,
  binding: CallBinding<R, InputOf<C>, OutputsOf<C>> = {},
): Call {
  return Object.freeze({ [CALL]: true as const, callee, binding: binding as unknown as CallBinding });
}

export function isCall(value: unknown): value is Call {
  return typeof value === "object" && value !== null && (value as Record<symbol, unknown>)[CALL] === true;
}

/** Everything one call state needs once the mount has checked it. */
export interface CallSite {
  readonly state: string;
  /** The callee's name, for what is said about it. */
  readonly callee: string;
  readonly binding: CallBinding;
  /** The callee's workflow, itself composed when it calls others. */
  readonly workflow: Workflow;
  /** The callee's policy before its runtime exists. */
  readonly policy: unknown;
  /** Where the caller goes when the callee ends at each of its terminal states. */
  readonly edges: Readonly<Record<string, string>>;
  /** What the callee returns at an end, or undefined at one that returns nothing. */
  output(record: WorkRecord): unknown;
  /** A new callee record, already inside its own first call when it starts in one. */
  newRecord(workId: string, now: Date, input: unknown): WorkRecord;
  /** The callee's runtime, once the mount has built it. */
  runtime?: WorkflowRuntime;
  /** The root's ports as this callee is bound to them. */
  readonly port: PortLookup;
}

/** The record a caller is waiting on, or undefined when it is not in a call. */
export function activeCall(record: WorkRecord): WorkRecord | undefined {
  return record.calling === undefined ? undefined : record.calls?.[record.calling];
}

/** The record and every record it is waiting on, deepest last. */
export function callPath(record: WorkRecord): WorkRecord[] {
  const path = [record];
  for (let child = activeCall(record); child; child = activeCall(child)) path.push(child);
  return path;
}

/** One record on a call path, with the workflow that drives it. */
export interface CallStep {
  readonly record: WorkRecord;
  readonly workflow: Workflow;
}

/**
 * Where a piece of work stands through every call it is in: each record from
 * the root down, and whether the deepest one is waiting on its owner. A child
 * that escalates is the root's attention, because the root is what a person
 * sees.
 */
export function callStanding(workflow: Workflow, record: WorkRecord): { readonly path: readonly CallStep[]; readonly attention: boolean; readonly waiting: boolean } {
  const path: CallStep[] = [];
  let at: Workflow | undefined = workflow;
  for (const step of callPath(record)) {
    if (!at) break;
    path.push({ record: step, workflow: at });
    at = at.calls?.[step.state];
  }
  const deepest = path.at(-1)!;
  const lanes = laneStanding(deepest.workflow, deepest.record).filter((lane) => !lane.ended);
  if (lanes.length > 0) {
    // A record waiting on lanes needs the person when any lane does, and
    // waits when every lane still running does.
    return { path, attention: lanes.some((lane) => lane.attention), waiting: lanes.every((lane) => lane.waiting) };
  }
  return {
    path,
    attention: deepest.workflow.diagram?.attention.includes(deepest.record.state) ?? false,
    waiting: deepest.workflow.waitingStates.includes(deepest.record.state),
  };
}

/**
 * Enters a call: a new child record, numbered by how many times this caller
 * has entered the same state before, so a second entry never reuses the
 * first's history or output.
 */
export function enterCall(record: WorkRecord, site: CallSite, now: Date): WorkRecord {
  const child = newChild(record, site, now);
  return { ...record, calls: { ...record.calls, [child.id]: child }, calling: child.id };
}

/** The callee's new record for one entry into its call state, holding what the binding lends it. */
function newChild(record: WorkRecord, site: CallSite, now: Date): WorkRecord {
  const prefix = `${record.id}/${site.state}#`;
  const entered = Object.keys(record.calls ?? {}).filter((id) => id.startsWith(prefix)).length;
  const id = `${prefix}${entered + 1}`;
  const child = site.newRecord(id, now, site.binding.input?.(record));
  const revision = site.binding.revision?.(record);
  return revision === undefined ? child : { ...child, revision };
}

/** A fork as the mount put it together: its lanes, each a call, and where they meet. */
export interface ForkSite {
  readonly state: string;
  readonly join: string;
  readonly lanes: readonly CallSite[];
  /** The branches its lanes hold, let go of as each one ends. */
  readonly leases?: BranchLeases;
  /**
   * The commit each running lane was lent, by the lane record's id, read by
   * the lanes' checkouts: a lane bound with `revision` is handed a tree
   * detached at it whatever it asks for, and every move there is refused.
   */
  readonly lent?: Map<string, string>;
}

/**
 * Enters a fork: every lane's callee starts at once, each a record of its own
 * with its own input, numbered like any call so a second round never reuses
 * the first's.
 */
function enterFork(record: WorkRecord, fork: ForkSite, now: Date): WorkRecord {
  let entered = record;
  const lanes: Record<string, Lane> = {};
  for (const site of fork.lanes) {
    const child = newChild(entered, site, now);
    entered = { ...entered, calls: { ...entered.calls, [child.id]: child } };
    lanes[site.state] = { call: child.id };
  }
  return { ...entered, lanes };
}

/** The lane's own record, or undefined for a lane this record never started. */
function laneRecord(record: WorkRecord, lane: string): WorkRecord | undefined {
  const call = record.lanes?.[lane]?.call;
  return call === undefined ? undefined : record.calls?.[call];
}

function hasEnded(site: CallSite, child: WorkRecord | undefined): boolean {
  return !!child && site.workflow.terminalStates.includes(child.state);
}

/** Whether a record in this fork has started every one of its lanes. */
function started(fork: ForkSite, record: WorkRecord): boolean {
  return fork.lanes.every((site) => laneRecord(record, site.state) !== undefined);
}

/** The lanes still running, in the order the next look takes them: the one whose turn it is first. */
function inTurn(fork: ForkSite, record: WorkRecord): CallSite[] {
  const running = fork.lanes.filter((site) => !hasEnded(site, laneRecord(record, site.state)));
  if (running.length === 0) return running;
  const first = looksIn(record, fork.state) % running.length;
  return [...running.slice(first), ...running.slice(0, first)];
}

/** Where one lane stands, as its caller says it. */
export interface LaneStanding {
  readonly lane: string;
  readonly record: WorkRecord;
  readonly ended: boolean;
  /** The lane, at its deepest call, waits on the person whose work it is. */
  readonly attention: boolean;
  readonly waiting: boolean;
}

/**
 * Every lane of the fork a record waits in, and where each stands; empty for
 * a record that is not in a fork. What the join says while it waits: which
 * lanes have arrived, and which one needs the person.
 */
export function laneStanding(workflow: Workflow, record: WorkRecord): LaneStanding[] {
  const fork = workflow.diagram?.forks[record.state];
  if (!fork) return [];
  return fork.lanes.flatMap((lane) => {
    const child = laneRecord(record, lane);
    const callee = workflow.calls?.[lane];
    if (!child || !callee) return [];
    const standing = callStanding(callee, child);
    return [{ lane, record: child, ended: callee.terminalStates.includes(child.state), attention: standing.attention, waiting: standing.waiting }];
  });
}

/**
 * The caller's workflow, with each call state decided by its callee.
 *
 * A child's move is handed to the engine as a look its caller took without
 * trying, so nothing the callee counts reaches a caller's ceiling, and the
 * caller's own state moves only when the child reaches an end.
 */
export function composedWorkflow(own: Workflow, sites: ReadonlyMap<string, CallSite>, forks: ReadonlyMap<string, ForkSite> = new Map()): Workflow {
  if (sites.size === 0) return own;
  return {
    ...own,
    calls: Object.fromEntries([...sites].map(([state, site]) => [state, site.workflow])),
    everyLane: (record, observation, policy) => everyLaneThrough(own, sites, forks, record, observation, policy),
    plan: (record, observation, policy) => {
      const fork = forks.get(record.state);
      if (fork) return own.interrupt?.(record, ownObservation(observation), policy) ?? forkPlan(fork, record, observation);
      const site = callAt(sites, forks, record.state);
      if (!site) return own.plan(record, observation, policy);
      const child = activeCall(record);
      // A record saved in this state before it was a call — an install that
      // upgraded mid-flight — makes its call on its next look.
      if (!child) return Object.assign({ kind: "act", effects: [], why: `${record.id} calls ${site.callee} in ${record.state}`, attempt: false } as Plan, { [ENTER]: true });
      if (site.workflow.terminalStates.includes(child.state)) return returned(site, record, child);
      const inner = site.workflow.plan(child, childObservation(observation), site.runtime?.policy ?? site.policy);
      return carried(child, inner);
    },
  };
}

/**
 * The call a record in this state is making — none for a lane, which is
 * never a record's own state: its fork is. A record that is in one was saved
 * there by a version before the state was a lane, and is the workflow's own
 * to move.
 */
function callAt(sites: ReadonlyMap<string, CallSite>, forks: ReadonlyMap<string, ForkSite>, state: string): CallSite | undefined {
  for (const fork of forks.values()) if (fork.lanes.some((lane) => lane.state === state)) return undefined;
  return sites.get(state);
}

function returned(site: CallSite, record: WorkRecord, child: WorkRecord): Plan {
  const to = site.edges[child.state]!;
  const say = (site.binding.effects as Record<string, ((work: WorkRecord, out: unknown) => Action[]) | undefined> | undefined)?.[child.state];
  const effects = say ? say(record, site.output(child)) : [];
  const plan: Plan = { kind: "advance", to, effects, why: `${child.id} ended at ${child.state}` };
  return Object.assign(plan, { [RETURNED]: child.id });
}

/** The child's plan as its caller's engine runs it: a look that stays where the caller is. */
function carried(child: WorkRecord, inner: Plan): Plan {
  // A settled child is passed up as it said it, so a decision nobody has
  // written yet (`notWritten`) still reads as one through its caller.
  if (inner.kind === "settled") return inner;
  const why = `${child.id}: ${inner.why}`;
  const plan: Plan = inner.kind === "wait"
    ? { kind: "wait", retryAfterMs: inner.retryAfterMs, effects: inner.effects, why }
    : { kind: "act", effects: inner.effects, why, attempt: false };
  // A lane's move stays a lane's through every caller that carries it.
  const lane = laneOf(inner);
  return Object.assign(plan, { [INNER]: inner }, lane === undefined ? {} : { [LANE]: lane });
}

/** The lane a plan moves, when it is a lane's move: what an engine keeps a lane's own accounts by. */
export function laneMoved(plan: Plan): string | undefined {
  return laneOf(plan);
}

function childObservation(observation: unknown): unknown {
  return (observation as Record<string, unknown> | undefined)?.[CALLED];
}

function laneObservation(observation: unknown, lane: string): unknown {
  return ((observation as Record<string, unknown> | undefined)?.[LANED] as Record<string, unknown> | undefined)?.[lane];
}

/**
 * The next move of a record waiting in a fork: start the lanes, move the
 * lane whose turn it is, or go to the join once every lane has ended.
 *
 * One move per look, as anywhere else. A lane that waits gives its turn to
 * the next, so a lane that escalates never holds its siblings up; only when
 * every lane still running waits does the record wait, saying which lanes
 * have arrived and which one needs the person.
 */
function forkPlan(fork: ForkSite, record: WorkRecord, observation: unknown): Plan {
  if (!started(fork, record)) {
    return Object.assign({ kind: "act", effects: [], why: `${record.id} starts the lanes of ${fork.state}`, attempt: false } as Plan, { [ENTER_FORK]: true });
  }
  const running = inTurn(fork, record);
  if (running.length === 0) return joined(fork, record);
  const moves = running.map((site) => laneMove(site, record, observation));
  // A lane whose decision is not written yet settles; its siblings still
  // move, and the record settles on it only once nothing else can.
  const moving = moves.find((move) => move.kind !== "wait" && move.kind !== "settled");
  if (moving) return moving;
  const settled = moves.find((move) => move.kind === "settled");
  if (settled) return settled;
  const soonest = Math.min(...moves.map((move) => (move.kind === "wait" ? move.retryAfterMs : 0)));
  const first = moves[0] as Extract<Plan, { kind: "wait" }>;
  return Object.assign({ ...first, retryAfterMs: soonest, why: `every lane of ${fork.state} waits — ${arrivals(fork, record, moves)}` }, { [LANE]: laneOf(first), [INNER]: innerOf(first) });
}

/**
 * Every move the lanes can make on this look — of the fork the record waits
 * in, or of one inside the call it is in, at any depth — or undefined when
 * there are not two, or the workflow has something to say first.
 */
function everyLaneThrough(
  own: Workflow,
  sites: ReadonlyMap<string, CallSite>,
  forks: ReadonlyMap<string, ForkSite>,
  record: WorkRecord,
  observation: unknown,
  policy: unknown,
): readonly Plan[] | undefined {
  if (forks.has(record.state)) {
    return own.interrupt?.(record, ownObservation(observation), policy) ? undefined : everyLane(forks, record, observation);
  }
  const site = callAt(sites, forks, record.state);
  const child = activeCall(record);
  if (!site || !child || site.workflow.terminalStates.includes(child.state)) return undefined;
  const moves = site.workflow.everyLane?.(child, childObservation(observation), site.runtime?.policy ?? site.policy);
  return moves?.map((move) => carried(child, move));
}

/** The caller's own world in a fork's observation — which, once every lane has ended, is all it holds. */
function ownObservation(observation: unknown): unknown {
  const held = observation as Record<string, unknown> | undefined;
  return held && Object.hasOwn(held, OWN) ? held[OWN] : observation;
}

/** Every move the lanes of a fork can make on this look, one per lane that is not waiting, for an engine that moves them side by side. */
function everyLane(forks: ReadonlyMap<string, ForkSite>, record: WorkRecord, observation: unknown): readonly Plan[] | undefined {
  const fork = forks.get(record.state);
  if (!fork || !started(fork, record)) return undefined;
  const moves = inTurn(fork, record).map((site) => laneMove(site, record, observation));
  const moving = moves.filter((move) => move.kind !== "wait" && move.kind !== "settled");
  return moving.length > 1 ? moving : undefined;
}

/** One lane's own plan, as its caller's engine runs it, every action on it marked as the lane's. */
function laneMove(site: CallSite, record: WorkRecord, observation: unknown): Plan {
  const child = laneRecord(record, site.state)!;
  const inner = site.workflow.plan(child, laneObservation(observation, site.state), site.runtime?.policy ?? site.policy);
  const plan = carried(child, inner);
  if (plan.kind === "settled") return plan;
  const effects = plan.effects.map((effect) => Object.assign({ ...effect }, { [LANE_PATH]: [site.state, ...(lanePathOf(effect) ?? [])] }));
  return Object.assign({ ...plan, effects }, { [INNER]: inner, [LANE]: site.state });
}

/** The move to the join, carrying what each lane's binding says on the way out. */
function joined(fork: ForkSite, record: WorkRecord): Plan {
  const effects: Action[] = [];
  const ends: string[] = [];
  for (const site of fork.lanes) {
    const child = laneRecord(record, site.state)!;
    ends.push(`${site.state} at ${child.state}`);
    const say = (site.binding.effects as Record<string, ((work: WorkRecord, out: unknown) => Action[]) | undefined> | undefined)?.[child.state];
    if (say) effects.push(...say(record, site.output(child)));
  }
  const plan: Plan = { kind: "advance", to: fork.join, effects, why: `every lane of ${fork.state} has ended: ${ends.join(", ")}` };
  return Object.assign(plan, { [JOINED]: fork.state });
}

/** Which lanes have arrived, and what each one still running is waiting on. */
function arrivals(fork: ForkSite, record: WorkRecord, moves: readonly Plan[]): string {
  const ended = fork.lanes.filter((site) => hasEnded(site, laneRecord(record, site.state)));
  const arrived = `${ended.length} of ${fork.lanes.length} arrived${ended.length > 0 ? ` (${ended.map((site) => site.state).join(", ")})` : ""}`;
  const waiting = moves.map((move) => {
    const site = fork.lanes.find((candidate) => candidate.state === laneOf(move))!;
    const child = laneRecord(record, site.state)!;
    // Read at the lane's deepest record, as `laneStanding` reads it.
    const attention = callStanding(site.workflow, child).attention;
    return `${site.state} ${attention ? "needs the person" : "waits"} in ${child.state}`;
  });
  return [arrived, ...waiting].join("; ");
}

function lanePathOf(action: object): readonly string[] | undefined {
  const path = (action as { [LANE_PATH]?: readonly string[] })[LANE_PATH];
  return path && path.length > 0 ? path : undefined;
}

/** The action as the lane's own workflow runs it: the lanes inside it, if any, still marked. */
function inTheLane(action: Action): Action {
  const [, ...rest] = lanePathOf(action) ?? [];
  return Object.assign({ ...action }, { [LANE_PATH]: rest });
}

function laneOf(value: object): string | undefined {
  return (value as { [LANE]?: string })[LANE];
}

function innerOf(plan: Plan): Plan | undefined {
  return (plan as Plan & { [INNER]?: Plan })[INNER];
}

function returnedFrom(plan: Plan): string | undefined {
  return (plan as Plan & { [RETURNED]?: string })[RETURNED];
}

/**
 * The caller's runtime, with each call state observed, acted on and folded
 * through its callee's.
 *
 * Only the deepest record is observed: a caller in a call state is not asked
 * what its world looks like until its child has ended, and a child that has
 * ended is not asked at all, because the next move is its caller's return.
 */
export function composedRuntime(own: WorkflowRuntime, sites: ReadonlyMap<string, CallSite>, port: PortLookup, forks: ReadonlyMap<string, ForkSite> = new Map()): WorkflowRuntime {
  if (sites.size === 0) return own;
  const siteOf = (record: WorkRecord): CallSite | undefined => callAt(sites, forks, record.state);
  const runtimeOf = (site: CallSite): WorkflowRuntime => {
    if (!site.runtime) throw new Error(`the call in \`${site.state}\` to ${site.callee} was never built`);
    return site.runtime;
  };

  return {
    ...own,
    found: async () => {
      const delegated = [...sites.values()].filter((site) => site.binding.discover);
      const found = await Promise.all([own.found(), ...delegated.map((site) => runtimeOf(site).found())]);
      return found.flat();
    },
    newRecord: (workId, now) => {
      const record = own.newRecord(workId, now);
      const site = siteOf(record);
      return site ? enterCall(record, site, now) : record;
    },
    observe: async (record) => {
      if (record.abandoned?.length) await returnTreesOf(record.abandoned, port("worktree") as Worktree | undefined);
      const fork = forks.get(record.state);
      if (fork) return observeFork(own, fork, record, runtimeOf, port);
      const site = siteOf(record);
      // Looked at again only when its child has ended: that look is the
      // caller's return, and it is the caller's world it returns into.
      const child = site ? activeCall(record) : undefined;
      if (!site || (child && site.workflow.terminalStates.includes(child.state))) return own.observe(record);
      if (!child) return { [CALLED]: undefined };
      return { [CALLED]: await runtimeOf(site).observe(child) };
    },
    actions: composedActions(own, sites, port, forks),
    apply: (looked, plan, outcomes, observation, now, moved) => {
      // The look that folds this has already given the abandoned lanes' trees back.
      const { abandoned: _given, ...record } = looked;
      const inner = innerOf(plan);
      const lane = laneOf(plan);
      const fork = forks.get(record.state);
      if (fork && (plan as Plan & { [ENTER_FORK]?: true })[ENTER_FORK]) return enterFork(record, fork, now);
      if (fork && lane && inner) return foldedLane(record, fork, lane, runtimeOf, inner, outcomes, laneObservation(observation, lane), now);
      const site = siteOf(record);
      if (site && (plan as Plan & { [ENTER]?: true })[ENTER]) return enterCall(record, site, now);
      if (inner && site) return folded(record, site, runtimeOf(site), inner, outcomes, childObservation(observation), now);
      return ownMove(own, sites, forks, { record, plan, outcomes, observation, now, moved });
    },
  };
}

/**
 * A move the caller makes itself: back from a call, on from the join, or out
 * of a fork interrupted before its lanes met — whose lanes still running stop
 * where they are and let go of the branches they held.
 */
function ownMove(
  own: WorkflowRuntime,
  sites: ReadonlyMap<string, CallSite>,
  forks: ReadonlyMap<string, ForkSite>,
  look: { record: WorkRecord; plan: Plan; outcomes: Record<string, unknown>; observation: unknown; now: Date; moved: Moved | null },
): WorkRecord {
  const { record, plan, outcomes, now, moved } = look;
  const id = returnedFrom(plan);
  const from = (plan as Plan & { [JOINED]?: string })[JOINED];
  const left = moved ? forks.get(moved.from) : undefined;
  const abandoned = left && from === undefined ? abandon(left, record) : undefined;
  const base = abandoned ? { ...record, abandoned } : record;
  const kept = id !== undefined ? returnTo(base, sites, id, moved) : from !== undefined ? joinedInto(base, forks.get(from)!) : base;
  // In or out of a fork, the caller folds its own world, not the lanes'.
  const observation = left || forks.has(record.state) ? ownObservation(look.observation) : look.observation;
  return entering(own.apply(kept, plan, outcomes, observation, now, moved), sites, forks, moved, now);
}

/**
 * The lanes of a fork left other than through its join: what they held goes
 * back now, and the trees they were lent on the record's next look.
 */
function abandon(fork: ForkSite, record: WorkRecord): string[] {
  const ids = fork.lanes.map((site) => record.lanes?.[site.state]?.call).filter((id): id is string => id !== undefined);
  for (const id of ids) {
    fork.leases?.release(id);
    fork.lent?.delete(id);
  }
  return ids;
}

/**
 * What a record waiting in a fork is shown: each running lane's own world,
 * by lane — or, once every lane has ended, the caller's, since that look is
 * its move to the join. The trees the lanes were lent go back then.
 */
async function observeFork(
  own: WorkflowRuntime,
  fork: ForkSite,
  record: WorkRecord,
  runtimeOf: (site: CallSite) => WorkflowRuntime,
  port: PortLookup,
): Promise<unknown> {
  if (!started(fork, record)) return { [LANED]: {}, [OWN]: await own.observe(record) };
  const running = inTurn(fork, record);
  if (running.length === 0) {
    await returnTrees(fork, record, port("worktree") as Worktree | undefined);
    return own.observe(record);
  }
  // Lent before anything looks: a lane reads its tree at its commit from its first observation on.
  for (const site of running) {
    const child = laneRecord(record, site.state)!;
    if (child.revision !== undefined) fork.lent?.set(child.id, child.revision);
  }
  const seen = await Promise.all(running.map(async (site) => [site.state, await runtimeOf(site).observe(laneRecord(record, site.state)!)] as const));
  // The caller's own world too, so what it says before any decision — a
  // ticket that left the working status — is heard while its lanes run.
  return { [LANED]: Object.fromEntries(seen), [OWN]: await own.observe(record) };
}

/**
 * Removes the trees the lanes of an ended fork were lent. A lane checks; it
 * keeps nothing in its tree worth keeping once it has ended, and a fork run
 * every round would otherwise leave two trees behind each time.
 */
async function returnTrees(fork: ForkSite, record: WorkRecord, worktree: Worktree | undefined): Promise<void> {
  const ids = fork.lanes.map((site) => record.lanes?.[site.state]?.call).filter((id): id is string => id !== undefined);
  await returnTreesOf(ids, worktree);
}

/** Removes the trees lent to these lane records, if any were. */
async function returnTreesOf(ids: readonly string[], worktree: Worktree | undefined): Promise<void> {
  if (!worktree || ids.length === 0) return;
  const lanes = new Set(ids);
  for (const tree of await worktree.states()) {
    if (lanes.has(tree.workId)) await worktree.release(tree.workId, tree.repo, { force: true });
  }
}

/** One look of a lane, folded into its own record; a lane that has ended lets go of the branches it held. */
function foldedLane(
  record: WorkRecord,
  fork: ForkSite,
  lane: string,
  runtimeOf: (site: CallSite) => WorkflowRuntime,
  inner: Plan,
  outcomes: Record<string, unknown>,
  observation: unknown,
  now: Date,
): WorkRecord {
  const site = fork.lanes.find((candidate) => candidate.state === lane)!;
  const child = laneRecord(record, lane)!;
  // A lane that waited on a branch made no move, whatever its plan said:
  // it looked, it stays where it is, and nothing it planned is folded.
  if (outcomes[LEASE_WAIT]) {
    const waited: Plan = { kind: "wait", retryAfterMs: LEASE_WAIT_MS, effects: [], why: "waiting on a branch another lane holds" };
    return { ...record, calls: { ...record.calls, [child.id]: applyPlan(child, waited, now) } };
  }
  const next = runtimeOf(site).apply(applyPlan(child, inner, now, outcomes), inner, outcomes, observation, now, movedBy(child, inner));
  // Every branch the lane took goes back with it, those its own calls took included.
  if (hasEnded(site, next)) {
    fork.leases?.release(next.id);
    fork.lent?.delete(next.id);
  }
  return { ...record, calls: { ...record.calls, [next.id]: next } };
}

/**
 * The caller at its join, holding where each lane ended and what it
 * returned, keyed by lane, with each binding's fold applied in the order the
 * lanes are drawn.
 */
function joinedInto(record: WorkRecord, fork: ForkSite): WorkRecord {
  let kept = record;
  const lanes: Record<string, Lane> = {};
  for (const site of fork.lanes) {
    const child = laneRecord(record, site.state)!;
    const output = site.output(child);
    lanes[site.state] = { call: child.id, end: child.state, ...(output === undefined ? {} : { output }) };
    const fold = (site.binding.output as Record<string, ((work: WorkRecord, out: unknown) => WorkRecord) | undefined> | undefined)?.[child.state];
    if (fold) kept = fold(kept, output);
  }
  return { ...kept, lanes };
}

/** One look of the child, folded into its own record and kept inside its caller's. */
function folded(
  record: WorkRecord,
  site: CallSite,
  runtime: WorkflowRuntime,
  inner: Plan,
  outcomes: Record<string, unknown>,
  observation: unknown,
  now: Date,
): WorkRecord {
  const id = record.calling!;
  const child = record.calls![id]!;
  const next = runtime.apply(applyPlan(child, inner, now, outcomes), inner, outcomes, observation, now, movedBy(child, inner));
  return { ...record, calls: { ...record.calls, [id]: next } };
}

/** The caller, holding what the child returned, and waiting on nothing. */
function returnTo(record: WorkRecord, sites: ReadonlyMap<string, CallSite>, id: string, moved: Moved | null): WorkRecord {
  const site = moved ? sites.get(moved.from) : undefined;
  const child = record.calls?.[id];
  if (!site || !child) return record;
  const fold = (site.binding.output as Record<string, ((work: WorkRecord, out: unknown) => WorkRecord) | undefined> | undefined)?.[child.state];
  const kept = fold ? fold(record, site.output(child)) : record;
  const { calling: _calling, ...rest } = kept;
  return rest as WorkRecord;
}

function entering(record: WorkRecord, sites: ReadonlyMap<string, CallSite>, forks: ReadonlyMap<string, ForkSite>, moved: Moved | null, now: Date): WorkRecord {
  if (!moved || record.state !== moved.to) return record;
  const fork = forks.get(moved.to);
  if (fork) return enterFork(record, fork, now);
  const site = sites.get(moved.to);
  return site ? enterCall(record, site, now) : record;
}

/**
 * Every action the caller or any callee can plan, each run against the
 * record whose plan carried it.
 *
 * Two workflows may well name an action the same — both announce — so a name
 * a callee plans is a dispatcher that asks whose look this is. One only the
 * caller plans is left exactly as the caller declared it.
 */
function composedActions(own: WorkflowRuntime, sites: ReadonlyMap<string, CallSite>, port: PortLookup, forks: ReadonlyMap<string, ForkSite>): Readonly<Record<string, ActionImplementation>> {
  // In a fork, the caller's own actions — whatever its `interrupt` planned —
  // see the caller's world, not the lanes' it is wrapped in.
  // A port and a method never reads the world, so it is left as declared.
  const actions: Record<string, ActionImplementation> = forks.size === 0 ? { ...own.actions } : Object.fromEntries(
    Object.entries(own.actions).map(([name, implementation]) => [name, isPortBinding(implementation) ? implementation : ownInAFork(own, name, port, forks)]),
  );
  const names = new Set<string>();
  for (const site of sites.values()) for (const name of Object.keys(site.runtime?.actions ?? {})) names.add(name);
  // A lane's action runs against the lane's record, never the caller's, so it
  // is always dispatched rather than handed to the port as declared.
  const laned = new Set([...forks.values()].flatMap((fork) => fork.lanes.flatMap((site) => Object.keys(site.runtime?.actions ?? {}))));
  for (const name of names) {
    const shared = laned.has(name) ? undefined : sharedBinding(own, sites, name);
    if (shared) {
      actions[name] = shared;
      continue;
    }
    actions[name] = reaching(async (action: Action, context: ActionContext) => {
      const lane = lanePathOf(action)?.[0];
      const fork = forks.get(context.record.state);
      if (fork && lane) return laneAction(fork, lane, name, action, context);
      const site = sites.get(context.record.state);
      const child = activeCall(context.record);
      // A child that has ended plans nothing: what runs now is its caller's
      // return, and the effects on that edge are the caller's own.
      const ended = !child || !site || site.workflow.terminalStates.includes(child.state);
      if (!site?.runtime || ended) return runAction(implementationOf(own, name), action, { ...context, observation: forks.has(context.record.state) ? ownObservation(context.observation) : context.observation }, port);
      const observation = childObservation(context.observation);
      await runAction(implementationOf(site.runtime, name), action, { record: child, observation, outcomes: context.outcomes }, site.port);
    }, laneSpends(forks, name) ?? spentThroughEveryCall(own, sites, name));
  }
  return actions;
}

/**
 * The port a lane's action spends, when every lane declaring it binds it to
 * the same one: the dispatcher still says so, so the budget is asked before
 * a lane spends the agent as before any other move.
 */
function laneSpends(forks: ReadonlyMap<string, ForkSite>, name: string): ActionSpec | undefined {
  return agreed([...forks.values()].flatMap((fork) => fork.lanes.flatMap((site) => {
    const implementation = site.runtime && implementationOf(site.runtime, name);
    return implementation === undefined ? [] : [bindingThrough(site, implementation)];
  })));
}

/** What a callee's declared binding is, as its caller's ports name it. */
function bindingThrough(site: CallSite, implementation: unknown): ActionSpec | undefined {
  const bound = declaredBinding(implementation);
  return bound && { ...bound, port: site.binding.ports?.[bound.port] ?? bound.port };
}

/** The one binding every declaration agrees on, or none when any differs or runs none. */
function agreed(bindings: readonly (ActionSpec | undefined)[]): ActionSpec | undefined {
  const [first] = bindings;
  if (!first || bindings.length === 0) return undefined;
  return bindings.every((binding) => binding?.port === first.port && binding.method === first.method) ? first : undefined;
}

/** The caller's own action, handed its own world while the record waits in a fork. */
function ownInAFork(own: WorkflowRuntime, name: string, port: PortLookup, forks: ReadonlyMap<string, ForkSite>): ActionImplementation {
  const implementation = implementationOf(own, name)!;
  return async (action: Action, context: ActionContext) => {
    const observation = forks.has(context.record.state) ? ownObservation(context.observation) : context.observation;
    await runAction(implementation, action, { ...context, observation }, port);
  };
}

/**
 * The port an action spends when every workflow declaring it — the caller and
 * each callee, through its binding's ports — spends the same one, however it
 * is dispatched: a callee whose lanes run it still says so to whoever calls it.
 */
function spentThroughEveryCall(own: WorkflowRuntime, sites: ReadonlyMap<string, CallSite>, name: string): ActionSpec | undefined {
  const mine = implementationOf(own, name);
  return agreed([
    ...(mine === undefined ? [] : [declaredBinding(mine)]),
    ...[...sites.values()].flatMap((site) => {
      const implementation = site.runtime && implementationOf(site.runtime, name);
      return implementation === undefined ? [] : [bindingThrough(site, implementation)];
    }),
  ]);
}

/**
 * One action of one lane, run against the lane's own record and world.
 *
 * A lane that asks for a branch another lane holds has not tried anything:
 * the look is written down as one that waited, and the rest of the lane's
 * plan is not run on top of a branch it never got.
 */
async function laneAction(fork: ForkSite, lane: string, name: string, action: Action, context: ActionContext): Promise<void> {
  if (context.outcomes[LEASE_WAIT]) return;
  const site = fork.lanes.find((candidate) => candidate.state === lane)!;
  const child = laneRecord(context.record, lane)!;
  if (child.revision !== undefined) fork.lent?.set(child.id, child.revision);
  try {
    await runningLane.run(child.id, () =>
      runAction(implementationOf(site.runtime!, name), inTheLane(action), { record: child, observation: laneObservation(context.observation, lane), outcomes: context.outcomes }, site.port));
  } catch (error) {
    if (!(error instanceof LeaseHeld)) throw error;
    context.outcomes[LEASE_WAIT] = { notATry: true, retryAfterMs: LEASE_WAIT_MS, held: error.message };
  }
}

/**
 * The port and method every workflow in a call declares for an action, when
 * they all declare the same one and no call rebinds that port: kept as it is
 * rather than wrapped, so the engine can still read what it reaches — the
 * budget asks whether an action spends the agent by the binding it declares.
 */
function sharedBinding(own: WorkflowRuntime, sites: ReadonlyMap<string, CallSite>, name: string): ActionImplementation | undefined {
  const declared = [own, ...[...sites.values()].map((site) => site.runtime!)]
    .map((runtime) => implementationOf(runtime, name))
    .filter((implementation) => implementation !== undefined);
  const [first] = declared;
  if (!isPortBinding(first)) return undefined;
  const same = declared.every((implementation) => isPortBinding(implementation) && implementation.port === first.port && implementation.method === first.method);
  const rebound = [...sites.values()].some((site) => site.binding.ports?.[first.port] !== undefined);
  return same && !rebound ? first : undefined;
}

import { ConfigSchema } from "./config-schema.js";
import { Workspace } from "./ports/Workspace.js";
import { Git, RepoLayout } from "./git.js";
import { CommandRunner } from "./ports/CommandRunner.js";
import { Worktree } from "./ports/Worktree.js";

/**
 * The two branch settings, with the one description they have.
 *
 * A plugin that needs a repository's base spreads these into its own schema.
 * The settings stay the plugin's own — every existing `config.yaml` names
 * them per plugin — but what they mean is written once, here, so seven
 * schemas cannot describe one fact seven ways.
 */
export const BRANCH_SETTINGS = {
  defaultBranch: {
    type: "string",
    description: "the branch new work is cut from, for a repository that named none, which is not always `main`",
    default: "main",
  },
  baseBranch: {
    type: "record",
    description:
      "where one repository's base branch is, instead of the fallback. A repository named here has its work cut from, and its pull requests opened against, that branch",
    default: {},
  },
} as const satisfies ConfigSchema;

/** What the host lends a plugin that works in a repository's checkout. */
export interface Checkouts {
  /** Where the work happens and how it gets onto its branch. */
  readonly git: Git;
  /**
   * The same layout, for the question `Git` does not answer: what a pull
   * request opens against. Ask `baseBranchFor(layout, repo)`.
   */
  readonly layout: RepoLayout;
}

/**
 * The checkouts one plugin works in: the host's paths, the plugin's own branch
 * settings, and the worktree port read each time a path is asked for.
 *
 * A plugin that declared no `defaultBranch` gets the shared setting's default,
 * which is what it would have been handed had it spread `BRANCH_SETTINGS`.
 */
export function checkoutsFromWorkspace(
  runner: CommandRunner,
  workspace: Workspace,
  config: Readonly<Record<string, unknown>>,
  worktree: () => Worktree | undefined,
): Checkouts {
  return lendCheckouts(runner, {
    workspaceRoot: workspace.workspaceRoot,
    checkouts: workspace.checkouts,
    defaultBranch: defaultBranchOf(config),
    baseBranch: baseBranchesOf(config),
  }, worktree);
}

/**
 * The checkouts a plugin or workflow asks for, answered when they are read.
 *
 * The workspace is looked up on the first read, so building a runtime never
 * asks for the workplace by itself: a workflow that never reads its
 * checkouts mounts on an install that carries none, and one that reads is
 * refused by `refuse`, which says who asked and what to add. The answer is
 * held once taken, so every read after the first sees the same workplace.
 */
export function lentWhenRead(resolve: () => Checkouts): Checkouts {
  let taken: Checkouts | undefined;
  const once = (): Checkouts => {
    if (!taken) taken = resolve();
    return taken;
  };
  return {
    get git() {
      return once().git;
    },
    get layout() {
      return once().layout;
    },
  };
}

/**
 * The checkouts for a layout already in hand.
 *
 * What `PluginContext.checkouts()` answers with, exported for a test that
 * drives a port without mounting it. A plugin asks its context instead: the
 * architecture test refuses this, and `new Git`, anywhere outside the core's
 * own source.
 */
export function lendCheckouts(
  runner: CommandRunner,
  layout: RepoLayout,
  worktree?: Worktree | (() => Worktree | undefined),
): Checkouts {
  return { git: new Git(runner, layout, worktree), layout };
}

function defaultBranchOf(config: Readonly<Record<string, unknown>>): string {
  const value = config.defaultBranch;
  if (value === undefined) return BRANCH_SETTINGS.defaultBranch.default;
  if (typeof value !== "string") throw new Error(`\`defaultBranch\` must be a branch name, not ${JSON.stringify(value)}`);
  return value;
}

/**
 * The one place `baseBranch`, validated only as a record, is narrowed to
 * names. A plugin that takes the map in its own slice reads it through this,
 * so a value that is not a branch name is refused at boot rather than sent.
 */
export function baseBranchesOf(config: Readonly<Record<string, unknown>>): Readonly<Record<string, string>> | undefined {
  const value = config.baseBranch;
  if (value === undefined) return undefined;
  if (value === null || typeof value !== "object" || Array.isArray(value)) {
    throw new Error(`\`baseBranch\` must map repositories to branch names, not ${JSON.stringify(value)}`);
  }
  for (const [repo, branch] of Object.entries(value)) {
    if (typeof branch !== "string") {
      throw new Error(`\`baseBranch\` names ${JSON.stringify(branch)} for \`${repo}\`, which is not a branch name`);
    }
  }
  return value as Readonly<Record<string, string>>;
}

import { PortKind } from "./actions.js";
import { CommandRunner } from "./ports/CommandRunner.js";

/**
 * What a command writes to. The host owns the terminal; a command says what
 * it found and never decides how it is drawn.
 */
export interface CommandOutput {
  line(text?: string): void;
  error(text: string): void;
}

/**
 * What a command is handed: the profile's state directory, its own settings
 * and nothing else.
 *
 * Deliberately not the mounted machine. A command exists for the moment the
 * machine will not come up — `amy doctor` after a bad upgrade, `amy add` on a
 * bare install — so a command that needed a port to say what is wrong would
 * only speak on the machines that do not need it. A command declared
 * `mount: true` asks for the ports and is refused, by name, when the machine
 * will not assemble.
 */
export interface CommandContext<Settings extends Record<string, unknown> = Record<string, unknown>> {
  /** The profile's state directory: everything a plugin owns lives under it. */
  readonly state: string;
  /**
   * The machine's state root.
   *
   * For the one file that is nobody's profile: `amy models` reads the price
   * table every agent call shares, and a table per profile would mean one
   * machine holding several answers to what a model costs.
   */
  readonly home: string;
  /** This plugin's settings slice, validated the way a mount's are. */
  readonly settings: Settings;
  readonly args: readonly string[];
  readonly options: Readonly<Record<string, string | boolean | undefined>>;
  readonly out: CommandOutput;
  /** The mounted ports, for a command declared `mount: true`. */
  readonly ports?: ReadonlyMap<PortKind, object>;
}

/** A positional argument a command accepts, in the order it is typed. */
export interface CommandArgument {
  readonly name: string;
  readonly description?: string;
  readonly optional?: boolean;
  readonly variadic?: boolean;
}

/** A flag a command accepts, written the way the help prints it. */
export interface CommandFlag {
  readonly flags: string;
  readonly description?: string;
  readonly default?: string;
}

/**
 * A command a plugin brings.
 *
 * Plain data read after the module is imported: the host lists it in
 * `amy --help`, parses it, and hands it a directory. The plugin decides what
 * the command means; the host decides nothing about it.
 */
export interface PluginCommand<Settings extends Record<string, unknown> = Record<string, unknown>> {
  readonly name: string;
  readonly description: string;
  readonly args?: readonly CommandArgument[];
  readonly flags?: readonly CommandFlag[];
  /** Subcommands, one of which may be the default when none is typed. */
  readonly subcommands?: readonly PluginCommand<Settings>[];
  /** The subcommand `amy <name>` means when no subcommand is given. */
  readonly default?: boolean;
  /** Whether running it needs the mounted ports, rather than only this directory. */
  readonly mount?: boolean;
  /** Absent on a command that only groups subcommands. */
  run?(ctx: CommandContext<Settings>): void | Promise<void>;
}

/** The host's own check, so a plugin's red one fails the doctor the same way. */
export interface Check {
  label: string;
  ok: boolean;
  detail?: string;
}

/** What a check is handed: the same directories, settings and output a command gets. */
export type CheckContext<Settings extends Record<string, unknown> = Record<string, unknown>> =
  Pick<CommandContext<Settings>, "state" | "home" | "settings" | "out">;

/** A check a plugin brings, run by `amy doctor` after the host's own. */
export interface PluginCheck<Settings extends Record<string, unknown> = Record<string, unknown>> {
  readonly name: string;
  run(ctx: CheckContext<Settings>): Check | Promise<Check>;
}

/**
 * What a setup is handed: what a check gets, and a way to run a command.
 *
 * A setup prepares something outside amy's own state — another program's
 * profile, say — so unlike a check it is expected to run commands.
 */
export type SetupContext<Settings extends Record<string, unknown> = Record<string, unknown>> =
  CheckContext<Settings> & { readonly runner: CommandRunner };

/**
 * Something a plugin prepares outside amy's state, run by `amy init` and
 * `amy add` after the files.
 *
 * Run every time, so it must find what an earlier run made and leave it
 * alone: what is already there belongs to whoever edited it. It answers the
 * way a check does, and its own doctor check is how a later drift is told.
 */
export interface PluginSetup<Settings extends Record<string, unknown> = Record<string, unknown>> {
  readonly name: string;
  run(ctx: SetupContext<Settings>): Check | Promise<Check>;
}

/**
 * A file a plugin wants written, relative to the profile's state directory.
 *
 * Written by `amy init` and `amy add` and never overwritten: what is already
 * there belongs to whoever edited it.
 */
export interface PluginFile<Settings extends Record<string, unknown> = Record<string, unknown>> {
  readonly path: string;
  readonly content: string | ((settings: Settings) => string);
}

export type ConfigFieldType = "string" | "number" | "boolean" | "string[]" | "record";

type ConfigValueFor<T extends ConfigFieldType> =
  T extends "string" ? string
    : T extends "number" ? number
      : T extends "boolean" ? boolean
        : T extends "string[]" ? string[]
          : Record<string, unknown>;

/** One field, coupled to the value type it promises at boot. */
export type ConfigField = {
  [T in ConfigFieldType]: {
    readonly type: T;
    /** What the field is for. Printed when the field is missing or wrong. */
    readonly description: string;
    readonly required?: boolean;
    readonly default?: ConfigValueFor<T>;
    /**
     * A value the plugin would mount with, never applied to a config.
     *
     * For a required field the plugin checks beyond its type — an id that has
     * to look like an id — so the reference docs can ask the plugin what it
     * mounts without handing it a blank it rightly refuses.
     */
    readonly example?: unknown;
  };
}[ConfigFieldType];

/**
 * What one plugin says its configuration looks like.
 *
 * Declared by the plugin rather than known by the host, because the host has
 * no business knowing that a tracker has a status name or that a notifier has
 * a channel. Kept to five types on purpose: a plugin that needs more shape
 * than this wants its own validation, not a bigger schema language here.
 *
 * A key may be dotted, and a dotted key is how a group of settings one plugin
 * owns is described one setting at a time: `policy.maxAttempts` says the
 * policy block carries a `maxAttempts` number, without the block collapsing
 * into one untyped `record` nobody can explain. The config file keeps writing
 * the group nested; the schema names every leaf it accepts.
 */
export type ConfigSchema = Record<string, ConfigField>;

/** The value one schema field promises after validation, by its required/default shape. */
export type ValueFor<Field extends ConfigField> = ConfigValueFor<Field["type"]> extends infer Value
  ? Field extends { readonly required: true }
    ? Value
    : Field extends { readonly default: infer Default }
      ? undefined extends Default ? Value | undefined : Value
      : Value | undefined
  : never;

/** One intersection piece a dotted schema key contributes to the plugin's config. */
type PieceOf<S extends ConfigSchema, K extends keyof S> = K extends `${infer Head}.${infer Rest}`
  ? Rest extends `${infer Inner}.${infer Tail}`
    ? { [H in Head]: RestPieceOf<Tail, Inner, ValueFor<S[K]>> }
    : { [H in Head]: { [L in Rest]: ValueFor<S[K]> } }
  : never;

/** The inner segments of a path of three or more, folded into nested groups.
 *
 * `Value` arrives as the field's validated value, not the schema's own
 * descriptor: the plugin reads a number where the schema declared one, not
 * the declaration itself. */
type RestPieceOf<Rest extends string, Head extends string, Value> = Rest extends `${infer Inner}.${infer Tail}`
  ? { [H in Head]: RestPieceOf<Tail, Inner, Value> }
  : { [H in Head]: { [L in Rest]: Value } };

type UnionToIntersection<U> = (U extends unknown ? (k: U) => void : never) extends (k: infer I) => void ? I : never;

/**
 * The post-validation shape a schema promises to its plugin.
 *
 * Undotted keys carry their own values; dotted keys meet as nested groups.
 * A key with no dots contributes `never` to the intersection, which is the
 * union's own identity, so a schema without dotted keys produces exactly
 * what it always produced.
 */
export type ConfigOf<S extends ConfigSchema> = {
  [K in keyof S as K extends `${string}.${string}` ? never : K]: ValueFor<S[K]>
} & UnionToIntersection<{ [K in keyof S]: K extends `${string}.${string}` ? PieceOf<S, K> : never }[keyof S]>;

export type ConfigResult =
  | { ok: true; config: Record<string, unknown> }
  | { ok: false; problems: string[] };

/**
 * Checks one plugin's configuration against what it declared.
 *
 * Names the plugin and the field in every problem, because "invalid config"
 * with nothing else in it is the error message that costs an hour. Reports
 * every problem rather than the first, so one boot fixes one round of edits.
 */
export function validateConfig(
  plugin: string,
  schema: ConfigSchema,
  value: unknown,
): ConfigResult {
  if (value !== undefined && !isRecord(value)) {
    return { ok: false, problems: [`${plugin}: configuration must be a mapping`] };
  }

  const given = value ?? {};
  const { own, groups, problems, config } = splitSchema(plugin, schema);

  acceptOwn(plugin, own, given, config, problems);

  for (const [head, leaves] of groups) {
    if (!Object.hasOwn(given, head)) {
      // An absent group is no different from an empty one: a leaf the schema
      // requires is still owed, named with the path it would have been
      // written at, and a group that requires nothing fills its defaults
      // where the plugin expects to read them.
      const owed = [...leaves.entries()].filter(([, spec]) => spec.required);
      if (owed.length > 0) {
        problems.push(
          ...owed.map(([leaf, spec]) => `${plugin}: \`${head}.${leaf}\` is required — ${spec.description}`),
        );
        continue;
      }
      const filled = fill(leaves);
      // A group whose every leaf is optional has nothing to fill in, and the
      // type the schema promised (the group is read without a guard) is
      // still owed: the plugin meets an empty mapping, not a missing one.
      config[head] = filled ?? emptyMapping();
      continue;
    }

    const givenHead = given[head];
    if (!isRecord(givenHead)) {
      problems.push(
        `${plugin}: \`${head}\` must be a mapping whose settings are ${[...leaves.keys()].map((leaf) => `\`${head}.${leaf}\``).join(", ")}, got ${describe(givenHead)}`,
      );
      continue;
    }

    const problemsInGroup = validateInto(plugin, head, leaves, givenHead, (filled) => {
      config[head] = filled;
    });
    problems.push(...problemsInGroup);
  }

  rejectUnknown(plugin, given, own, groups, problems);

  return problems.length > 0 ? { ok: false, problems } : { ok: true, config };
}

/** Splits a dotted schema into its own keys and per-group leaves. */
function splitSchema(
  plugin: string,
  schema: ConfigSchema,
): {
  own: { key: string; spec: ConfigField }[];
  groups: Map<string, Map<string, ConfigField>>;
  problems: string[];
  config: Record<string, unknown>;
} {
  const own: { key: string; spec: ConfigField }[] = [];
  const groups = new Map<string, Map<string, ConfigField>>();
  const problems: string[] = [];
  const config: Record<string, unknown> = {};
  for (const [key, spec] of Object.entries(schema)) {
    const [head, ...path] = key.split(".");
    if (path.length === 0) {
      own.push({ key, spec });
      continue;
    }
    if (head === undefined || head === "") {
      problems.push(`${plugin}: a schema key cannot begin with a dot`);
      continue;
    }
    let group = groups.get(head);
    if (!group) groups.set(head, (group = new Map()));
    group.set(path.join("."), spec);
  }
  return { own, groups, problems, config };
}

/** An empty mapping the validator hands the plugin where the schema promised a group. */
function emptyMapping(): Record<string, unknown> {
  return {};
}

/**
 * Accepts and checks the schema's own (undotted) keys against what the
 * machine wrote: required named when absent, defaults filled in, and any
 * value of the wrong shape named with the type it asked for.
 */
function acceptOwn(
  plugin: string,
  own: { key: string; spec: ConfigField }[],
  given: Record<string, unknown>,
  config: Record<string, unknown>,
  problems: string[],
): void {
  for (const { key, spec } of own) {
    const present = Object.hasOwn(given, key);
    if (!present) {
      if (spec.required) {
        problems.push(`${plugin}: \`${key}\` is required — ${spec.description}`);
      } else if (spec.default !== undefined) {
        config[key] = spec.default;
      }
      continue;
    }

    const supplied = given[key];
    if (!matches(spec.type, supplied)) {
      problems.push(
        `${plugin}: \`${key}\` must be ${spec.type}, got ${describe(supplied)} — ${spec.description}`,
      );
      continue;
    }

    config[key] = supplied;
  }
}

/**
 * An unknown key is almost always a typo in a field that matters, and
 * ignoring it means the setting silently never applied. A dotted schema
 * names its group's leaves, so anything the machine wrote that no dotted
 * path declares is refused with the path it was written at — including
 * levels inside a group, where a typo three segments deep must not fall
 * through to a silent default.
 */
function rejectUnknown(
  plugin: string,
  given: Record<string, unknown>,
  own: { key: string; spec: ConfigField }[],
  groups: Map<string, Map<string, ConfigField>>,
  problems: string[],
): void {
  for (const key of Object.keys(given)) {
    if (own.some(({ key: ownKey }) => ownKey === key)) continue;
    const leaves = groups.get(key);
    if (leaves === undefined) {
      problems.push(`${plugin}: \`${key}\` is not a setting this plugin has`);
      continue;
    }
    // A declared group still owes its given shape. Scalars and wrong shapes
    // are named by the group's own validator below; what is left to refuse
    // here is everything the settings carry that no declared path reaches.
    rejectOutsidePaths(plugin, key, given[key], [...leaves.keys()], [], problems);
  }
}

/** Refuses the names a group was given that its schema's paths do not reach.
 *
 * Every recursion level walks the leaves as they are spelled at that level —
 * `[...walked]` restarts, so a declared path's second segment is compared
 * with its own spelling, not with the path it sits under — while `full`
 * carries what the operator wrote, so a refusal names every segment it sat
 * at. */
function rejectOutsidePaths(
  plugin: string,
  head: string,
  value: unknown,
  declaredLeaves: readonly string[],
  full: string[],
  problems: string[],
): void {
  if (!isRecord(value)) return;
  const leaves = [...declaredLeaves];
  for (const name of Object.keys(value)) {
    const path = [head, ...full, name];
    const reaching = leaves.filter((leaf) => leaf === name || leaf.startsWith(name + "."));
    if (reaching.length === 0) {
      problems.push(`${plugin}: \`${path.join(".")}\` is not a setting this plugin has`);
      continue;
    }
    if (reaching.every((leaf) => leaf !== name)) {
      rejectOutsidePaths(
        plugin,
        head,
        value[name],
        reaching.map((leaf) => leaf.slice(name.length + 1)),
        [...full, name],
        problems,
      );
    }
  }
}

/**
 * Validates one given group of nested settings into its filled shape.
 *
 * `emit` receives the whole filled group even when a leaf misbehaved — a
 * group whose one leaf is wrong still carries the leaves that were right,
 * so one round of edits fixes one round of settings.
 */
function validateInto(
  plugin: string,
  head: string,
  leaves: ReadonlyMap<string, ConfigField>,
  given: Record<string, unknown>,
  emit: (filled: Record<string, unknown>) => void,
): string[] {
  const problems: string[] = [];
  const filled = fill(leaves) ?? {};

  for (const [path, spec] of leaves) {
    const at = path.split(".");
    let source: unknown = given;
    let where = head;
    let present = true;
    for (const segment of at) {
      if (!isRecord(source) || !Object.hasOwn(source, segment)) {
        present = false;
        break;
      }
      source = (source as Record<string, unknown>)[segment];
      where = `${where}.${segment}`;
    }

    if (present) {
      if (!matches(spec.type, source)) {
        problems.push(`${plugin}: \`${where}\` must be ${spec.type}, got ${describe(source)} — ${spec.description}`);
        continue;
      }
      leafSet(filled, at, source);
      continue;
    }
    if (spec.required) {
      problems.push(`${plugin}: \`${head}.${path}\` is required — ${spec.description}`);
    }
  }

  for (const key of Object.keys(given)) {
    const covered = [...leaves.keys()].some((leaf) => leaf === key || leaf.startsWith(`${key}.`));
    if (!covered) {
      problems.push(`${plugin}: \`${head}.${key}\` is not a setting this plugin has`);
    }
  }

  emit(filled);
  return problems;
}

/** The defaults a group's leaves fill in with, or nothing when none has one. */
function fill(leaves: ReadonlyMap<string, ConfigField>): Record<string, unknown> | undefined {
  const filled: Record<string, unknown> = {};
  for (const [path, spec] of leaves) {
    if (spec.default === undefined || spec.required) continue;
    leafSet(filled, path.split("."), spec.default);
  }
  return Object.keys(filled).length > 0 ? filled : undefined;
}

function leafSet(into: Record<string, unknown>, path: readonly string[], value: unknown): void {
  const [head, ...rest] = path;
  if (head === undefined) return;
  if (rest.length === 0) {
    into[head] = value;
    return;
  }
  const child = isRecord(into[head]) ? (into[head] as Record<string, unknown>) : (into[head] = {});
  leafSet(child, rest, value);
}

function matches(type: ConfigFieldType, value: unknown): boolean {
  switch (type) {
    case "string":
      return typeof value === "string";
    case "number":
      return typeof value === "number" && Number.isFinite(value);
    case "boolean":
      return typeof value === "boolean";
    case "string[]":
      return Array.isArray(value) && value.every((item) => typeof item === "string");
    case "record":
      return isRecord(value);
  }
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function describe(value: unknown): string {
  if (value === null) return "null";
  if (Array.isArray(value)) return "an array";
  return typeof value;
}

/**
 * The marker a deferred implementation carries.
 *
 * A global symbol rather than a module one, so a host that reads a plugin
 * without importing this module — the docs generator does — can still tell a
 * factory from the thing it builds.
 */
const DEFERRED = Symbol.for("amykit.deferred");

/**
 * An implementation the host builds once every plugin has registered.
 *
 * Explicit rather than "any function", because a contribution that is itself
 * a function is a legitimate thing to register.
 */
export interface Deferred<T extends object = object> {
  readonly [DEFERRED]: () => T;
}

/**
 * Registers `build` instead of what it returns.
 *
 * The host calls it once per mount, after every plugin has registered and
 * before any `ready`, so it may read any port or contribution regardless of
 * the order plugins are listed in. Whoever reads it receives the built object.
 */
export function deferred<T extends object>(build: () => T): Deferred<T> {
  return Object.freeze({ [DEFERRED]: build });
}

export function isDeferred(value: unknown): value is Deferred {
  return typeof value === "object" && value !== null && typeof (value as Record<symbol, unknown>)[DEFERRED] === "function";
}

/** The factory behind a deferred implementation. */
export function factoryOf<T extends object>(value: Deferred<T>): () => T {
  return value[DEFERRED];
}

import fs from "node:fs";
import nodePath from "node:path";
import { fileURLToPath } from "node:url";
import { Checkouts } from "./checkouts.js";
import { ActionSpec } from "./actions.js";
import { ActionDuties, actionPorts } from "./action-ports.js";
import { PluginCheck, PluginCommand, PluginFile, PluginSetup } from "./commands.js";
import { DIAGRAM_FILE, Diagram, readDiagram } from "./diagram.js";
import { ConfigOf, ConfigSchema, ValueFor, validateConfig } from "./config-schema.js";
import { Call, CallSite, ForkSite, Signature, composedRuntime, composedWorkflow, enterCall, isCall } from "./calls.js";
import { BranchLeases, FileLeases } from "./leases.js";
import { PortLookup } from "./dispatch.js";
import { deferred } from "./deferred.js";
import { Plugin, PluginContext, Registry, Workflow, ProjectPhases } from "./plugin.js";
import { WorkflowRuntime } from "./runtime.js";
import { Action, Moved, Plan, WorkRecord } from "./work.js";
import { ActionContext, ActionImplementation, FoundWork, ProgressPolicy } from "./runtime.js";
import { WORKFLOW_RUNTIME } from "./runtime.js";

const PORT_NEED = Symbol("workflow-port-need");

export interface PortNeed<T, Optional extends boolean = false> {
  readonly [PORT_NEED]: { readonly type: T; readonly optional: Optional; readonly requires?: readonly string[] };
}

/**
 * Declares a mounted port a workflow requires.
 *
 * `requires` names the methods a port only offers optionally that this
 * workflow calls, so a mounted adapter without one is refused at boot by
 * name rather than on the first piece of work that reaches it.
 */
export function port<T>(options: { readonly requires?: readonly (keyof T & string)[] } = {}): PortNeed<T> {
  const requires = options.requires ?? [];
  return Object.freeze({ [PORT_NEED]: { optional: false, ...(requires.length > 0 ? { requires: [...requires] } : {}) } }) as PortNeed<T>;
}

/** Declares a mounted port a workflow can use when present. */
export function optional<T>(): PortNeed<T, true> {
  return Object.freeze({ [PORT_NEED]: { optional: true } }) as PortNeed<T, true>;
}

type Needs = Readonly<Record<string, PortNeed<unknown, boolean>>>;
export type PortsOf<N extends Needs> = {
  readonly [K in keyof N]: N[K] extends PortNeed<infer T, true> ? T | undefined
    : N[K] extends PortNeed<infer T, false> ? T
      : never;
};

export type WorkflowRuntimeParts<R extends WorkRecord, O> = Omit<WorkflowRuntime<R, O>, "policy" | "newRecord">;

/** Everything an individual runtime piece can use, built once at mount. */
export type WorkflowPieceContext<S extends ConfigSchema, P extends object, N extends Needs> = {
  readonly ports: PortsOf<N>;
  readonly config: ConfigOf<S>;
  readonly policy: P;
  readonly checkouts: Checkouts;
  readonly ctx: PluginContext<ConfigOf<S>>;
};

/** One state-sized pure decision. */
export type WorkflowDecision<R extends WorkRecord, O, P, State extends string = string, Effect extends Action = Action> =
  (record: R, observation: O, policy: P) => Plan<State, Effect>;

/** What an action is handed: the mounted context, with its ports and duties bound to the work. */
export type WorkflowActionScope<S extends ConfigSchema, P extends object, N extends Needs> = WorkflowPieceContext<S, P, N> & ActionDuties;

/** One action implementation, with the mounted workflow context in front. */
export type WorkflowAction<S extends ConfigSchema, P extends object, N extends Needs, R extends WorkRecord, O, Effect extends Action = Action> = (
  scope: WorkflowActionScope<S, P, N>,
  work: ActionContext<R, O>,
  effect: Effect,
) => Promise<void>;

// The declaration accepts domain-narrowed handlers from `workflowActions()`
// while contextual typing an inline handler against the core's open Action.
// Method parameters are bivariant; the runtime adapter still owns the cast at
// the one point where a keyed handler is dispatched from an open action.
type DeclarationAction<S extends ConfigSchema, P extends object, N extends Needs, R extends WorkRecord, O> = {
  run(scope: WorkflowActionScope<S, P, N>, work: ActionContext<R, O>, effect: Action): Promise<void>;
}["run"];

/**
 * Contextually types each handler from its action's own payload.
 *
 * A workflow supplies its effect union once, and each key then receives only
 * the matching member instead of the core's deliberately open Action shape.
 */
export function workflowActions<Effect extends Action>() {
  return <S extends ConfigSchema, P extends object, N extends Needs, R extends WorkRecord, O>(
    actions: { readonly [Name in Effect["type"]]: WorkflowAction<S, P, N, R, O, Extract<Effect, { type: Name }>> },
  ) => actions;
}

type Claims<S extends ConfigSchema, P extends object> =
  | readonly string[]
  | ((args: { readonly config: ConfigOf<S>; readonly policy: P }) => readonly string[]);

export interface WorkflowPlugin<R extends WorkRecord = WorkRecord, O = unknown, P = unknown, I = unknown, Outs = Record<string, unknown>>
  extends Plugin, Signature<I, Outs> {
  /** Throws, naming why, when the workflow has no states: no diagram was read and none were declared. */
  readonly workflow: Workflow<O, P>;
  newRecord(workId: string, now: Date): R;
  /**
   * The project phases this workflow declared, readable without a mount:
   * the composition of a project reads these off the workflow its config
   * names, and `amy status` reads the mounted one's through the workflow.
   */
  readonly phases?: ProjectPhases;
}

// Registered rather than private: a workflow may be defined against another
// copy of the core than the host's, and the host still has to hand it its
// diagram.
const DRAW = Symbol.for("@amykit/core/workflow-draw");
/** What a caller reads off a declaration it calls: the declaration and its shape. */
const CALLEE = Symbol.for("@amykit/core/workflow-callee");

/** A declaration that can be handed the diagram the host found beside it. */
interface Drawable {
  readonly [DRAW]: (diagram: Diagram | Error) => Plugin;
}

/** The states, the initial one, and where work waits and ends, from the diagram or the declaration. */
interface Shape {
  readonly states: readonly string[];
  readonly initial: string;
  readonly waiting: readonly string[];
  readonly terminal: readonly string[];
  readonly diagram?: Diagram;
}

/** The four typed constructors a pure workflow plan returns. */
export function act<Effect extends Action>(why: string, ...effects: Effect[]): Extract<Plan<string, Effect>, { kind: "act" }>;
export function act<Effect extends Action>(why: string, options: { attempt: false }, ...effects: Effect[]): Extract<Plan<string, Effect>, { kind: "act" }>;
export function act<Effect extends Action>(
  why: string,
  ...rest: (Effect | { attempt: false })[]
): Extract<Plan<string, Effect>, { kind: "act" }> {
  return actOf(why, rest);
}

function actOf<Effect extends Action>(
  why: string,
  [first, ...rest]: (Effect | { attempt: false })[],
): Extract<Plan<string, Effect>, { kind: "act" }> {
  const notATry = !!first && !("type" in first) && first.attempt === false;
  const effects = (notATry || first === undefined ? rest : [first, ...rest]) as Effect[];
  return { kind: "act", effects, why, ...(notATry ? { attempt: false } : {}) };
}

export function advance<State extends string, Effect extends Action>(to: State, why: string, ...effects: Effect[]): Plan<State, Effect> {
  return { kind: "advance", to, effects, why };
}

export function wait<Effect extends Action>(retryAfterMs: number, why: string, ...effects: Effect[]): Extract<Plan<string, Effect>, { kind: "wait" }> {
  return { kind: "wait", retryAfterMs, why, effects };
}

export function settled(why: string): Extract<Plan, { kind: "settled" }> {
  return { kind: "settled", why };
}

export function planning<State extends string, Effect extends Action>() {
  // Written out rather than named, so a workflow re-exporting it can name it.
  const typedAct: {
    (why: string, ...effects: Effect[]): Plan;
    (why: string, options: { attempt: false }, ...effects: Effect[]): Plan;
  } = (why: string, ...rest: (Effect | { attempt: false })[]): Plan => actOf(why, rest);
  return {
    act: typedAct,
    advance: (to: State, why: string, ...effects: Effect[]): Plan => advance(to, why, ...effects),
    wait: (retryAfterMs: number, why: string, ...effects: Effect[]): Plan => wait(retryAfterMs, why, ...effects),
    settled,
  };
}

const NOT_WRITTEN = /^the decision for `([^`]+)` is not written yet$/;

/**
 * A decision nobody has written yet, for a state the diagram draws.
 *
 * It mounts, and on a look it settles the record saying so rather than
 * guessing a move, so a workflow imported from a diagram runs on its first
 * boot and still says what is left to write.
 */
export function notWritten(): (record: WorkRecord) => Plan {
  return (record) => ({ kind: "settled", why: `the decision for \`${record.state}\` is not written yet` });
}

/** The state whose decision is a `notWritten()` stub, read off the plan it returned. */
export function notWrittenIn(plan: Plan): string | undefined {
  return plan.kind === "settled" ? NOT_WRITTEN.exec(plan.why)?.[1] : undefined;
}

/** What one end of a callee returns, computed from its record. */
type Outputs<R extends WorkRecord> = { readonly [end: string]: { returned(record: R): unknown }["returned"] };

interface DeclarationBase<
  S extends ConfigSchema,
  P extends object,
  N extends Needs,
  R extends WorkRecord,
  In extends ConfigSchema = ConfigSchema,
  Out extends Outputs<R> = Outputs<R>,
> {
  readonly name: string;
  readonly pluginName?: string;
  /**
   * The project phases this workflow declares, every value the reason the
   * phase it names is absent. See `ProjectPhases`.
   */
  readonly phases?: ProjectPhases;
  // No `states`, `waiting` or `terminal`: the states come only from the
  // `workflow.mmd` the host reads beside the workflow.
  readonly configSchema: S;
  readonly policy: P;
  readonly needs: N;
  readonly trackerWrites?: Claims<S, P>;
  readonly codeHostWrites?: Claims<S, P>;
  /** What a caller must pass, typed like a plugin's settings; a record a caller starts holds it as \`input\`. */
  readonly input?: In;
  /** What this workflow returns, keyed by terminal state. A workflow with none returns nothing at any end. */
  readonly output?: Out;
  /** Each state the diagram marks \`call\`, bound to the workflow it calls. */
  readonly calls?: Readonly<Record<string, Call>>;
  /**
   * The commands, checks and files this workflow brings, read beside
   * `register` rather than through it: they have to answer when the machine
   * does not mount, which is when a workflow's own `amy roster` matters most.
   */
  readonly commands?: readonly PluginCommand<ConfigOf<S>>[];
  readonly checks?: readonly PluginCheck<ConfigOf<S>>[];
  readonly files?: readonly PluginFile<ConfigOf<S>>[];
  /** What `amy init` prepares for this workflow, and the environment variables it reads: a plugin's own, carried as they are. */
  readonly setup?: readonly PluginSetup<ConfigOf<S>>[];
  readonly environment?: readonly string[];
  runtimePolicy?(args: { readonly ports: PortsOf<N>; readonly config: ConfigOf<S>; readonly policy: P }): P;
  record(workId: string): Omit<R, keyof WorkRecord>;
  /** Registers the supporting half of a workflow: ports, queues, actions or harnesses. */
  extend?(registry: Registry, ctx: PluginContext<ConfigOf<S>>): void | Promise<void>;
}

interface PiecesDeclaration<S extends ConfigSchema, States extends readonly [string, ...string[]], P extends object, N extends Needs, R extends WorkRecord, O,
  In extends ConfigSchema = ConfigSchema, Out extends Outputs<R> = Outputs<R>>
  extends DeclarationBase<S, P, N, R, In, Out> {
  readonly decide: Readonly<Record<string, WorkflowDecision<R, O, P, States[number]>>>;
  before?(record: R, observation: O, policy: P): Plan<States[number]> | undefined;
  after?(decision: Plan<States[number]>, record: R, observation: O, policy: P): Plan<States[number]>;
  discover?(scope: WorkflowPieceContext<S, P, N>): Promise<readonly (string | FoundWork)[]>;
  readonly progress?: ProgressPolicy | ((scope: WorkflowPieceContext<S, P, N>) => ProgressPolicy | undefined);
  observe(scope: WorkflowPieceContext<S, P, N>, record: R): Promise<O>;
  readonly actions:
    // `workflowActions()` narrows each handler's final argument to the action
    // named by its key. The declaration is the boundary that erases that
    // domain payload back to the core's open action vocabulary.
    | Readonly<Record<string, DeclarationAction<S, P, N, R, O> | ActionSpec>>
    | ((scope: WorkflowPieceContext<S, P, N>) => Readonly<Record<string, DeclarationAction<S, P, N, R, O> | ActionSpec>>);
  remember?(
    scope: WorkflowPieceContext<S, P, N>, record: R, outcomes: Record<string, unknown>, observation: O,
    moved: Moved | null, decision: Plan, now: Date,
  ): R;
  /** Gone: a single `plan()` is refused at mount; its `switch` is `decide`, one key per drawn state. */
  readonly plan?: never;
  /** Gone: a `runtime()` is refused at mount; its parts are `discover`, `observe`, `actions` and `remember`. */
  readonly runtime?: never;
}

type WorkflowDeclaration<S extends ConfigSchema, States extends readonly [string, ...string[]], P extends object, N extends Needs, R extends WorkRecord, O,
  In extends ConfigSchema = ConfigSchema, Out extends Outputs<R> = Outputs<R>> = PiecesDeclaration<S, States, P, N, R, O, In, Out>;

/**
 * What a caller passes, as the callee's schema promises it: a required field
 * must be given, any other may be left out. Nothing for a callee that
 * declares no input.
 */
type InputFor<In extends ConfigSchema> = keyof In extends never ? undefined : Flat<
  { [K in keyof In as In[K] extends { readonly required: true } ? K : never]: ValueFor<In[K]> } &
  { [K in keyof In as In[K] extends { readonly required: true } ? never : K]?: ValueFor<In[K]> }
>;
type Flat<T> = { [K in keyof T]: T[K] };
type OutputsFor<Out> = { [End in keyof Out]: Out[End] extends (...args: never[]) => infer Value ? Value : never };

export function defineWorkflow<
  const S extends ConfigSchema,
  const States extends readonly [string, ...string[]],
  P extends object,
  const N extends Needs,
  R extends WorkRecord,
  O,
  const In extends ConfigSchema = Record<never, never>,
  Out extends Outputs<R> = Record<never, never>,
>(declaration: WorkflowDeclaration<S, States, P, N, R, O, In, Out>): WorkflowPlugin<R, O, P, InputFor<In>, OutputsFor<Out>> {
  return drawnWith(declaration as unknown as Declaration<S, P, N, R, O>, undefined) as unknown as WorkflowPlugin<R, O, P, InputFor<In>, OutputsFor<Out>>;
}

type Declaration<S extends ConfigSchema, P extends object, N extends Needs, R extends WorkRecord, O> =
  WorkflowDeclaration<S, readonly [string, ...string[]], P, N, R, O>;

/** The plugin for a declaration, shaped by the diagram the host read beside it, or by its own lists. */
function drawnWith<S extends ConfigSchema, P extends object, N extends Needs, R extends WorkRecord, O>(
  declaration: Declaration<S, P, N, R, O>,
  drawn: Diagram | Error | undefined,
): WorkflowPlugin<R, O, P> {
  const shape = shapeOf(declaration, drawn);
  const refused = (): never => {
    throw new Error(shape as string);
  };
  // Read when asked rather than at import: a call can only be checked once
  // every workflow it names is defined, and a module may define them in any
  // order.
  let unmounted: Assembled | undefined;
  const assembled = (): Assembled => {
    if (typeof shape === "string") refused();
    return (unmounted ??= assemble(declaration as unknown as AnyDeclaration, shape as Shape, undefined, [declaration.name], [declaration as unknown as AnyDeclaration]));
  };

  const plugin = {
    name: declaration.pluginName ?? `workflow-${declaration.name}`,
    configSchema: declaration.configSchema,
    ...(declaration.commands ? { commands: declaration.commands as unknown as readonly PluginCommand[] } : {}),
    ...(declaration.checks ? { checks: declaration.checks as unknown as readonly PluginCheck[] } : {}),
    ...(declaration.files ? { files: declaration.files as unknown as readonly PluginFile[] } : {}),
    ...(declaration.setup ? { setup: declaration.setup as unknown as readonly PluginSetup[] } : {}),
    ...(declaration.environment ? { environment: declaration.environment } : {}),
    ...(declaration.phases ? { phases: declaration.phases } : {}),
    newRecord: (workId: string, now: Date): R => assembled().newRecord(workId, now) as R,
    [DRAW]: (diagram: Diagram | Error) => drawnWith(declaration, diagram),
    register(registry: Registry, untyped: PluginContext) {
      declarationMode(declaration);
      if (typeof shape === "string") refused();
      const mounted = assemble(declaration as unknown as AnyDeclaration, shape as Shape, untyped, [declaration.name], [declaration as unknown as AnyDeclaration]);
      const registerWorkflow = () => {
        registry.workflow(mounted.workflow as Workflow<never, never>);
        registry.contribute(WORKFLOW_RUNTIME, mounted.workflow.name, deferred(mounted.runtime));
      };
      const extended = declaration.extend?.(registry, untyped as PluginContext<ConfigOf<S>>);
      return extended instanceof Promise ? extended.then(registerWorkflow) : registerWorkflow();
    },
  } satisfies Omit<WorkflowPlugin<R, O, P>, "workflow"> & Drawable;
  Object.defineProperty(plugin, CALLEE, { value: { declaration: declaration as unknown as AnyDeclaration, shape } satisfies Callable, enumerable: false });
  // A workflow with no states cannot be read until something gives it some,
  // so the unmounted declaration says why when it is asked, not at import.
  Object.defineProperty(plugin, "workflow", { get: () => assembled().workflow, enumerable: typeof shape !== "string" });
  return plugin as unknown as WorkflowPlugin<R, O, P>;
}

/**
 * What a caller composes against, read off a declared workflow its module
 * exports.
 *
 * `input` is the schema the declaration says a caller must pass, undefined
 * when the workflow takes none; `returns` names the ends it returns
 * something at, so a composition folds only where there is something to
 * fold. Nothing for a plugin that is not a `defineWorkflow` declaration —
 * which is the whole answer: such a workflow can be mounted but never
 * called, and a project composes its phases by calling them.
 */
export function declaredCallee(plugin: object): {
  readonly configSchema: ConfigSchema;
  readonly policy: object;
  readonly input?: ConfigSchema;
  readonly returns: readonly string[];
  readonly trackerWrites?: Claims<ConfigSchema, object>;
  readonly codeHostWrites?: Claims<ConfigSchema, object>;
} {
  const callee = (plugin as Partial<Record<typeof CALLEE, Callable | undefined>>)?.[CALLEE];
  if (!callee || typeof callee.shape === "string") return { configSchema: {}, policy: {}, returns: [] };
  const declaration = callee.declaration as Partial<{
    readonly trackerWrites?: Claims<ConfigSchema, object>;
    readonly codeHostWrites?: Claims<ConfigSchema, object>;
  }>;
  return {
    configSchema: callee.declaration.configSchema,
    policy: callee.declaration.policy,
    ...(callee.declaration.input ? { input: callee.declaration.input as ConfigSchema } : {}),
    returns: Object.keys(callee.declaration.output ?? {}),
    ...(declaration.trackerWrites !== undefined ? { trackerWrites: declaration.trackerWrites } : {}),
    ...(declaration.codeHostWrites !== undefined ? { codeHostWrites: declaration.codeHostWrites } : {}),
  };
}

/** A declaration with its types let go of, as assembly reads it. */
type AnyDeclaration = Declaration<ConfigSchema, object, Needs, WorkRecord, unknown>;

/** What a caller reads off a declaration it calls. */
interface Callable {
  readonly declaration: AnyDeclaration;
  readonly shape: Shape | string;
}

/** A workflow put together for one mount, or for none: its decisions, its first record, and how to build its runtime. */
interface Assembled {
  readonly workflow: Workflow;
  readonly policy: object;
  newRecord(workId: string, now: Date, input?: unknown): WorkRecord;
  /** Built by the host once every plugin has registered; throws, by name, when the mount cannot give it what it needs. */
  runtime(): WorkflowRuntime;
}

/**
 * The workflow for one mount, every call in it checked and put together.
 *
 * `ctx` is absent for the declaration a module exports before anything
 * mounts it: its decisions can be read, and its runtime cannot be built.
 * `path` names where in a tree of calls this is, for what is refused, and
 * `trail` the workflows already on the way here, which is how a cycle is
 * found.
 */
function assemble(
  declaration: AnyDeclaration,
  shape: Shape,
  ctx: PluginContext | undefined,
  path: readonly string[],
  trail: readonly AnyDeclaration[],
): Assembled {
  const config = ctx?.config;
  // Refused before a word of it is merged: a policy default the schema does
  // not describe is a setting whose real answer nobody could find from the
  // config the machine explains.
  if (ctx) policyFits(declaration.name, declaration.configSchema, declaration.policy);
  if (ctx && declaration.phases) phasesFit(declaration.name, declaration.phases);
  const policy = policyFor(declaration.name, declaration.policy, config?.policy);
  // Only a workflow with lanes holds branches, and only its lanes take them.
  const forked = Object.keys(shape.diagram?.forks ?? {}).length > 0;
  const leases = ctx && forked ? new FileLeases(() => nodePath.join(ctx.paths.state, "leases")) : undefined;
  const lent = new Map<string, string>();
  const sites = callSites(declaration, shape, ctx, policy, path, trail, leases && { leases, lent });
  const forks = forkSites(shape, sites, path, leases && { leases, lent });
  // Judged at mount, as it always was: a module's exported declaration is
  // read by suites that walk it to find exactly this kind of mistake.
  if (ctx) decisionsFit(declaration.name, shape.states, declaration.decide, [...sites.keys()], [...forks.keys()]);
  const own = (workId: string, now: Date, input?: unknown): WorkRecord => ({
    ...declaration.record(workId),
    ...(input === undefined ? {} : { input: input as Record<string, unknown> }),
    id: workId,
    state: shape.initial,
    updatedAt: now.toISOString(),
    attempts: {},
    looks: {},
    history: [],
  });
  const newRecord = (workId: string, now: Date, input?: unknown): WorkRecord => {
    const record = own(workId, now, input);
    const site = sites.get(record.state);
    return site ? enterCall(record, site, now) : record;
  };
  const workflow = composedWorkflow(workflowFor(declaration, shape, policy, config as ConfigOf<ConfigSchema> | undefined), sites, forks);

  const runtime = (): WorkflowRuntime => {
    if (!ctx) throw new Error(`the ${declaration.name} workflow is not mounted, so it has no runtime`);
    const ports = portsFor(declaration.name, declaration.needs, ctx, path) as PortsOf<Needs>;
    const settings = ctx.config as ConfigOf<ConfigSchema>;
    const runtimePolicy = declaration.runtimePolicy?.({ ports, config: settings, policy }) ?? policy;
    const args = { ports, config: settings, policy: runtimePolicy, checkouts: ctx.checkouts(), ctx: ctx as PluginContext<ConfigOf<ConfigSchema>> };
    const parts = runtimeFromPieces(declaration, args);
    for (const site of sites.values()) site.runtime = (site as PendingSite).build();
    const lookup: PortLookup = (kind) => (ctx.workflowPort ?? ctx.port)(kind);
    return composedRuntime(completeRuntime(parts, runtimePolicy, (workId, now) => own(workId, now)), sites, lookup, forks);
  };

  return { workflow, policy, newRecord, runtime };
}

/** A call site whose callee's runtime is built when its caller's is. */
interface PendingSite extends CallSite {
  build(): WorkflowRuntime;
}

/**
 * Every call state, checked against the workflow it calls.
 *
 * Each refusal names the call path, because in a tree of calls the workflow
 * that is wrong is not always the one being mounted.
 */
function callSites(
  declaration: AnyDeclaration,
  shape: Shape,
  ctx: PluginContext | undefined,
  policy: object,
  path: readonly string[],
  trail: readonly AnyDeclaration[],
  held?: LaneHolds,
): Map<string, PendingSite> {
  const sites = new Map<string, PendingSite>();
  const declared = declaration.calls ?? {};
  const drawn = shape.diagram?.calls ?? [];
  const where = path.join(" → ");
  for (const state of Object.keys(declared)) {
    if (!shape.diagram) {
      throw new Error(`${where}: binds \`calls.${state}\`, and has no ${DIAGRAM_FILE}: a call state is drawn, with \`class ${state} call\``);
    }
    if (!drawn.includes(state)) {
      throw new Error(`${where}: binds \`calls.${state}\`, and its diagram does not mark \`${state}\` as a call — add \`class ${state} call\``);
    }
  }
  for (const state of drawn) {
    const binding = declared[state];
    if (!isCall(binding)) {
      throw new Error(`${where}: \`${state}\` is a call state with no \`calls\` entry — bind it with \`${state}: call(workflow)\``);
    }
    const lane = Object.values(shape.diagram!.forks).some((fork) => fork.lanes.includes(state));
    sites.set(state, callSite(declaration, shape, ctx, policy, path, trail, state, binding, lane ? held : undefined));
  }
  return sites;
}

/**
 * Every fork the diagram draws, its lanes bound to their calls.
 *
 * Two lanes of one fork that name the same branch would write it at once,
 * and that much can be seen without running anything; a branch only known
 * at run time is held to a lease instead, and the second lane waits for it.
 */
function forkSites(shape: Shape, sites: ReadonlyMap<string, CallSite>, path: readonly string[], held?: LaneHolds): Map<string, ForkSite> {
  const forks = new Map<string, ForkSite>();
  for (const [state, fork] of Object.entries(shape.diagram?.forks ?? {})) {
    const lanes = fork.lanes.map((lane) => sites.get(lane)!);
    const written = new Map<string, string>();
    for (const site of lanes) {
      const branch = site.binding.branch;
      if (branch === undefined) continue;
      const other = written.get(branch);
      if (other !== undefined) {
        throw new Error(`${[...path, state].join(" → ")}: \`${other}\` and \`${site.state}\` both write the branch \`${branch}\`; two lanes of one fork write two branches`);
      }
      written.set(branch, site.state);
    }
    forks.set(state, { state, join: fork.join, lanes, ...(held ?? {}) });
  }
  return forks;
}

function callSite(
  caller: AnyDeclaration,
  shape: Shape,
  ctx: PluginContext | undefined,
  policy: object,
  path: readonly string[],
  trail: readonly AnyDeclaration[],
  state: string,
  binding: Call,
  held?: LaneHolds,
): PendingSite {
  const at = `${[...path, state].join(" → ")}`;
  const callee = calleeOf(binding, at);
  const name = callee.declaration.name;
  const seen = trail.indexOf(callee.declaration);
  if (seen >= 0) throw new Error(`a cycle of calls: ${[...trail.slice(seen), callee.declaration].map((one) => one.name).join(" → ")}`);
  if (typeof callee.shape === "string") throw new Error(`${at}: ${callee.shape}`);
  const declaration = callee.declaration as AnyDeclaration;
  if (declaration.extend) {
    throw new Error(`${at}: ${name} registers its own ports and actions with \`extend\`, so it can be mounted but not called`);
  }
  const edges = returnEdges(shape, state, callee.shape.terminal, name, at);
  signatureFits(binding, declaration, callee.shape.terminal, name, at);

  const settings = validateConfig(at, declaration.configSchema, binding.binding.config);
  if (!settings.ok) throw new Error(settings.problems.join("; "));
  const bound = (kind: string): string => binding.binding.ports?.[kind] ?? kind;
  const calleeCtx: PluginContext | undefined = ctx && {
    ...ctx,
    config: settings.config,
    port: (kind) => ctx.port(bound(kind)),
    ...(ctx.workflowPort ? { workflowPort: (kind: string) => ctx.workflowPort!(bound(kind)) } : {}),
    // A callee's checkouts answer through the same workplace, and a refusal
    // there names the call's workflow — the one whose work stopped — rather
    // than the caller this context was spread from. A deeper call's name is
    // passed through, so the refusal names the innermost one. A lane leases
    // the same workplace, lent its caller's commit.
    checkouts: held
      ? (who) => leasedCheckouts(ctx.checkouts(who ?? name), held)
      : (who) => ctx.checkouts(who ?? name),
  };
  const assembled = assemble(declaration, callee.shape, calleeCtx ?? undefined, [...path, state], [...trail, declaration]);
  if (ctx) claimsFit(caller, ctx.config, policy, declaration, settings.config, assembled.policy, at);

  return {
    state,
    callee: name,
    binding: binding.binding as CallSite["binding"],
    workflow: assembled.workflow,
    policy: assembled.policy,
    edges,
    output: (record) => declaration.output?.[record.state]?.(record),
    newRecord: (workId, now, input) => assembled.newRecord(workId, now, inputFor(declaration, input, `${workId}`)),
    port: (kind) => ctx && (ctx.workflowPort ?? ctx.port)(bound(kind)),
    build: () => assembled.runtime(),
  };
}

/** What the lanes of a fork hold: the branches they took, and the commit each was lent. */
interface LaneHolds {
  readonly leases: BranchLeases;
  readonly lent: Map<string, string>;
}

/**
 * A lane's checkouts: leased, and lent its caller's commit when bound with
 * one — read for the lane's record and every call under it.
 *
 * The lease is composed on the first read, not when the runtime is built: a
 * workflow whose lanes never read their checkouts is still handed nothing,
 * and one that does is lent the branch by the same answer every other read
 * takes.
 */
function leasedCheckouts(checkouts: Checkouts, held: LaneHolds): Checkouts {
  const lent = (workId: string): string | undefined => {
    for (const [id, revision] of held.lent) if (workId === id || workId.startsWith(`${id}/`)) return revision;
    return undefined;
  };
  let leased: Checkouts | undefined;
  const once = (): Checkouts => {
    if (!leased) leased = { git: checkouts.git.leasedTo(held.leases, lent), layout: checkouts.layout };
    return leased;
  };
  return {
    get git() {
      return once().git;
    },
    get layout() {
      return once().layout;
    },
  };
}

function calleeOf(binding: Call, at: string): Callable {
  const reference = binding.callee;
  const target = typeof reference === "function" && !(CALLEE in reference) ? (reference as () => object)() : reference;
  const callee = (target as Partial<Record<typeof CALLEE, Callable>> | undefined)?.[CALLEE];
  if (!callee) throw new Error(`${at}: calls something that is not a workflow declared with \`defineWorkflow\``);
  return callee;
}

/**
 * Where the caller goes from each of the callee's ends: the edge out of the
 * call state named for it. An end with no edge, an edge named for no end and
 * an end with two edges are each refused.
 */
function returnEdges(shape: Shape, state: string, ends: readonly string[], callee: string, at: string): Record<string, string> {
  const out = (shape.diagram?.transitions ?? []).filter((edge) => edge.from === state);
  for (const edge of out) {
    if (!ends.includes(edge.label ?? "")) {
      throw new Error(`${at}: \`${state} --> ${edge.to}\` is not named for an end of ${callee}, which ends at ${ends.map((end) => `\`${end}\``).join(", ")}`);
    }
  }
  return Object.fromEntries(ends.map((end) => {
    const named = out.filter((edge) => edge.label === end);
    if (named.length === 0) {
      throw new Error(`${at}: ${callee} can end at \`${end}\`, and no edge out of \`${state}\` is named \`${end}\` — draw \`${state} --> SOMEWHERE: ${end}\``);
    }
    if (named.length > 1) throw new Error(`${at}: two edges out of \`${state}\` are named \`${end}\`; a return goes one place`);
    return [end, named[0]!.to];
  }));
}

/** The binding's `input`, `output` and `effects` against what the callee declares it takes and returns. */
function signatureFits(binding: Call, callee: AnyDeclaration, ends: readonly string[], name: string, at: string): void {
  inputFits(binding, callee, name, at);
  const named = ends.map((state) => `\`${state}\``).join(", ");
  for (const end of Object.keys(binding.binding.output ?? {})) {
    if (!ends.includes(end)) throw new Error(`${at}: \`output.${end}\` folds an end ${name} does not have; it ends at ${named}`);
    if (!callee.output?.[end]) throw new Error(`${at}: \`output.${end}\` folds what ${name} returns at \`${end}\`, and it returns nothing there`);
  }
  for (const end of Object.keys(binding.binding.effects ?? {})) {
    if (!ends.includes(end)) throw new Error(`${at}: \`effects.${end}\` is for an end ${name} does not have; it ends at ${named}`);
  }
}

/** An input only for a callee that takes one, and one for every callee that needs one. */
function inputFits(binding: Call, callee: AnyDeclaration, name: string, at: string): void {
  const { input } = binding.binding;
  if (input && !callee.input) throw new Error(`${at}: passes an \`input\`, and ${name} takes none`);
  const required = Object.entries(callee.input ?? {}).filter(([, field]) => field.required && field.default === undefined).map(([field]) => field);
  if (!input && required.length > 0) {
    throw new Error(`${at}: ${name} needs an \`input\` with ${required.map((field) => `\`${field}\``).join(", ")}, and the call passes none`);
  }
}

/** What a callee is started with, held to its schema at the moment the call is made. */
function inputFor(callee: AnyDeclaration, input: unknown, workId: string): unknown {
  if (!callee.input) return undefined;
  const checked = validateConfig(`the input ${workId} was called with`, callee.input, input);
  if (!checked.ok) throw new Error(checked.problems.join("; "));
  return checked.config;
}

/** A callee writes nothing its caller did not claim, so installing one cannot widen what the person granted. */
function claimsFit(
  caller: AnyDeclaration,
  callerConfig: Record<string, unknown>,
  callerPolicy: object,
  callee: AnyDeclaration,
  calleeConfig: Record<string, unknown>,
  calleePolicy: object,
  at: string,
): void {
  for (const [field, port] of [["trackerWrites", "tracker"], ["codeHostWrites", "code-host"]] as const) {
    const granted = claimsOf(caller[field], callerConfig, callerPolicy);
    for (const write of claimsOf(callee[field], calleeConfig, calleePolicy)) {
      if (!granted.includes(write)) {
        throw new Error(`${at}: ${callee.name} claims the ${port} write \`${write}\`, and ${caller.name} does not claim it`);
      }
    }
  }
}

function claimsOf(value: Claims<ConfigSchema, object> | undefined, config: Record<string, unknown>, policy: object): readonly string[] {
  if (typeof value !== "function") return value ?? [];
  return value({ config: config as ConfigOf<ConfigSchema>, policy });
}

/**
 * Where the states come from, or why there are none.
 *
 * The diagram is the only shape: a workflow says its states once, in the
 * file beside it. One whose host found no diagram cannot mount, and a
 * diagram amy cannot read is refused with the line it stopped at. A
 * declaration still carrying the lists it used to declare is refused by
 * name, so the fact is not said twice.
 */
function shapeOf(declaration: { readonly name: string }, drawn: Diagram | Error | undefined): Shape | string {
  const workflow = `the ${declaration.name} workflow`;
  if (drawn instanceof Error) return `${workflow} has a diagram amy cannot read — ${drawn.message}`;
  const declared = (["states", "waiting", "terminal"] as const).filter((field) => field in declaration);
  if (declared.length > 0) {
    return `${workflow} declares ${declared.map((field) => `\`${field}\``).join(", ")}; delete them, a workflow's states come only from its ${DIAGRAM_FILE}`;
  }
  if (!drawn) {
    return `${workflow} has no ${DIAGRAM_FILE}: draw one beside its entry or at its package root — a workflow's states come only from its diagram`;
  }
  // Waiting on the owner is still waiting, as far as the engine is concerned.
  const waiting = drawn.states.filter((state) => drawn.waiting.includes(state) || drawn.attention.includes(state));
  return { states: drawn.states, initial: drawn.initial, waiting, terminal: drawn.terminal, diagram: drawn };
}

/**
 * The diagram beside a workflow's entry, found the way the entry itself is.
 *
 * A workflow is a directory: one under the workflows directory holds its
 * diagram beside its entry, and a package holds it at its root, which is the
 * nearest directory above the entry with a manifest. Nothing names the file.
 */
export function diagramBeside(entry: string | URL): { readonly path: string; readonly text: string } | undefined {
  const file = entry instanceof URL || entry.startsWith("file:") ? fileURLToPath(entry) : entry;
  for (const directory of [nodePath.dirname(file), packageRoot(nodePath.dirname(file))]) {
    if (directory === undefined) continue;
    const candidate = nodePath.join(directory, DIAGRAM_FILE);
    if (fs.existsSync(candidate)) return { path: candidate, text: fs.readFileSync(candidate, "utf-8") };
  }
  return undefined;
}

function packageRoot(from: string): string | undefined {
  for (let directory = from; ; directory = nodePath.dirname(directory)) {
    if (fs.existsSync(nodePath.join(directory, "package.json"))) return directory;
    if (nodePath.dirname(directory) === directory) return undefined;
  }
}

/**
 * The plugin, shaped by a diagram's text.
 *
 * A declaration takes its states from it. A plugin that registers its
 * workflow by hand already says its states, so a diagram beside it is the
 * same fact twice, and it is refused when it mounts.
 */
export function withDiagram<T extends Plugin>(plugin: T, text: string, source: string = DIAGRAM_FILE): T {
  let diagram: Diagram | Error;
  try {
    diagram = readDiagram(text, source);
  } catch (error) {
    diagram = error instanceof Error ? error : new Error(String(error));
  }
  if (DRAW in plugin) return (plugin as T & Drawable)[DRAW](diagram) as T;
  return {
    name: plugin.name,
    ...(plugin.configSchema ? { configSchema: plugin.configSchema } : {}),
    register() {
      throw new Error(`${plugin.name} registers its workflow by hand and has ${source} beside it; a workflow says its states once — move it onto \`defineWorkflow\``);
    },
  } as unknown as T;
}

/** The plugin, shaped by the diagram beside its entry when there is one, and unchanged when there is none. */
export function withDiagramBeside<T extends Plugin>(plugin: T, entry: string | URL): T {
  const found = diagramBeside(entry);
  return found ? withDiagram(plugin, found.text, found.path) : plugin;
}

/**
 * The plugin, refused at mount if it registers a workflow by hand.
 *
 * A host that mounts what somebody installed calls this on every plugin it
 * loads: every workflow it mounts is a `defineWorkflow` with a diagram, so a
 * raw `registry.workflow(...)` is refused naming the plugin. A declaration,
 * and a plugin that registers no workflow, pass through unchanged.
 */
export function declaredWorkflowsOnly<T extends Plugin>(plugin: T): T {
  if (DRAW in plugin) return plugin;
  const refuse = (): never => {
    throw new Error(`${plugin.name} registers a workflow by hand; amy mounts a workflow declared with \`defineWorkflow\` and a ${DIAGRAM_FILE} beside it — move it onto them`);
  };
  const register: Plugin["register"] = (registry, ctx) =>
    plugin.register(receiverKept(registry, { workflow: refuse }), ctx);
  return receiverKept(plugin, { register });
}

/**
 * The object with some members replaced, every other one read and called on
 * the object itself. A class whose getters or methods read `#private`
 * fields throws on any other receiver, so a prototype wrapper cannot do this.
 */
function receiverKept<T extends object>(target: T, replaced: Readonly<Record<string, unknown>>): T {
  const own = (key: string | symbol): boolean => typeof key === "string" && Object.hasOwn(replaced, key);
  // The proxy stands on an empty object of its own, never on the target: a
  // frozen target would make every replaced member break a Proxy invariant.
  const stand = Object.create(Object.getPrototypeOf(target) as object | null) as T;
  return new Proxy(stand, {
    get(_stand, key) {
      if (own(key)) return replaced[key as string];
      const value: unknown = Reflect.get(target, key, target);
      return typeof value === "function" ? (value as (...args: unknown[]) => unknown).bind(target) : value;
    },
    has: (_stand, key) => own(key) || Reflect.has(target, key),
    ownKeys: () => [...new Set([...Reflect.ownKeys(target), ...Object.keys(replaced)])],
    getOwnPropertyDescriptor(_stand, key) {
      const descriptor = own(key)
        ? { value: replaced[key as string], writable: false, enumerable: true }
        : Reflect.getOwnPropertyDescriptor(target, key);
      return descriptor && { ...descriptor, configurable: true };
    },
  });
}

/**
 * Completes a declaration's runtime with the fields the core owns.
 *
 * Members are delegated, not spread: a class-built runtime keeps its methods
 * on the prototype, and a spread drops them while the mount still succeeds.
 */
function completeRuntime<R extends WorkRecord, O, P>(
  parts: WorkflowRuntimeParts<R, O>,
  policy: P,
  newRecord: (workId: string, now: Date) => R,
): WorkflowRuntime<R, O> {
  return {
    policy,
    ...(parts.progress ? { progress: parts.progress } : {}),
    found: () => parts.found(),
    observe: (record) => parts.observe(record),
    actions: parts.actions,
    apply: (record, plan, outcomes, observation, now, moved) =>
      parts.apply(record, plan, outcomes, observation, now, moved),
    newRecord,
  };
}

function workflowFor<S extends ConfigSchema, P extends object, R extends WorkRecord, O>(
  declaration: {
    readonly name: string;
    readonly phases?: ProjectPhases;
    readonly trackerWrites?: Claims<S, P>;
    readonly codeHostWrites?: Claims<S, P>;
    readonly decide: Readonly<Record<string, WorkflowDecision<R, O, P>>>;
    before?(record: R, observation: O, policy: P): Plan | undefined;
    after?(decision: Plan, record: R, observation: O, policy: P): Plan;
  },
  shape: Shape,
  policy: P,
  config?: ConfigOf<S>,
): Workflow<O, P> {
  // A claim written as a function is read only where a configuration exists:
  // this module's exported object has none, so a callback that reads a
  // required setting cannot throw at import. The mount rebuilds the workflow
  // with its own validated config, and the unmounted declaration claims
  // nothing — a mount given it refuses loudly rather than widening the claim.
  const claims = (value: Claims<S, P> | undefined): readonly string[] => {
    if (typeof value !== "function") return value ?? [];
    if (config === undefined) return [];
    return value({ config, policy });
  };
  return {
    name: declaration.name,
    states: shape.states,
    waitingStates: shape.waiting,
    initialState: shape.initial,
    terminalStates: shape.terminal,
    ...(shape.diagram ? { diagram: shape.diagram } : {}),
    ...(declaration.phases ? { phases: declaration.phases } : {}),
    trackerWrites: claims(declaration.trackerWrites),
    codeHostWrites: claims(declaration.codeHostWrites),
    // What it says before any decision passes through `after` like any plan,
    // so a write it makes in a fork is handed over as one anywhere else is.
    ...(declaration.before ? {
      interrupt: (record: WorkRecord, observation: O, chosen: P) => {
        const early = declaration.before!(record as R, observation, chosen);
        return early && (declaration.after?.(early, record as R, observation, chosen) ?? early);
      },
    } : {}),
    plan: (record, observation, chosen) => {
      const current = record as R;
      const early = declaration.before?.(current, observation, chosen);
      const decision = early ?? declaration.decide[current.state]?.(current, observation, chosen);
      if (!decision) throw new Error(`${declaration.name} has no decision for state \`${current.state}\``);
      return declaration.after?.(decision, current, observation, chosen) ?? decision;
    },
  };
}

const GONE = { plan: "`decide`, one key per drawn state", runtime: "`discover`, `observe`, `actions` and `remember`" } as const;

/**
 * Only the pieces form mounts. A declaration still passing the old `plan`
 * or `runtime` is refused naming each and where it went, rather than read as
 * a workflow whose decisions are all missing.
 */
function declarationMode(declaration: { readonly name: string }): void {
  const gone = (Object.keys(GONE) as (keyof typeof GONE)[]).filter((key) => key in declaration);
  if (gone.length > 0) {
    const moves = gone.map((key) => `\`${key}\` moves onto ${GONE[key]}`).join("; ");
    throw new Error(`the ${declaration.name} workflow declares ${gone.map((key) => `\`${key}\``).join(" and ")}, which no longer mount: ${moves}`);
  }
  for (const required of ["decide", "observe", "actions"] as const) {
    if (!(required in declaration)) throw new Error(`the ${declaration.name} workflow declares no \`${required}\`; a workflow is its diagram, \`decide\` and \`actions\``);
  }
}

function decisionsFit(workflow: string, states: readonly string[], decide: Readonly<Record<string, unknown>>, calls: readonly string[], forks: readonly string[]): void {
  const names = Object.keys(decide);
  const decided = states.filter((state) => !calls.includes(state) && !forks.includes(state));
  const missing = decided.filter((state) => !Object.hasOwn(decide, state));
  const extra = names.filter((state) => !states.includes(state));
  // A call is its own decision: the callee decides, and its ends say where the caller goes.
  const called = names.filter((state) => calls.includes(state));
  // A fork too: its lanes decide, and the join is where the caller does.
  const forked = names.filter((state) => forks.includes(state));
  if (missing.length === 0 && extra.length === 0 && called.length === 0 && forked.length === 0) return;
  const named = (list: readonly string[]) => list.map((state) => `\`${state}\``).join(", ");
  const details = [
    ...(missing.length ? [`missing ${named(missing)}`] : []),
    ...(extra.length ? [`extra ${named(extra)}`] : []),
    ...(called.length ? [`${named(called)} ${called.length === 1 ? "is a call state" : "are call states"}, decided by the workflow called there`] : []),
    ...(forked.length ? [`${named(forked)} ${forked.length === 1 ? "is a fork" : "are forks"}, moved by its lanes; the join is where the decision is`] : []),
  ];
  throw new Error(`the ${workflow} workflow's \`decide\` does not match its states: ${details.join("; ")}`);
}

function runtimeFromPieces<S extends ConfigSchema, P extends object, N extends Needs, R extends WorkRecord, O>(
  declaration: Declaration<S, P, N, R, O>,
  scope: WorkflowPieceContext<S, P, N>,
): WorkflowRuntimeParts<R, O> {
  const actions = Object.create(null) as Record<string, ActionImplementation<R, O>>;
  const declared = typeof declaration.actions === "function" ? declaration.actions(scope) : declaration.actions;
  for (const [name, implementation] of Object.entries(declared)) {
    actions[name] = typeof implementation === "function"
      ? (effect, work) => (implementation as WorkflowAction<S, P, N, R, O>)(
        { ...scope, ...actionPorts(scope.ports, work, scope.ctx.log, scope.ctx.now) },
        work,
        effect,
      )
      : implementation;
  }
  const progress = typeof declaration.progress === "function" ? declaration.progress(scope) : declaration.progress;
  return {
    ...(progress ? { progress } : {}),
    found: () => declaration.discover?.(scope) ?? Promise.resolve([]),
    observe: (record) => declaration.observe(scope, record),
    actions,
    apply: (record, decision, outcomes, observation, now, moved) =>
      declaration.remember?.(scope, record, outcomes, observation, moved, decision, now) ?? record,
  };
}

function portsFor(workflow: string, needs: Needs, ctx: PluginContext, path: readonly string[] = [workflow]): Record<string, unknown> {
  // A callee's need is refused with the whole call path, so the person
  // reading it knows which call in the tree is missing a port at the root.
  const called = path.length > 1;
  return Object.fromEntries(Object.entries(needs).map(([kind, need]) => {
    const { optional: canBeAbsent, requires = [] } = (need as PortNeed<unknown, boolean>)[PORT_NEED];
    const mounted = ctx.port(kind);
    if (!mounted && !canBeAbsent) {
      throw new Error(called ? `${path.join(" → ")}: needs ${kind}` : `the ${workflow} workflow needs the \`${kind}\` port, and nothing mounted it`);
    }
    const lacking = mounted ? requires.filter((method) => typeof (mounted as Record<string, unknown>)[method] !== "function") : [];
    if (lacking.length > 0) {
      const methods = lacking.map((method) => `\`${method}\``).join(", ");
      throw new Error(`${called ? path.join(" → ") : `the ${workflow} workflow`}: needs ${kind} to offer ${methods}, and the mounted one does not`);
    }
    return [kind, mounted];
  }));
}

/**
 * The decision's defaults, over what the machine said.
 *
 * Which keys may exist is the schema's word — the mount validated the config
 * against it, with every leaf of a policy group checked by name — and the
 * schema's defaults are the declaration's own, held equal by the mount's
 * consistency check. What is left here is the one merge both of those made
 * possible: what somebody wrote wins, what they left out keeps its default.
 */
export function policyFor<P extends object>(workflow: string, defaults: P, configured: unknown): P {
  const overrides = configured ?? {};
  if (typeof overrides !== "object" || overrides === null || Array.isArray(overrides)) {
    throw new Error(`${workflow} policy must be a mapping`);
  }
  return { ...defaults, ...overrides };
}

/**
 * Every default a workflow's decision reads, its schema must say too.
 *
 * The policy is not a `record` field hiding its members any more: each one is
 * a schema entry, `policy.<key>`, with the type, the default and the reason —
 * which is what `amy config explain` prints and what the boot check holds the
 * template to. A decision reading a key the schema does not declare, or a
 * schema stating a default different from the one the decision reads, is
 * refused at mount, naming the key: two answers to the same question is one
 * lie waiting for the person who tunes the wrong one.
 */
function policyFits(workflow: string, schema: ConfigSchema, defaults: object): void {
  const problems: string[] = [];
  for (const [key, value] of Object.entries(defaults)) {
    const entry = schema[`policy.${key}`];
    if (entry === undefined) {
      problems.push(
        `the ${workflow} workflow reads \`policy.${key}\`, and its schema declares no such setting — declare \`policy.${key}\` with a type, a default and a description`,
      );
      continue;
    }
    if (entry.default !== value) {
      problems.push(
        `the ${workflow} workflow's schema says \`policy.${key}\` defaults to ${describeDefault(entry.default)}, and its decision reads ${describeDefault(value)} — both name the same machine`,
      );
    }
  }
  if (problems.length > 0) throw new Error(problems.join("; "));
}

function describeDefault(value: unknown): string {
  return typeof value === "string" ? `"${value}"` : String(value);
}

/**
 * Every phase a declaration names absent must say why in one word or more.
 *
 * `phases` is a declaration of absence, not a flag: a value that is empty or
 * not prose tells nobody what the project loses without the phase, which is
 * the only reason it earns a word at all.
 */
function phasesFit(workflow: string, phases: ProjectPhases): void {
  const absent = Object.entries(phases).filter(([, reason]) => reason !== undefined);
  const empty = absent.filter(([, reason]) => typeof reason !== "string" || (reason as string).trim() === "");
  if (empty.length > 0) {
    throw new Error(`the ${workflow} workflow's \`phases\` names ${empty.map(([phase]) => `\`${phase}\``).join(", ")} with no reason: say in one sentence why it is absent`);
  }
}

/**
 * A workflow's shape, read from the Mermaid `stateDiagram-v2` beside it.
 *
 * amy reads a subset of Mermaid, and every line of it is ordinary Mermaid, so
 * the file renders on GitHub and in Obsidian with nothing installed. The
 * reader is amy's own: the subset is a handful of line forms, smaller than
 * the dependency that would replace it, and the core has none.
 */

import { DiagramError } from "./errors.js";

/** The file a workflow's directory holds beside its entry. */
export const DIAGRAM_FILE = "workflow.mmd";

/** One arrow the diagram draws. A label is prose for a reader; amy does not interpret it. */
export interface DrawnTransition {
  readonly from: string;
  readonly to: string;
  readonly label?: string;
}

export interface Diagram {
  /** Every state the diagram draws, the initial one first, then in the order they appear. */
  readonly states: readonly string[];
  readonly initial: string;
  readonly terminal: readonly string[];
  /** Nothing moves until the world does. */
  readonly waiting: readonly string[];
  /** It waits on the person whose work it is. */
  readonly attention: readonly string[];
  /** Any state that is not terminal may move to it. */
  readonly anywhere: readonly string[];
  /** It leaves to the state the record came from. */
  readonly returns: readonly string[];
  /** It calls another workflow, and its edges out are named for where that one ends. */
  readonly calls: readonly string[];
  /**
   * Every `<<fork>>`, with the lanes drawn out of it and the `<<join>>` they
   * all lead to. A record waits in the fork while its lanes run, each lane a
   * call of its own, and moves to the join when every one has ended.
   */
  readonly forks: Readonly<Record<string, Fork>>;
  /** A state's description, from `state "…" as NAME`: prose for a reader, never read as a binding. */
  readonly labels: Readonly<Record<string, string>>;
  readonly transitions: readonly DrawnTransition[];
  /** The file as it was read, so every view draws the same text. */
  readonly text: string;
}

/** One `<<fork>>`: the lanes it starts, in the order they are drawn, and the join they meet at. */
export interface Fork {
  readonly lanes: readonly string[];
  readonly join: string;
}

/** The five classes amy reads. Any other class is left for whoever renders the file. */
export const DIAGRAM_CLASSES = ["waiting", "attention", "anywhere", "returns", "call"] as const;
type DiagramClass = (typeof DIAGRAM_CLASSES)[number];

const START = "[*]";
/** A state is a name of letters, digits and underscores; `[*]` is where work starts and ends. */
const END = /^(?:[A-Za-z_]\w*|\[\*\])$/;
const NAME = /^[A-Za-z_]\w*$/;
/** `state "a description" as NAME`, which names a state and draws nothing. */
const DESCRIBED = /^state\s+"([^"]*)"\s+as\s+([A-Za-z_]\w*)\s*$/;
/** `state NAME <<fork>>` or `state NAME <<join>>`: where lanes split, and where they meet again. */
const PSEUDO = /^state\s+([A-Za-z_]\w*)\s+<<(fork|join)>>\s*$/;
/**
 * Names Mermaid's state grammar takes as keywords, compared without case: a
 * state called one of them would mount and never render.
 */
const RESERVED = new Set(["class", "classdef", "click", "default", "href", "note", "scale", "state", "statediagram", "style"]);

/**
 * Constructs a record in one flat state cannot be in, refused by name rather
 * than drawn as something the machine does not do.
 */
const REFUSED: readonly [RegExp, string][] = [
  [/^state\s+.*\{\s*$/, "a composite state is not read: a record is in one flat state"],
  [/^\}\s*$/, "a composite state is not read: a record is in one flat state"],
  [/<<choice>>/, "`<<choice>>` is not read: the decision is code, and the diagram draws where it can lead"],
  [/<<fork>>/, "`<<fork>>` is read only as `state NAME <<fork>>`, on a line of its own"],
  [/<<join>>/, "`<<join>>` is read only as `state NAME <<join>>`, on a line of its own"],
  [/^--\s*$/, "a concurrent region is not read: a record is in one state at a time"],
  [/:::/, "the `:::` class shorthand is not read; write `class STATE name` on a line of its own"],
];

/** Lines that are for whoever renders the file, and say nothing about where work can go. */
const LEFT_FOR_THE_RENDERER: readonly RegExp[] = [
  /^%%/,
  /^classDef\s/,
  /^style\s/,
  /^direction\s+(TB|BT|LR|RL)\s*$/,
  /^accTitle\s*:/,
  /^accDescr\s*:/,
  /^note\s+(left|right)\s+of\s+[^\s:]+\s*:/,
];

interface Reading {
  readonly states: string[];
  readonly initial: string[];
  readonly terminal: Set<string>;
  readonly classes: Map<DiagramClass, Set<string>>;
  /** Every state a line names outside an arrow — a class, a style, a note — and the first line naming it. */
  readonly named: Map<string, number>;
  readonly labels: Record<string, string>;
  readonly transitions: DrawnTransition[];
  readonly forks: Set<string>;
  readonly joins: Set<string>;
}

/**
 * Reads the subset, or refuses with the line that is outside it.
 *
 * `source` names the file in a refusal, for a caller that knows where it
 * came from.
 */
export function readDiagram(text: string, source = DIAGRAM_FILE): Diagram {
  const reading: Reading = {
    states: [],
    initial: [],
    terminal: new Set(),
    classes: new Map(DIAGRAM_CLASSES.map((name) => [name, new Set<string>()])),
    named: new Map(),
    labels: {},
    transitions: [],
    forks: new Set(),
    joins: new Set(),
  };
  const lines = text.split(/\r?\n/);
  let index = frontMatterEnd(lines);
  index = header(lines, index, source);

  for (; index < lines.length; index += 1) {
    const line = lines[index]!.trim();
    const number = index + 1;
    if (line === "") continue;
    for (const state of namedBy(line)) if (!reading.named.has(state)) reading.named.set(state, number);
    const block = blockEnd(lines, index, line, source);
    if (block !== undefined) {
      index = block;
      continue;
    }
    readLine(line, number, reading, source);
  }

  return settle(reading, text, source);
}

/** A Mermaid front-matter block (`---` … `---`) ahead of the header is configuration for the renderer. */
function frontMatterEnd(lines: readonly string[]): number {
  const first = lines.findIndex((line) => line.trim() !== "");
  if (first < 0 || lines[first]!.trim() !== "---") return 0;
  const close = lines.findIndex((line, at) => at > first && line.trim() === "---");
  return close < 0 ? lines.length : close + 1;
}

function header(lines: readonly string[], from: number, source: string): number {
  for (let index = from; index < lines.length; index += 1) {
    const line = lines[index]!.trim();
    if (line === "" || line.startsWith("%%")) continue;
    if (line === "stateDiagram-v2") return index + 1;
    throw new DiagramError(index + 1, `the first line is \`${line}\`, and amy reads a \`stateDiagram-v2\``, source);
  }
  throw new DiagramError(0, "it is empty, and amy reads a `stateDiagram-v2`", source);
}

/** A multi-line `note … end note` or `accDescr { … }` is prose, skipped whole. Returns the index of its last line. */
function blockEnd(lines: readonly string[], index: number, line: string, source: string): number | undefined {
  if (/^note\s+(left|right)\s+of\s+[^\s:]+\s*$/.test(line)) {
    return closingLine(lines, index, (next) => next === "end note", "a `note` is never closed with `end note`", source);
  }
  if (!/^accDescr\s*\{/.test(line)) return undefined;
  return /\}\s*$/.test(line) ? index : closingLine(lines, index, (next) => /\}\s*$/.test(next), "an `accDescr {` is never closed with `}`", source);
}

/**
 * The line a block closes on. One left open is refused at the line that
 * opened it: Mermaid would not draw it, and what follows would be read as
 * prose rather than as states.
 */
function closingLine(lines: readonly string[], index: number, closes: (line: string) => boolean, unclosed: string, source: string): number {
  for (let at = index + 1; at < lines.length; at += 1) {
    if (closes(lines[at]!.trim())) return at;
  }
  throw new DiagramError(index + 1, unclosed, source);
}

function readLine(line: string, number: number, reading: Reading, source: string): void {
  // Prose first: a comment, a note or a label may mention `<<choice>>` or
  // `:::` without drawing either.
  if (LEFT_FOR_THE_RENDERER.some((pattern) => pattern.test(line))) return;
  // A description is prose too, whatever it mentions.
  const described = DESCRIBED.exec(line);
  if (described) {
    reading.labels[described[2]!] = described[1]!;
    return;
  }
  const pseudo = PSEUDO.exec(line);
  if (pseudo) {
    (pseudo[2] === "fork" ? reading.forks : reading.joins).add(pseudo[1]!);
    return;
  }
  const drawn = withoutLabel(line);
  for (const [pattern, reason] of REFUSED) {
    if (pattern.test(drawn)) throw new DiagramError(number, reason, source);
  }

  const arrow = arrowIn(line);
  if (arrow) return readTransition(arrow.from, arrow.to, arrow.label, number, reading, source);

  const marked = classIn(line);
  if (marked) return readClass(marked.states, marked.name, number, reading);

  throw new DiagramError(number, `\`${line}\` is not a line amy reads; it reads \`A --> B\`, \`[*] --> A\`, \`A --> [*]\`, \`class A name\` and \`state "description" as A\``, source);
}

/** An arrow's line up to its label: the label's first colon is one with no colon beside it. */
function withoutLabel(line: string): string {
  const at = line.indexOf("-->");
  if (at < 0) return line;
  const label = line.slice(at + 3).search(/(?<!:):(?!:)/);
  return label < 0 ? line : line.slice(0, at + 3 + label);
}

/**
 * The states a line names without drawing them: a `class` of any name, a
 * `style`, a `note`. Each has to be a state an arrow draws, or the diagram
 * renders a state the workflow does not have.
 */
function namedBy(line: string): string[] {
  const marked = classIn(line);
  if (marked) return marked.states;
  const styled = /^style\s+(\S+)\s/.exec(line);
  if (styled) return styled[1]!.split(",").map((state) => state.trim());
  const described = DESCRIBED.exec(line);
  if (described) return [described[2]!];
  const pseudo = PSEUDO.exec(line);
  if (pseudo) return [pseudo[1]!];
  const noted = /^note\s+(?:left|right)\s+of\s+([^\s:]+)/.exec(line);
  return noted ? [noted[1]!] : [];
}

/** `A --> B`, or `A --> B: label`. Everything after the first colon is the label, arrows included. */
function arrowIn(line: string): { from: string; to: string; label?: string } | undefined {
  const at = line.indexOf("-->");
  if (at < 0) return undefined;
  const rest = line.slice(at + 3);
  const colon = rest.indexOf(":");
  const from = line.slice(0, at).trim();
  const to = (colon < 0 ? rest : rest.slice(0, colon)).trim();
  if (!END.test(from) || !END.test(to)) return undefined;
  return colon < 0 ? { from, to } : { from, to, label: rest.slice(colon + 1) };
}

/** `class A,B name`. */
function classIn(line: string): { states: string[]; name: string } | undefined {
  const words = /^class\s+(.+)\s+(\S+)$/.exec(line.replace(/;$/, "").trim());
  if (!words) return undefined;
  const states = words[1]!.split(",").map((state) => state.trim());
  const name = words[2]!;
  return states.every((state) => NAME.test(state)) && NAME.test(name) ? { states, name } : undefined;
}

function readTransition(from: string, to: string, label: string | undefined, number: number, reading: Reading, source: string): void {
  if (from === START && to === START) throw new DiagramError(number, "`[*] --> [*]` draws no state", source);
  for (const end of [from, to]) {
    if (RESERVED.has(end.toLowerCase())) {
      throw new DiagramError(number, `\`${end}\` is a word Mermaid reads as a keyword, in any case, not as a state; name the state something else`, source);
    }
  }
  if (from === START) {
    reading.initial.push(to);
    see(reading, to);
    return;
  }
  see(reading, from);
  if (to === START) {
    reading.terminal.add(from);
    return;
  }
  see(reading, to);
  const said = label?.trim();
  reading.transitions.push(said ? { from, to, label: said } : { from, to });
}

function readClass(states: readonly string[], name: string, number: number, reading: Reading): void {
  if (!(DIAGRAM_CLASSES as readonly string[]).includes(name)) return;
  for (const state of states) {
    reading.classes.get(name as DiagramClass)!.add(state);
  }
}

function see(reading: Reading, state: string): void {
  if (!reading.states.includes(state)) reading.states.push(state);
}

function settle(reading: Reading, text: string, source: string): Diagram {
  if (reading.initial.length === 0) throw new DiagramError(0, "no `[*] --> STATE` names the initial state", source);
  if (reading.initial.length > 1) {
    throw new DiagramError(0, `\`[*]\` leads to ${reading.initial.map((state) => `\`${state}\``).join(" and ")}; a workflow starts in one state`, source);
  }
  for (const [state, line] of reading.named) {
    if (!reading.states.includes(state)) throw new DiagramError(line, `\`${state}\` is named here, and no transition draws it`, source);
  }
  if (reading.terminal.size === 0) throw new DiagramError(0, "no `STATE --> [*]` names a state where the work ends", source);

  const initial = reading.initial[0]!;
  const of = (name: DiagramClass) => reading.states.filter((state) => reading.classes.get(name)!.has(state));
  return {
    states: [initial, ...reading.states.filter((state) => state !== initial)],
    initial,
    terminal: reading.states.filter((state) => reading.terminal.has(state)),
    waiting: of("waiting"),
    attention: of("attention"),
    anywhere: of("anywhere"),
    returns: of("returns"),
    calls: of("call"),
    forks: forksOf(reading, source),
    labels: reading.labels,
    transitions: reading.transitions,
    text,
  };
}

/**
 * Every fork with its lanes and the join they meet at, or the refusal that
 * names what is drawn wrong.
 *
 * A record is in one state at a time, and that stays true: the record waits
 * in the fork, and every lane is a call, so each one is a record of its own.
 * A lane that is not a call, a lane whose edges lead anywhere but the join,
 * and a join some lane never reaches would each be a drawing of something the
 * machine does not do.
 */
function forksOf(reading: Reading, source: string): Record<string, Fork> {
  const refuse = (why: string): never => {
    throw new DiagramError(0, why, source);
  };
  for (const state of [...reading.forks, ...reading.joins]) pseudoFits(reading, state, refuse);
  const forks: Record<string, Fork> = {};
  const laned = new Set<string>();
  for (const fork of reading.forks) forks[fork] = forkOf(reading, fork, laned, refuse);
  for (const join of reading.joins) joinFits(reading, join, forks, refuse);
  return forks;
}

type Refuse = (why: string) => never;

const out = (reading: Reading, state: string) => reading.transitions.filter((edge) => edge.from === state);
const into = (reading: Reading, state: string) => reading.transitions.filter((edge) => edge.to === state);

/** A fork or a join is one or the other, never where work starts or ends, and never a call. */
function pseudoFits(reading: Reading, state: string, refuse: Refuse): void {
  if (reading.forks.has(state) && reading.joins.has(state)) refuse(`\`${state}\` is drawn as a fork and as a join; a state is one or the other`);
  if (reading.initial.includes(state) || reading.terminal.has(state)) refuse(`\`${state}\` is a fork or a join, and work neither starts nor ends in one`);
  if (reading.classes.get("call")!.has(state)) refuse(`\`${state}\` is a fork or a join and a call; the lanes are the calls`);
}

/** One fork's lanes, each a call started only there, and the join every one of them leads to. */
function forkOf(reading: Reading, fork: string, laned: Set<string>, refuse: Refuse): Fork {
  const lanes = out(reading, fork).map((edge) => edge.to);
  if (lanes.length < 2) refuse(`the fork \`${fork}\` draws ${lanes.length} lane(s); a fork splits work into two or more, and one is a call`);
  for (const lane of lanes) laneFits(reading, fork, lane, laned, refuse);
  const join = [...new Set(lanes.flatMap((lane) => out(reading, lane).map((edge) => edge.to)))].find((state) => reading.joins.has(state));
  if (!join) return refuse(`the lanes of \`${fork}\` lead to no \`<<join>>\`; draw where they meet again`);
  for (const lane of lanes) meetsAt(reading, fork, lane, join, refuse);
  return { lanes, join };
}

function laneFits(reading: Reading, fork: string, lane: string, laned: Set<string>, refuse: Refuse): void {
  if (!reading.classes.get("call")!.has(lane)) refuse(`\`${lane}\` is a lane of the fork \`${fork}\` and not a call: every lane is a record of its own — add \`class ${lane} call\``);
  if (laned.has(lane)) refuse(`\`${lane}\` is drawn twice out of a fork; each lane is drawn once`);
  laned.add(lane);
  const from = into(reading, lane).map((edge) => edge.from).filter((state) => state !== fork);
  if (from.length > 0) refuse(`\`${lane}\` is a lane of \`${fork}\` and is also reached from \`${from[0]}\`; a lane starts only at its fork`);
}

/** Every end of a lane leads to its join, and nowhere else. */
function meetsAt(reading: Reading, fork: string, lane: string, join: string, refuse: Refuse): void {
  const edges = out(reading, lane);
  if (edges.length === 0) refuse(`\`${lane}\` is a lane of \`${fork}\` and never reaches the join \`${join}\``);
  const elsewhere = edges.find((edge) => edge.to !== join);
  if (elsewhere) refuse(`\`${lane} --> ${elsewhere.to}\` leaves a lane of \`${fork}\` for somewhere other than its join \`${join}\`; every end of a lane leads to the join`);
}

/** A join is where one fork's lanes meet, only they lead into it, and it leads somewhere. */
function joinFits(reading: Reading, join: string, forks: Record<string, Fork>, refuse: Refuse): void {
  const met = Object.values(forks).filter((fork) => fork.join === join);
  if (met.length !== 1) refuse(`the join \`${join}\` is ${met.length === 0 ? "reached by no fork's lanes" : "where two forks meet"}; a join is where one fork's lanes meet again`);
  const strays = into(reading, join).filter((edge) => !met[0]!.lanes.includes(edge.from));
  if (strays.length > 0) refuse(`\`${strays[0]!.from} --> ${join}\` reaches the join from outside its fork; only the lanes lead into a join`);
  if (out(reading, join).length === 0) refuse(`the join \`${join}\` leads nowhere; draw where the work goes once its lanes have met`);
}

/**
 * Whether the diagram connects one state to another.
 *
 * Drawn, or reached through a class: any state that is not terminal may
 * move to an `anywhere` state, and a `returns` state may leave to the state
 * the record came from, which `cameFrom` names.
 */
export function connects(diagram: Diagram, from: string, to: string, cameFrom?: string): boolean {
  if (diagram.transitions.some((edge) => edge.from === from && edge.to === to)) return true;
  // A record waits in the fork while its lanes run, and moves to the join
  // once they have met: the lines between are the lanes'.
  if (diagram.forks[from]?.join === to) return true;
  if (diagram.anywhere.includes(to) && !diagram.terminal.includes(from)) return true;
  return diagram.returns.includes(from) && cameFrom === to;
}

/** The state a record was in before it last entered `state`, read from its history. */
export function cameFrom(history: readonly { readonly from: string; readonly to: string }[], state: string): string | undefined {
  for (let index = history.length - 1; index >= 0; index -= 1) {
    if (history[index]!.to === state) return history[index]!.from;
  }
  return undefined;
}

/**
 * The diagram with one state marked as where a piece of work is.
 *
 * Two ordinary Mermaid lines at the end, so the result renders wherever the
 * file does and a pull request comment shows where the work stands.
 */
export function markState(diagram: Diagram, state: string): string {
  if (!diagram.states.includes(state)) throw new Error(`the diagram draws no \`${state}\``);
  const text = diagram.text.replace(/\s*$/, "");
  return `${text}\n\n    classDef current stroke-width:3px,font-weight:bold\n    class ${state} current\n`;
}

import { ActionSpec, PortKind } from "./actions.js";
import { ActionContext, ActionImplementation, WorkflowRuntime } from "./runtime.js";
import { Action, Plan, actionsOf } from "./work.js";

/** A mounted port, looked up by kind when an action needs it. */
export type PortLookup = (kind: PortKind) => object | undefined;

/** Marks a port method as taking `(action, context)`, set by `acceptsAction`. */
const ACCEPTS_ACTION = Symbol.for("amykit.acceptsAction");

/**
 * Marks a port method as one the host may call with `(action, context)`.
 *
 * A port method written for its own callers — `check(repo, workId)`, say —
 * would be handed an action where it expects a repository, and run wrong
 * rather than fail. So a port-and-method declaration only reaches a method
 * that opted in, and the mount refuses one that did not.
 */
export function acceptsAction<F extends (action: Action, context: ActionContext) => unknown>(method: F): F {
  Object.defineProperty(method, ACCEPTS_ACTION, { value: true });
  return method;
}

/** Whether a port method opted in to being called with an action. */
function takesAnAction(method: unknown): boolean {
  return typeof method === "function" && (method as unknown as Record<symbol, unknown>)[ACCEPTS_ACTION] === true;
}

/** Whether an implementation is a port and a method rather than a handler. */
export function isPortBinding(implementation: unknown): implementation is ActionSpec {
  if (implementation === null || typeof implementation !== "object") return false;
  const { port, method } = implementation as Partial<ActionSpec>;
  return typeof port === "string" && typeof method === "string";
}

const REACHES = Symbol.for("@amykit/core/reaches");

/**
 * The port an action spends, whether it is declared as a port and a method or
 * dispatched by a host that runs one on somebody's behalf — a lane's action,
 * run against the lane's own record. What a budget asks before the call.
 */
export function portReachedBy(implementation: unknown): string | undefined {
  return declaredBinding(implementation)?.port;
}

/**
 * The port and method an action is declared to run, whether it is that
 * binding itself or a dispatcher the host built around it — so what the
 * mount checks of a binding (which port, whether it writes, whether the
 * workflow claimed the write) it checks however the action is dispatched.
 */
export function declaredBinding(implementation: unknown): ActionSpec | undefined {
  if (isPortBinding(implementation)) return implementation;
  return (implementation as { [REACHES]?: ActionSpec } | undefined)?.[REACHES];
}

/** A dispatcher that runs a declared port and method, still saying which it runs. */
export function reaching<T extends object>(dispatcher: T, binding: ActionSpec | undefined): T {
  return binding === undefined ? dispatcher : Object.assign(dispatcher, { [REACHES]: binding });
}

/** The actions a runtime declares: the keys of its map, and nothing else. */
export function declaredActions(runtime: Pick<WorkflowRuntime, "actions">): string[] {
  return Object.keys(runtime.actions);
}

/**
 * What a runtime has behind one action name, or `undefined` when it never
 * declared it. Own keys only, so `toString` is not an action.
 */
export function implementationOf(
  runtime: Pick<WorkflowRuntime, "actions">,
  name: string,
): ActionImplementation | undefined {
  return Object.hasOwn(runtime.actions, name)
    ? (runtime.actions[name] as ActionImplementation)
    : undefined;
}

/** The actions a plan carries that the runtime never declared, in order. */
export function undeclaredIn(runtime: Pick<WorkflowRuntime, "actions">, plan: Plan): string[] {
  return actionsOf(plan)
    .map((action) => action.type)
    .filter((name) => !Object.hasOwn(runtime.actions, name));
}

/**
 * Why a declared action could not run, or `null` when it could.
 *
 * Asked at boot of every key, so a declaration with nothing behind it is
 * refused by name before any work reaches the state that plans it.
 */
export function unrunnable(name: string, implementation: unknown, port: PortLookup): string | null {
  if (typeof implementation === "function") return null;
  if (!isPortBinding(implementation)) {
    return `action \`${name}\` is declared with no implementation — give it a handler, or a port and a method`;
  }

  const target = port(implementation.port);
  if (!target) {
    return `action \`${name}\`: needs the \`${implementation.port}\` port, which nothing mounted`;
  }
  const method = (target as Record<string, unknown>)[implementation.method];
  if (typeof method !== "function") {
    return `action \`${name}\`: the \`${implementation.port}\` port has no method \`${implementation.method}\``;
  }
  if (!takesAnAction(method)) {
    return (
      `action \`${name}\`: \`${implementation.port}.${implementation.method}\` takes its own arguments, not an action — ` +
      `write a handler that calls it, or mark it with \`acceptsAction\``
    );
  }
  return null;
}

/**
 * Runs one action through whatever the runtime declared for it.
 *
 * A port-and-method is called with the action and its context, and what it
 * returns — `undefined` included — lands in `outcomes` under the action's
 * name: the one shape the host can wire without the workflow writing a line.
 */
export async function runAction(
  implementation: ActionImplementation | undefined,
  action: Action,
  context: ActionContext,
  port: PortLookup,
): Promise<void> {
  if (typeof implementation === "function") {
    await implementation(action, context);
    return;
  }

  const problem = unrunnable(action.type, implementation, port);
  if (problem || !isPortBinding(implementation)) {
    throw new Error(problem ?? `action \`${action.type}\` has no implementation`);
  }

  const target = port(implementation.port) as Record<string, (...args: unknown[]) => unknown>;
  context.outcomes[action.type] = await target[implementation.method]!(action, context);
}

/** A diagram amy will not read, naming the file and the line that says why. */
export class DiagramError extends Error {
  constructor(
    readonly line: number,
    readonly reason: string,
    source: string,
  ) {
    super(line > 0 ? `${source} line ${line}: ${reason}` : `${source}: ${reason}`);
    this.name = "DiagramError";
  }
}

import fs from "node:fs";
import { Event } from "./ports/EventLog.js";

/** The vocabulary a declared field can be written in. `?` means optional. */
export type FieldType =
  | "string"
  | "number"
  | "boolean"
  | "object"
  | "array"
  | "string?"
  | "number?"
  | "boolean?"
  | "object?"
  | "array?";

export interface KindContract {
  /** What the line means, in one sentence, for whoever reads the log later. */
  says: string;
  /** Which top-level fields this kind cannot be written without. */
  requires: readonly string[];
  detail: Readonly<Record<string, FieldType>>;
}

export interface EventContract {
  version: number;
  kinds: Readonly<Record<string, KindContract>>;
}

let contract: EventContract | null = null;

/**
 * The declared contract, read from the vendored `events.json`.
 *
 * Read from disk rather than imported so the file stays a plain artifact a
 * hash lock can watch, the same way the model price table does.
 */
export function eventContract(): EventContract {
  if (contract) return contract;

  const file = new URL("../events.json", import.meta.url);
  contract = JSON.parse(fs.readFileSync(file, "utf-8")) as EventContract;
  return contract;
}

/** A field is absent when it is missing, `null` or `undefined`. */
function absent(value: unknown): boolean {
  return value === null || value === undefined;
}

function typeOf(value: unknown): string {
  if (Array.isArray(value)) return "array";
  return typeof value;
}

function wrongType(value: unknown, declared: FieldType): boolean {
  return typeOf(value) !== declared.replace("?", "");
}

function detailViolations(kind: string, detail: Record<string, unknown>, of: KindContract): string[] {
  const problems: string[] = [];

  for (const [field, declared] of Object.entries(of.detail)) {
    const value = detail[field];
    if (absent(value)) {
      if (!declared.endsWith("?")) problems.push(`${kind}: detail.${field} is required`);
      continue;
    }
    if (wrongType(value, declared)) {
      problems.push(`${kind}: detail.${field} should be ${declared}, got ${typeOf(value)}`);
    }
  }

  for (const field of Object.keys(detail)) {
    if (!(field in of.detail)) {
      problems.push(`${kind}: detail.${field} is not declared in events.json`);
    }
  }

  return problems;
}

/**
 * What a line breaks in the contract, or nothing if it keeps it.
 *
 * An undeclared `detail` field is a violation, not a courtesy: a field that
 * slips in unannounced is how the declaration rots into fiction while every
 * reader carries on guessing.
 */
export function checkEvent(event: Event, against: EventContract = eventContract()): string[] {
  const of = against.kinds[event.kind];
  if (!of) return [`${String(event.kind)} is not a kind events.json declares`];

  const problems: string[] = [];
  const top = event as unknown as Record<string, unknown>;

  if (absent(event.at)) problems.push(`${event.kind}: at is required`);

  for (const field of of.requires) {
    if (absent(top[field])) problems.push(`${event.kind}: ${field} is required`);
  }

  return [...problems, ...detailViolations(event.kind, event.detail ?? {}, of)];
}

import { callPath } from "./calls.js";
import { DIAGRAM_CLASSES, Diagram } from "./diagram.js";
import { Workflow } from "./plugin.js";
import { WorkRecord } from "./work.js";

/**
 * A workflow's diagram with every call drawn as what it calls: a Mermaid
 * composite state, `state REVIEW { … }`, holding the callee's own diagram.
 *
 * For reading only. It is valid Mermaid and renders wherever the file does,
 * but the source subset still refuses a composite state: a source file holds
 * one workflow, and a call holds the rest. Inner states are named after the
 * call state they sit in (`REVIEW__FIX`), so two workflows that both have a
 * `DONE` draw two states. Given a record, the state it is in at every depth
 * is marked.
 */
export function expandDiagram(workflow: Workflow, record?: WorkRecord): string {
  const diagram = drawnOf(workflow);
  const lines = [diagram.text.replace(/\s*$/, "")];
  const classes: string[] = [];
  const taken = new Set(diagram.states);
  for (const state of diagram.calls) {
    const callee = workflow.calls?.[state];
    if (callee) lines.push("", ...composite(state, callee, "    ", classes, taken));
  }
  lines.push(...classes);
  const marked = record ? markedPath(workflow, record) : [];
  if (marked.length > 0) {
    lines.push("", "    classDef current stroke-width:3px,font-weight:bold", `    class ${marked.join(",")} current`);
  }
  return `${lines.join("\n")}\n`;
}

function drawnOf(workflow: Workflow): Diagram {
  if (!workflow.diagram) throw new Error(`${workflow.name} has no diagram to expand: its states are declared in its code`);
  return workflow.diagram;
}

function composite(prefix: string, callee: Workflow, indent: string, classes: string[], taken: Set<string>): string[] {
  const diagram = drawnOf(callee);
  const id = (state: string): string => `${prefix}__${state}`;
  claim(prefix, diagram.states.map(id), taken);
  const inner = `${indent}    `;
  const lines = [`${indent}state ${prefix} {`];
  for (const state of diagram.states) lines.push(`${inner}${declared(diagram, state, id(state))}`);
  lines.push(`${inner}[*] --> ${id(diagram.initial)}`);
  for (const edge of diagram.transitions) lines.push(`${inner}${id(edge.from)} --> ${id(edge.to)}${edge.label ? `: ${edge.label}` : ""}`);
  for (const state of diagram.terminal) lines.push(`${inner}${id(state)} --> [*]`);
  for (const state of diagram.calls) {
    const called = callee.calls?.[state];
    if (called) lines.push(...composite(id(state), called, inner, classes, taken));
  }
  lines.push(`${indent}}`);
  // Outside the block, where a class line is read for any state it names.
  for (const name of DIAGRAM_CLASSES) {
    const states = diagram[name === "call" ? "calls" : name];
    if (states.length > 0) classes.push(`    class ${states.map(id).join(",")} ${name}`);
  }
  return lines;
}

/** How a state is named inside a composite: a fork and a join keep their shape, so its lanes still read as lanes. */
function declared(diagram: Diagram, state: string, id: string): string {
  if (diagram.forks[state]) return `state ${id} <<fork>>`;
  if (Object.values(diagram.forks).some((fork) => fork.join === state)) return `state ${id} <<join>>`;
  return `state "${diagram.labels[state] ?? state}" as ${id}`;
}

/** Mermaid has one namespace for every id, composite or not, so each drawn id is taken once. */
function claim(prefix: string, ids: readonly string[], taken: Set<string>): void {
  for (const id of ids) {
    if (taken.has(id)) throw new Error(`expanding \`${prefix}\` would draw \`${id}\` twice; rename one of the two states`);
    taken.add(id);
  }
}

/**
 * The id the record is drawn at, at every depth of its call path — and, for
 * a record waiting in a fork, where each lane's own record is, so every lane
 * carries its mark.
 */
function markedPath(workflow: Workflow, record: WorkRecord, prefix = ""): string[] {
  const ids: string[] = [];
  let at: Workflow | undefined = workflow;
  let under = prefix;
  for (const step of callPath(record)) {
    if (!at) break;
    const id = under ? `${under}__${step.state}` : step.state;
    ids.push(id);
    for (const lane of at.diagram?.forks[step.state]?.lanes ?? []) {
      const call = step.lanes?.[lane]?.call;
      const child = call === undefined ? undefined : step.calls?.[call];
      const callee = at.calls?.[lane];
      if (child && callee) ids.push(...markedPath(callee, child, under ? `${under}__${lane}` : lane));
    }
    at = at.calls?.[step.state];
    under = id;
  }
  return ids;
}

import fs from "node:fs";
import path from "node:path";
import { BranchLeases, LeaseHeld, STANDING_CHECKOUT, runningLane } from "./leases.js";
import { CommandRunner } from "./ports/CommandRunner.js";
import { Worktree } from "./ports/Worktree.js";

export interface RepoLayout {
  /** Directory that holds one checkout per repository. */
  workspaceRoot: string;
  /**
   * Where one repository's checkout is, instead of under the root.
   *
   * A repository named here is never looked for under `workspaceRoot` at all,
   * which is what makes the answer one fact rather than two guesses: work can
   * span repositories two unrelated parents hold, with no symlink holding the
   * map together and nothing in the state directory standing for config.
   */
  checkouts?: Readonly<Record<string, string>>;
  /** Branch new work is cut from. */
  defaultBranch: string;
  /**
   * Where one repository's base branch is, instead of the fallback.
   *
   * A repository named here is cut from, and opened against, its own branch;
   * every other keeps `defaultBranch`. The map is passed through whole rather
   * than resolved at the edge, because the slice is built once and the
   * repository is known per piece of work.
   */
  baseBranch?: Readonly<Record<string, string>>;
}

/**
 * The one base branch answer there is: a repository that named its own is
 * answered by that name, and every other keeps the fallback.
 *
 * Both halves of `RepoLayout` answer here, beside `checkoutFor`, so no caller
 * re-derives the rule and a second reader cannot drift from the first.
 */
export function baseBranchFor(layout: RepoLayout, repo: string): string {
  return layout.baseBranch?.[repo] ?? layout.defaultBranch;
}

/**
 * The one checkout answer there is: a repository that named its own root is
 * found there, and every other is found under the shared root.
 *
 * Both halves of `RepoLayout` answer here so no caller ever re-derives the
 * rule, and `amy doctor` asks the same function, so a missing checkout names
 * the root that was actually asked.
 */
export function checkoutFor(layout: RepoLayout, repo: string): string {
  const named = layout.checkouts?.[repo];
  if (named !== undefined) return named;
  const name = repo.includes("/") ? repo.slice(repo.indexOf("/") + 1) : repo;
  return path.join(layout.workspaceRoot, name);
}

/**
 * The git side of a ticket: get onto its branch, and get the work pushed.
 *
 * The branch name is always the one the tracker gave us, never derived here,
 * because the tracker owns the slug and links the pull request by it.
 *
 * One class answers both modes, and nothing about the mode is decided here:
 * when a worktree port was mounted, `pathFor` resolves through it and every
 * path hands out is the item's own tree; when none was, it resolves through
 * `workspaceRoot` exactly as it always did. A caller never changes shape.
 */
export class Git {
  /**
   * `worktrees` is the port itself, or how to read it when it is needed: the
   * host lends a reader, so a worktree plugin listed after the one holding
   * this `Git` is still the one every path resolves through.
   */
  constructor(
    private readonly runner: CommandRunner,
    private readonly layout: RepoLayout,
    private readonly worktreesOf?: Worktree | (() => Worktree | undefined),
    private readonly leases?: BranchLeases,
    private readonly lentTo?: (workId: string) => string | undefined,
  ) {}

  /**
   * The same checkouts, for a lane: a branch is taken before it is checked
   * out or pushed, and a branch another lane holds is a `LeaseHeld`, which
   * the lane waits on rather than fails. `lent` names the commit a lane was
   * lent, if any: that lane's tree is detached at it whatever it asks for,
   * and no move is made in it.
   */
  leasedTo(leases: BranchLeases, lent?: (workId: string) => string | undefined): Git {
    // Composed rather than replaced: a lane lent a commit that calls a
    // workflow with lanes of its own lends that commit to them too.
    const outer = this.lentTo;
    const lentTo = lent && outer ? (workId: string) => lent(workId) ?? outer(workId) : lent ?? outer;
    return new Git(this.runner, this.layout, this.worktreesOf, leases, lentTo);
  }

  private get worktrees(): Worktree | undefined {
    return typeof this.worktreesOf === "function" ? this.worktreesOf() : this.worktreesOf;
  }

  /**
   * Where the work for one repository happens.
   *
   * The mode question is answered once, here, rather than by every caller:
   * the agent steps, the gates and the workflow runtimes all read this, and
   * none of them learns whether this install isolates its checkouts.
   */
  pathFor(repo: string, workId?: string): string {
    const worktrees = this.worktrees;
    if (worktrees && workId !== undefined) {
      return worktrees.pathFor(workId, repo);
    }
    return checkoutFor(this.layout, repo);
  }

  /**
   * Makes the item's workplace before an agent is sent there.
   *
   * Triage is the first agent step and precedes branch preparation, so merely
   * computing `pathFor` would hand a harness a directory that does not exist.
   * The shared mode remains a no-op path lookup.
   */
  async acquire(repo: string, workId?: string): Promise<string> {
    const lent = workId === undefined ? undefined : this.lentTo?.(workId);
    if (lent !== undefined) return this.atRevision(repo, lent, workId!);
    const worktrees = this.worktrees;
    if (worktrees && workId !== undefined) return worktrees.acquire(workId, repo);
    return this.pathFor(repo);
  }

  private async git(repo: string, ...args: string[]) {
    const result = await this.runner.run("git", args, { cwd: this.pathFor(repo) });
    if (!result.ok) {
      throw new Error(`git ${args.join(" ")} failed in ${repo}: ${result.stderr || result.stdout}`);
    }
    return result;
  }

  /**
   * Puts the work on the ticket's branch, creating it from the default
   * branch when it does not exist yet.
   *
   * With a worktree port behind it, the branch is prepared inside the item's
   * own tree and never touches the standing checkout: acquiring the tree
   * makes no move at all, and `--ignore-other-worktrees` is what lets a
   * branch that exists because another item carried it be checked out here
   * without the second tree refusing or the first tree losing its place.
   */
  async prepareBranch(repo: string, branch: string, workId?: string): Promise<void> {
    this.mayMove(repo, branch, workId);
    const worktrees = this.worktrees;
    if (worktrees && workId !== undefined) {
      const tree = await worktrees.acquire(workId, repo);
      await this.onBranch(tree, repo, branch, ["--ignore-other-worktrees"]);
      return;
    }
    await this.onBranch(this.pathFor(repo), repo, branch, []);
  }

  /**
   * Gets onto `branch` in `cwd` without ever discarding a commit on it.
   *
   * A local branch can hold a commit the remote never saw: the machine
   * committed and the push failed. Resetting it to the remote, or to the
   * base, erases that work with nothing to say it existed, so the branch only
   * moves forward. When the target is ahead of it, the branch fast-forwards;
   * when it is ahead of the target, it is kept, and `commitAndPush` pushes
   * what it holds; when it has diverged from its remote, it is refused,
   * naming what only the local side holds.
   */
  private async onBranch(cwd: string, repo: string, branch: string, flags: string[]): Promise<void> {
    await this.gitIn(cwd, "fetch", "origin", "--prune");

    const remote = `refs/remotes/origin/${branch}`;
    const local = `refs/heads/${branch}`;
    const onRemote = await this.succeeds(cwd, "rev-parse", "--verify", remote);
    const target = onRemote ? `origin/${branch}` : `origin/${baseBranchFor(this.layout, repo)}`;

    if (!(await this.succeeds(cwd, "rev-parse", "--verify", local))) {
      await this.gitIn(cwd, "checkout", "-b", branch, target, ...flags);
      return;
    }

    if (await this.succeeds(cwd, "merge-base", "--is-ancestor", local, target)) {
      await this.gitIn(cwd, "checkout", branch, ...flags);
      await this.gitIn(cwd, "merge", "--ff-only", target);
      return;
    }

    if (onRemote && !(await this.succeeds(cwd, "merge-base", "--is-ancestor", remote, local))) {
      const unpushed = await this.gitIn(cwd, "log", "--oneline", `${target}..${local}`);
      throw new Error(
        `${branch} has diverged from ${target} in ${cwd}; refusing to reset it and lose what only the local branch holds:\n${unpushed.stdout.trim()}`,
      );
    }

    await this.gitIn(cwd, "checkout", branch, ...flags);
  }

  /** Whether git answered yes, for the commands whose exit code is the answer. */
  private async succeeds(cwd: string, ...args: string[]): Promise<boolean> {
    return (await this.runner.run("git", args, { cwd })).ok;
  }

  /** The commit the tree is at: the item's own, when a work id is named. */
  async headSha(repo: string, workId?: string): Promise<string> {
    if (workId === undefined) return (await this.git(repo, "rev-parse", "HEAD")).stdout;
    return (await this.gitIn(this.cwdFor(repo, workId), "rev-parse", "HEAD")).stdout.trim();
  }

  /**
   * A tree of the item's own, detached at a commit somebody else made, to
   * check and not to change.
   *
   * What a lane bound with `revision` is lent: every lane of a fork sees the
   * caller's commit rather than the base, and none of them can move the
   * caller's branch — the tree is detached, and every move this class makes
   * refuses a tree lent this way. Needs a worktree port: a revision is never
   * checked out in the standing checkout somebody may be working in.
   */
  async atRevision(repo: string, revision: string, workId: string): Promise<string> {
    const worktrees = this.worktrees;
    if (!worktrees) {
      throw new Error(`${workId} was lent ${revision.slice(0, 7)} to check, and no worktree is mounted to check it in; a revision is never checked out in the standing checkout`);
    }
    const tree = await worktrees.acquire(workId, repo);
    if (!(await this.succeeds(tree, "cat-file", "-e", `${revision}^{commit}`))) await this.gitIn(tree, "fetch", "origin", "--prune");
    await this.gitIn(tree, "checkout", "--detach", revision);
    const marker = lentMarker(tree);
    if (marker) fs.writeFileSync(marker, `${revision}\n`, "utf-8");
    return tree;
  }

  /**
   * Refuses a move in a tree lent at a revision, and a branch another lane
   * holds. Asked before a branch is checked out, committed on or pushed.
   */
  private mayMove(repo: string, branch: string | undefined, workId: string | undefined): void {
    const lane = this.leases ? runningLane.getStore() : undefined;
    if (lane !== undefined) return this.laneMayMove(lane, repo, branch, workId);
    if (workId !== undefined) this.notLent(repo, branch, workId);
  }

  /** Refuses a move in a tree lent at a revision, naming the commit. */
  private notLent(repo: string, branch: string | undefined, workId: string): void {
    const worktrees = this.worktrees;
    const lent = this.lentTo?.(workId) ?? (worktrees ? lentIn(worktrees.pathFor(workId, repo)) : undefined);
    if (lent) {
      throw new Error(`${workId} was lent ${lent.slice(0, 7)} to check, and checks it read-only: it cannot move ${branch ?? "a branch"} in ${repo}`);
    }
  }

  /**
   * A move a lane makes: only of its own work — never its caller's, never the
   * standing checkout's by passing no work id — never in a tree it was lent,
   * and only once it holds what it moves: the branch, in a tree of its own,
   * or the whole checkout, when the lanes share one.
   */
  private laneMayMove(lane: string, repo: string, branch: string | undefined, workId: string | undefined): void {
    if (workId === undefined || (workId !== lane && !workId.startsWith(`${lane}/`))) {
      throw new Error(`${lane} is a lane, and moves only its own work: it cannot move ${branch ?? "a branch"} in ${repo} as ${workId ?? "the standing checkout"}`);
    }
    this.notLent(repo, branch, workId);
    const held = this.worktrees ? branch : STANDING_CHECKOUT;
    if (held === undefined) return;
    const lease = this.leases!.take(repo, held, workId);
    if (!lease.taken) throw new LeaseHeld(repo, held, lease.holder);
  }

  /**
   * How many commits the branch in this item's tree holds beyond `of`.
   *
   * The question `commitAndPush` cannot answer by itself: a branch published
   * for the first time is a new remote ref whether or not it carries a
   * commit, so "a ref appeared" is not "there is something to review".
   */
  async commitsAhead(repo: string, of: string, workId?: string): Promise<number> {
    const result = await this.gitIn(
      this.cwdFor(repo, workId),
      "rev-list",
      "--count",
      `refs/remotes/origin/${of}..HEAD`,
    );
    return Number.parseInt(result.stdout.trim(), 10) || 0;
  }

  /**
   * Moves whatever the tree holds into a labelled stash, and leaves it clean.
   *
   * For work that must not be published and must not be lost: no branch
   * moves, so nothing a later branch reuses carries it, and no commit hook
   * runs, so unfinished work cannot refuse to be set aside. False when the
   * tree was already clean.
   */
  async setAside(repo: string, label: string, workId?: string): Promise<boolean> {
    const cwd = this.cwdFor(repo, workId);
    if (!(await this.hasChangesIn(cwd))) return false;
    await this.gitIn(cwd, "stash", "push", "--include-untracked", "--message", label);
    return true;
  }

  async hasChanges(repo: string, workId?: string): Promise<boolean> {
    const status = await this.gitIn(this.cwdFor(repo, workId), "status", "--porcelain");
    return status.stdout.length > 0;
  }

  /**
   * Commits whatever the agent left behind, and goes no further.
   *
   * A workflow that wants no round of work ever lost commits after each one,
   * and lets the remote see them once per cycle. Returns false when the tree
   * was clean, which is a real outcome rather than a failure.
   */
  async commit(repo: string, message: string, workId?: string): Promise<boolean> {
    this.mayMove(repo, undefined, workId);
    const cwd = this.cwdFor(repo, workId);
    if (!(await this.hasChangesIn(cwd))) return false;
    await this.gitIn(cwd, "add", "-A");
    await this.gitIn(cwd, "commit", "-m", message);
    return true;
  }

  /**
   * Pushes what the branch holds that the remote does not, as a fast-forward
   * or not at all.
   *
   * Returns false when the remote branch already held exactly this. The
   * answer is git's own, about the named branch: a count of commits missing
   * from every remote ref said "nothing to push" for a new branch cut at a
   * commit another branch had already pushed, and the branch never appeared.
   *
   * A remote branch somebody else moved is refused by git, and the refusal
   * is rethrown naming the branch, so the caller learns which one to fetch
   * rather than reading git's own words about refs. Nothing local is touched
   * by a refusal.
   */
  async push(repo: string, branch: string, workId?: string): Promise<boolean> {
    this.mayMove(repo, branch, workId);
    return this.pushIn(this.cwdFor(repo, workId), branch);
  }

  private async pushIn(cwd: string, branch: string): Promise<boolean> {
    const result = await this.runner.run("git", ["push", "--porcelain", "--set-upstream", "origin", branch], { cwd });
    if (result.ok) return updated(result.stdout, branch);
    const said = `${result.stderr}\n${result.stdout}`;
    if (/non-fast-forward|fetch first|\[rejected\]/.test(said)) {
      throw new Error(
        `refusing to push ${branch} from ${cwd}: origin/${branch} holds commits this branch does not, so the push is not a fast-forward. Fetch, and bring ${branch} forward onto it before pushing again.`,
      );
    }
    throw new Error(`git push --set-upstream origin ${branch} failed in ${cwd}: ${result.stderr || result.stdout}`);
  }


  /**
   * Commits and pushes whatever the agent left behind, in one call.
   *
   * Returns false when there was nothing to commit and nothing to push, which
   * is a real outcome rather than a failure: an agent asked to address a
   * comment may correctly decide the code already says what it should. A
   * commit an earlier push never delivered is something to push, so a clean
   * tree still pushes it, and that counts.
   */
  async commitAndPush(
    repo: string,
    branch: string,
    message: string,
    workId?: string,
  ): Promise<boolean> {
    // A clean tree still pushes: a commit an earlier push never delivered
    // is something to push, and only git knows whether the branch has it.
    const committed = await this.commit(repo, message, workId);
    const pushed = await this.push(repo, branch, workId);
    return committed || pushed;
  }

  /** The tree the work happens in, for the mode this install chose. */
  private cwdFor(repo: string, workId?: string): string {
    const worktrees = this.worktrees;
    if (worktrees && workId !== undefined) {
      return worktrees.pathFor(workId, repo);
    }
    return this.pathFor(repo);
  }

  private async hasChangesIn(cwd: string): Promise<boolean> {
    const status = await this.gitIn(cwd, "status", "--porcelain");
    return status.stdout.length > 0;
  }

  /** The same git, run in a named tree rather than in the standing checkout. */
  private async gitIn(cwd: string, ...args: string[]) {
    const result = await this.runner.run("git", args, { cwd });
    if (!result.ok) {
      throw new Error(`git ${args.join(" ")} failed in ${cwd}: ${result.stderr || result.stdout}`);
    }
    return result;
  }
}

/**
 * Whether `git push --porcelain` moved the named branch: a line for it
 * flagged new (`*`) or fast-forwarded (a space), rather than up to date (`=`).
 */
function updated(porcelain: string, branch: string): boolean {
  return porcelain.split("\n").some((line) => {
    const [flag, refs] = line.split("\t");
    return (flag === "*" || flag === " ") && (refs ?? "").endsWith(`:refs/heads/${branch}`);
  });
}

/**
 * Where a tree records the revision it was lent: inside its own git
 * directory, so the mark goes when the tree does and never shows as a change
 * in it. Undefined for a tree that does not exist or is not a worktree.
 */
function lentMarker(tree: string): string | undefined {
  try {
    const pointer = fs.readFileSync(path.join(tree, ".git"), "utf-8").trim();
    const gitDir = /^gitdir:\s*(.+)$/.exec(pointer)?.[1];
    return gitDir ? path.join(path.resolve(tree, gitDir), "amy-lent-revision") : undefined;
  } catch {
    return undefined;
  }
}

/** The revision a tree was lent at, or undefined for a tree that is its own. */
function lentIn(tree: string): string | undefined {
  const marker = lentMarker(tree);
  if (!marker || !fs.existsSync(marker)) return undefined;
  return fs.readFileSync(marker, "utf-8").trim();
}

