  /** Core actions plus whatever plugins added. */
  actions: Map<string, ActionSpec>;

  /** Named collections several plugins may add to, keyed by collection. */
  contributions: Map<string, Map<string, object>>;
  plugins: string[];
}

export type MountOutcome =
  | { ok: true; mounted: Mounted }
  | { ok: false; problems: string[] };

/** An embedding may require one workflow without changing generic plugin mounts. */
export interface MountRequirements {
  /** Label supplied by the host and repeated in the boot refusal. */
  readonly workflowLabel?: string;
  /** The configured plugin that must contribute the workflow. */
  readonly workflowPlugin?: Plugin;
}

/**
 * Assembles a set of plugins into one working host.
 *
 * Every refusal happens here, at boot, by name. The alternative is finding out
 * halfway through somebody's ticket that a setting was a typo, or that two
 * plugins both thought they were the tracker.
 */
export async function mount(
  plugins: readonly Plugin[],
  config: Readonly<Record<string, unknown>>,
  host: HostServices,
  requirements: MountRequirements = {},
): Promise<MountOutcome> {
  const problems: string[] = [];
  const mounted: Mounted = {
    ports: new Map(),
    actions: new Map(Object.entries(CORE_ACTIONS)),

    contributions: new Map(),
    plugins: [],
  };

  const registered: { plugin: Plugin; ctx: PluginContext }[] = [];
  const workflowFor = new WeakMap<PluginContext, Workflow<never, never>>();
  const workflowOwners = new Set<Plugin>();
  const mutablePortKinds = new WeakMap<object, MutablePortKind>();
  const builds = new Builds(problems);

  for (const plugin of plugins) {
    const settings = configFor(plugin.name, plugin.configSchema, config[plugin.name], problems);
    if (settings === null) continue;

    let finishRegistration!: () => void;
    const registrationComplete = new Promise<void>((resolve) => { finishRegistration = resolve; });
    const ctx = contextFor(settings, mounted, host, workflowFor, mutablePortKinds, registrationComplete, builds);

    try {
      await plugin.register(registrarFor(plugin, mounted, problems, ctx, workflowFor, workflowOwners, mutablePortKinds, builds), ctx);
    } catch (error) {
      // A plugin that cannot set itself up is a problem with a name, not an
      // unhandled throw that takes the whole boot down anonymously.
      problems.push(
        `${plugin.name}: failed to mount — ${error instanceof Error ? error.message : String(error)}`,
      );
      continue;
    } finally {
      // A mutable port acquired before a workflow declares itself must not
      // decide it is a provider call merely because registration awaited.
      // Deferred wrappers decide only once this plugin's registration ends.
      finishRegistration();
    }

    mounted.plugins.push(plugin.name);
    registered.push({ plugin, ctx });
  }

  // Every deferred implementation, built once every plugin has registered and
  // before any `ready`, so a `ready` reads built things and a build that
  // throws is a refusal with a name. Skipped when something already went
  // wrong, for the same reason the pass below is.
  if (problems.length === 0) builds.buildAll();

  // A second pass, because a plugin that composes others can only judge its
  // own settings once those others have contributed themselves. Skipped when
  // something already went wrong, since a later complaint about a missing
  // contribution would just be an echo of the earlier refusal.
  if (problems.length === 0) await judgeReady(registered, problems);

  if (requiresWorkflow(requirements, mounted, workflowOwners)) {
    problems.push(`${requirements.workflowLabel}: exports no workflow`);
  }

  return problems.length > 0 ? { ok: false, problems } : { ok: true, mounted };
}

/** Runs every `ready`, each refusal named by its plugin. */
async function judgeReady(registered: readonly { plugin: Plugin; ctx: PluginContext }[], problems: string[]): Promise<void> {
  for (const { plugin, ctx } of registered) {
    if (!plugin.ready) continue;

    try {
      await plugin.ready(ctx);
    } catch (error) {
      problems.push(
        `${plugin.name}: ${error instanceof Error ? error.message : String(error)}`,
      );
    }
  }
}

/**
 * What a plugin or workflow is told when the machine carries no workplace.
 *
 * The workflow a call site names comes first: a called workflow's checkouts
 * are asked for through its caller's context, and it is the callee whose
 * work stopped. Otherwise the workflow the context registered, and with
 * neither, the plugin — the mount already prefixes that with the plugin's
 * name, so the refusal names whichever thing wants a workspace.
 */
function askedWithoutAWorkspace(workflow: string | undefined, who: string | undefined): string {
  const asked = who ?? workflow;
  return asked
    ? `the ${asked} workflow asked for the machine's checkouts, and nothing mounted a workspace — add @amykit/plugin-file-worktree to the profile's plugins`
    : "this plugin asks for the machine's checkouts, and nothing mounted a workspace — add @amykit/plugin-file-worktree to the plugins that mount first";
}

function requiresWorkflow(requirements: MountRequirements, mounted: Mounted, workflowOwners: ReadonlySet<Plugin>): boolean {
  return Boolean(requirements.workflowLabel && (!mounted.workflow ||
    (requirements.workflowPlugin && !workflowOwners.has(requirements.workflowPlugin))));
}

function configFor(
  plugin: string,
  schema: ConfigSchema | undefined,
  given: unknown,
  problems: string[],
): Record<string, unknown> | null {
  if (!schema) {
    if (given !== undefined) {
      problems.push(`${plugin}: has no settings, but the config gives it some`);
      return null;
    }
    return {};
  }

  const result = validateConfig(plugin, schema, given);
  if (!result.ok) {
    problems.push(...result.problems);
    return null;
  }

  return result.config;
}

/**
 * The context one plugin sees.
 *
 * `contributions` and `port` read the mounted state when they are called, not
 * when the context is made, so a plugin that composes others is not at the
 * mercy of the order plugins were listed in.
 */
function contextFor(
  config: Record<string, unknown>,
  mounted: Mounted,
  host: HostServices,
  workflowFor: WeakMap<PluginContext, Workflow<never, never>>,
  mutablePortKinds: WeakMap<object, MutablePortKind>,
  registrationComplete: Promise<void>,
  builds: Builds,
): PluginContext {
  const ctx: PluginContext = {
    config,
    runner: host.runner,
    now: host.now,
    log: host.log,
    paths: host.paths,
    readOnly: host.readOnly === true,
    contributions: (collection) => builds.collection(mounted.contributions.get(collection)),
    // This remains deferred until a workflow registers. A workflow plugin can
    // retain this view while it registers; it must never retain the raw port.
    // Other plugins also compose independent contracts (for example the
    // feature-grooming seam); engines use `workflowPort` for selected actions.
    port: (kind) => narrowedPort(
      builds.resolve(mounted.ports.get(kind)), kind, () => workflowFor.get(ctx), mutablePortKinds, registrationComplete,
    ),
    checkouts: (who) => lentWhenRead(() => {
      const workspace = builds.resolve(mounted.ports.get(WORKSPACE_PORT)) as Workspace | undefined;
      if (!workspace) {
        throw new Error(askedWithoutAWorkspace(workflowFor.get(ctx)?.name, who));
      }
      return checkoutsFromWorkspace(host.runner, workspace, config, () => ctx.port("worktree") as Worktree | undefined);
    }),
    workflowPort: (kind) => narrowedPort(
      builds.resolve(mounted.ports.get(kind)), kind, () => mounted.workflow, mutablePortKinds, registrationComplete,
    ),
    workflow: () => mounted.workflow,
  };
  return ctx;
}

/**
 * A workflow receives a private view of its mutable external ports. The mounted
 * port remains whole for adapters. A workflow's own context and an engine's
 * workflow dispatch view are attenuated before either can invoke an action.
 */
const TRACKER_READ_METHODS = new Set(["inProgress", "get", "comments", "hasReplyAfter"]);
const CODE_HOST_READ_METHODS = new Set([
  "findPullRequest",
  "findPullRequestMentioning",
  "pullRequestAncestry",
  "authoredWithChangesRequested",
  "reviewLoad",
  "reviewsRequestedOf",
  "changesRequestedOf",
  "pullRequest",
  "commitStatuses",
]);

function narrowedPort(
  port: object | undefined,
  kind: PortKind,
  workflowFor: () => Workflow<never, never> | undefined,
  mutablePortKinds: WeakMap<object, MutablePortKind>,
  registrationComplete: Promise<void>,
): object | undefined {
  if (!port) return port;
  const scopedKind = mutablePortKind(port, kind, mutablePortKinds);
  if (!scopedKind) return port;
  // A dispatched action whose mutable contract is unknown cannot be handed
  // whole to a workflow. Boot names it; this empty view is defence in depth.
  if (scopedKind === "unknown") return new Proxy(Object.create(null), {
    getPrototypeOf: () => null,
    get: () => undefined,
  });
  const methods = scopedKind === "tracker" ? TRACKER_WRITE_FOR_METHOD : CODE_HOST_WRITE_FOR_METHOD;
  const capabilities = () => {
    const workflow = workflowFor();
    return scopedKind === "tracker"
      ? new Set(workflow?.trackerWrites ?? [])
      : new Set(workflow?.codeHostWrites ?? []);
  };

  const reads = scopedKind === "tracker" ? TRACKER_READ_METHODS : CODE_HOST_READ_METHODS;
  // Do not proxy the adapter itself: its prototype and own properties would
  // otherwise remain discoverable through reflection. The workflow gets a
  // blank object carrying only contract readers and the writers it claimed.
  const view = new Proxy(Object.create(null), {
    ownKeys() {
      return workflowFor() ? [] : Reflect.ownKeys(port);
    },
    getOwnPropertyDescriptor(_target, property) {
      if (workflowFor()) return undefined;
      const descriptor = Reflect.getOwnPropertyDescriptor(port, property);
      // Reflection is another way to retain a property before the workflow
      // declares itself. Never hand its raw value or accessor out through a
      // descriptor: a retained getter can otherwise disclose an adapter-owned
      // client after the workflow becomes attenuated.
      return deferredDescriptor(descriptor, workflowFor, port, property, registrationComplete);
    },
    getPrototypeOf() {
      // A prototype is adapter-owned state too. In particular, handing it out
      // while a workflow is registering lets that workflow retain prototype
      // helpers or accessors after its declaration closes the port.
      return null;
    },
    get(_target, property) {
      if (typeof property !== "string") return undefined;
      // Provider plugins may compose an independent seam before they register
      // a workflow. Resolve a callable when it is invoked rather than handing
      // out a bound adapter method: a workflow may cache it before registering
      // and must still become attenuated once it claims a workflow.
      if (!workflowFor()) {
        const initial = Reflect.get(port, property);
        const capability = methods[property];
        // Do not make a pre-declaration write wait for registration. An async
        // plugin may await this call before it declares its workflow; waiting
        // for the registration promise there would make boot wait on itself.
        // A provider can still compose read and non-contract seams during
        // registration, but a mutable contract call is never valid in that
        // window and fails closed immediately.
        if (capability) {
          return async (...args: unknown[]): Promise<unknown> => {
            // A callable acquired before declaration must not retain the
            // pre-declaration rejection forever. If it is invoked after this
            // context declares its workflow, resolve it through the same
            // allow-listed view as a freshly acquired callable.
            if (workflowFor()) {
              const narrowed = Reflect.get(view, property);
              return typeof narrowed === "function" ? narrowed(...args) : undefined;
            }
            throw new Error(`the workflow cannot call the ${scopedKind} write \`${capability}\` (${property}) before registration`);
          };
        }
        // Contract readers do not expand a workflow's authority, and a
        // registering plugin may need one to decide which workflow to expose.
        // Do not defer them behind registration completion: an async register
        // that awaits a reader before declaring would otherwise deadlock boot.
        const reader = registrationReader(initial, property, reads, port);
        if (reader) return reader;
        // A workflow may retain an adapter-owned client or runner before it
        // declares its surface just as easily as it may retain a method. Keep
        // objects deferred too: provider composition remains live until this
        // context registers a workflow, but a retained internal object becomes
        // opaque when that declaration takes effect.
        if (typeof initial !== "function") return deferredPortValue(initial, workflowFor, undefined, registrationComplete);
        return (...args: unknown[]) => registrationComplete.then(() => {
          // An async workflow can await before declaring itself. Decide only
          // after registration completes, when it either has a declaration or
          // is known to be an independent provider context.
          const value = workflowFor()
            ? Reflect.get(view, property)
            : initial;
          if (typeof value !== "function") return value;
          return value.apply(workflowFor() ? undefined : port, args);
        });
      }
      const capability = methods[property];
      if (!reads.has(property) && !capability) return undefined;
      const value = Reflect.get(port, property);
      if (typeof value !== "function") return undefined;
      if (!capability || capabilities().has(capability)) {
        const bound = value.bind(port);
        // `acceptsAction` is an opt-in marker on a callable. Binding changes
        // its receiver but does not copy the one public dispatch marker. Do
        // not copy arbitrary symbols: those may point back into an adapter.
        const acceptsAction = Symbol.for("amykit.acceptsAction");
        const descriptor = Object.getOwnPropertyDescriptor(value, acceptsAction);
        if (descriptor) Object.defineProperty(bound, acceptsAction, descriptor);
        return bound;
      }
      return async (): Promise<never> => {
        throw new Error(`the workflow does not claim the ${scopedKind} write \`${capability}\` (${property})`);
      };
    },
  });
  // A provider can re-export this deferred view under a consumer-facing alias
  // before it registers its workflow. Record the contract on the view itself
  // so the alias keeps the mutable kind when another workflow asks for it.
  mutablePortKinds.set(view, scopedKind);
  return view;
}

/** Invoke contract readers during registration without exposing other adapter methods. */
function registrationReader(
  value: unknown,
  property: string,
  reads: ReadonlySet<string>,
  receiver: object,
): (() => unknown) | undefined {
  if (typeof value !== "function" || !reads.has(property)) return undefined;
  return value.bind(receiver);
}

function deferredPortValue(
  value: unknown,
  workflowFor: () => Workflow<never, never> | undefined,
  receiver?: object,
  registrationComplete?: Promise<void>,
): unknown {
  if (typeof value === "function") {
    return (...args: unknown[]) => (registrationComplete ?? Promise.resolve()).then(() => {
      if (workflowFor()) return undefined;
      return value.apply(receiver, args);
    });
  }
  if (!value || typeof value !== "object") return value;
  return new Proxy(Object.create(null), {
    get(_target, property) {
      return workflowFor()
        ? undefined
        : deferredPortValue(Reflect.get(value, property), workflowFor, value, registrationComplete);
    },
    ownKeys() {
      return workflowFor() ? [] : Reflect.ownKeys(value);
    },
    getOwnPropertyDescriptor(_target, property) {
      return workflowFor()
        ? undefined
        : deferredDescriptor(
          Reflect.getOwnPropertyDescriptor(value, property), workflowFor, value, property, registrationComplete,
        );
    },
    getPrototypeOf() {
      return null;
    },
  });
}

/** Rebuild reflection descriptors so neither values nor accessors retain raw adapter state. */
function deferredDescriptor(
  descriptor: PropertyDescriptor | undefined,
  workflowFor: () => Workflow<never, never> | undefined,
  receiver: object,
  property: PropertyKey,
  registrationComplete?: Promise<void>,
): PropertyDescriptor | undefined {
  if (!descriptor) return undefined;
  // The proxy target owns no properties, so its reported descriptors must be
  // configurable regardless of the adapter's implementation detail.
  if ("value" in descriptor) {
    return {
      configurable: true,
      enumerable: descriptor.enumerable ?? false,
      writable: false,
      value: deferredPortValue(descriptor.value, workflowFor, receiver, registrationComplete),
    };
  }
  return {
    configurable: true,
    enumerable: descriptor.enumerable ?? false,
    get: () => deferredPortValue(
      Reflect.get(receiver, property, receiver), workflowFor, receiver, registrationComplete,
    ),
  };
}

/**
 * Ports are intentionally named by their consumer, so one mutable adapter may
 * also be mounted as a read seam such as `feature`. Preserve the mutable
 * contract recorded when the adapter was first mounted.
 */
function mutablePortKind(
  port: object,
  requested: PortKind,
  mutablePortKinds: WeakMap<object, MutablePortKind>,
): MutablePortKind | undefined {
  if (requested === "tracker" || requested === "code-host") return requested;
  return mutablePortKinds.get(port);
}

function registrarFor(
  plugin: Plugin,
  mounted: Mounted,
  problems: string[],
  ctx: PluginContext,
  workflowFor: WeakMap<PluginContext, Workflow<never, never>>,
  workflowOwners: Set<Plugin>,
  mutablePortKinds: WeakMap<object, MutablePortKind>,
  builds: Builds,
): Registry {
  const claim = <T>(what: string, held: T | undefined, incoming: T): T => {
    if (held !== undefined) {
      problems.push(`${plugin.name}: ${what} is already mounted by another plugin`);
      return held;
    }
    return incoming;
  };

  return {
    queue: (impl) => {
      mounted.queue = claim("the queue", mounted.queue, impl);
      mounted.ports.set("queue", impl as object);
    },
    store: (impl) => {
      mounted.store = claim("the store", mounted.store, impl);
      mounted.ports.set("store", impl as object);
    },
    engine: (impl) => {
      const held = mounted.engine;
      // A deferred engine holds the slot as its marker until it is built, so a
      // second engine is refused at registration either way. Nothing reads
      // the slot before the build pass, and a mount that skips it is refused.
      mounted.engine = claim("the engine", held, impl as Engine);
      if (held !== undefined || !isDeferred(impl)) return;
      builds.defer(impl, plugin.name, "the engine", (engine) => {
        mounted.engine = engine as Engine;
      });
    },
    workflow: (impl) => {
      const snapshot = snapshotWorkflow(impl);
      mounted.workflow = claim("a workflow", mounted.workflow, snapshot);
      if (mounted.workflow === snapshot) {
        workflowFor.set(ctx, snapshot);
        workflowOwners.add(plugin);
      }
    },
    port: (kind, impl) => {
      if (mounted.ports.has(kind)) {
        problems.push(`${plugin.name}: the \`${kind}\` port is already mounted by another plugin`);
        return;
      }
      mounted.ports.set(kind, impl);
      // A deferred port is classified by what it builds, once it has: the
      // marker has none of the methods the classification looks for.
      const classify = (port: object) => {
        const mutableKind = mutablePortKindForPort(kind, port, mutablePortKinds);
        if (mutableKind) mutablePortKinds.set(port, mutableKind);
      };
      if (!isDeferred(impl)) {
        classify(impl);
        return;
      }
      builds.defer(impl, plugin.name, `the \`${kind}\` port`, (port) => {
        mounted.ports.set(kind, port);
        classify(port);
      });
    },
    action: (name, spec, port) => {
      if (isDeferred(port)) {
        problems.push(`${plugin.name}: the action \`${name}\` needs a built port; register a deferred one with \`port\` and bind the action to it`);
        return;
      }
      if (mounted.actions.has(name) && !mounted.ports.has(spec.port)) {
        problems.push(`${plugin.name}: the action \`${name}\` is already claimed`);
        return;
      }
      mounted.actions.set(name, spec);
      if (!mounted.ports.has(spec.port)) {
        mounted.ports.set(spec.port, port);
      }
      // An action can bind a mutable method to an existing consumer-named
      // alias. Classify that already-mounted adapter as well as a new one.
      const adapter = mounted.ports.get(spec.port);
      const classify = (port: object) => {
        const kind = mutablePortKindForAction(spec, port, mutablePortKinds);
        if (kind) mutablePortKinds.set(port, kind);
      };
      if (adapter && builds.holds(adapter)) builds.afterBuilt(adapter, classify);
      else if (adapter) classify(adapter);
    },
    contribute: (collection, name, impl) => {
      const existing = mounted.contributions.get(collection) ?? new Map<string, object>();
      if (existing.has(name)) {
        problems.push(`${plugin.name}: \`${name}\` is already in the \`${collection}\` collection`);
        return;
      }
      existing.set(name, impl);
      mounted.contributions.set(collection, existing);
      if (isDeferred(impl)) {
        builds.defer(impl, plugin.name, `\`${name}\` in \`${collection}\``, (value) => existing.set(name, value));
      }
    },

  };
}

/**
 * An action may introduce its port, including an alias such as `feature`.
 * Classify a declared mutable method at that point so the engine's workflow
 * view cannot receive the newly mounted adapter whole.
 */
function mutablePortKindForAction(
  spec: ActionSpec,
  port?: object,
  mutablePortKinds?: WeakMap<object, MutablePortKind>,
): MutablePortKind | undefined {
  const known = port && mutablePortKinds?.get(port);
  // An alias mounted before its action is conservatively unknown. Its declared
  // binding may subsequently identify a concrete tracker/code-host contract;
  // retain an established concrete identity, but refine that provisional one.
  if (known && known !== "unknown") return known;
  return inferredMutablePortKind(spec, port) ?? known;
}

/** Infer a core contract only after preserving a mounted adapter's identity. */
function inferredMutablePortKind(spec: ActionSpec, port?: object): MutablePortKind | undefined {
  if (spec.port === "tracker" || TRACKER_WRITE_FOR_METHOD[spec.method]) return "tracker";
  if (spec.port === "code-host" || CODE_HOST_WRITE_FOR_METHOD[spec.method]) return "code-host";
  if (port && isCodeHostPort(port)) return "code-host";
  // A consumer-named tracker alias can bind a new mutator before the core
  // table learns its method name. The binding makes this a mutable boundary;
  // fail closed instead of returning that adapter whole to a workflow.
  if (isTrackerActionAlias(port)) return "tracker";
  if (port && isTrackerPort(port)) return "tracker";
  if (port && acceptsActionMethod(port, spec.method)) return "unknown";
  return undefined;
}

function mutablePortKindForPort(
  kind: PortKind,
  port: object,
  mutablePortKinds: WeakMap<object, MutablePortKind>,
): MutablePortKind | undefined {
  return mutablePortKind(port, kind, mutablePortKinds)
    ?? (isCodeHostPort(port) ? "code-host" : undefined)
    ?? (isTrackerPort(port) ? "tracker" : undefined)
    ?? (hasUnknownMutableMethod(port) ? "unknown" : undefined);
}

type MutablePortKind = "tracker" | "code-host" | "unknown";

/** Preserve the boot-validated writes if a plugin mutates its declaration later. */
function snapshotWorkflow(workflow: Workflow<never, never>): Workflow<never, never> {
  return Object.freeze({
    ...workflow,
    trackerWrites: Object.freeze([...(workflow.trackerWrites ?? [])]),
    codeHostWrites: Object.freeze([...(workflow.codeHostWrites ?? [])]),
  });
}

/** An opt-in dispatch method means this otherwise unknown port is a boundary. */
function acceptsActionMethod(port: object, method: string): boolean {
  const value = Reflect.get(port, method);
  return typeof value === "function" && (value as Record<symbol, unknown>)[Symbol.for("amykit.acceptsAction")] === true;
}

function isCodeHostPort(port: object): boolean {
  return [...CODE_HOST_READ_METHODS, ...Object.keys(CODE_HOST_WRITE_FOR_METHOD)]
    .some((method) => typeof Reflect.get(port, method) === "function");
}

function isTrackerPort(port: object): boolean {
  return Object.keys(TRACKER_WRITE_FOR_METHOD)
    .some((method) => typeof Reflect.get(port, method) === "function");
}

/** Detect an explicitly mutating alias method outside the two core contracts. */
function hasUnknownMutableMethod(port: object): boolean {
  for (let current: object | null = port; current && current !== Object.prototype; current = Object.getPrototypeOf(current)) {
    const descriptor = Reflect.getOwnPropertyDescriptor(current, "mutate");
    if (typeof descriptor?.value === "function" || descriptor?.get !== undefined || descriptor?.set !== undefined) return true;
  }
  return false;
}

/** An action binding turns an otherwise ambiguous `get` alias into a mutable boundary. */
function isTrackerActionAlias(port: object | undefined): boolean {
  return Boolean(port && typeof Reflect.get(port, "get") === "function");
}

/**
 * The runtime the mounted workflow contributed, looked up by the workflow's
 * own name the way an engine looks it up.
 */
export function mountedRuntime(
  mounted: Mounted,
  workflow: Workflow<never, never>,
): WorkflowRuntime | undefined {
  return mounted.contributions.get(WORKFLOW_RUNTIME)?.get(workflow.name) as
    | WorkflowRuntime
    | undefined;
}

/**
 * The actions a mounted workflow declares: its runtime's keys, or none when
 * the runtime is missing or cannot be read.
 */
export function mountedActions(mounted: Mounted, workflow: Workflow<never, never>): string[] {
  try {
    const runtime = mountedRuntime(mounted, workflow);
    return runtime?.actions ? declaredActions(runtime) : [];
  } catch {
    return [];
  }
}

/**
 * What a mounted host cannot give the workflow it was asked to drive.
 *
 * This is where the price of an open action name gets paid: at boot, naming
 * the action, rather than halfway through a ticket.
 */
export function unmetNeeds(mounted: Mounted, workflow: Workflow<never, never>): string[] {
  const unmet: string[] = [];
  const actions = declaredOn(mounted, workflow, unmet);

  if (actions !== null) {
    const port = (kind: PortKind): object | undefined => mounted.ports.get(kind);
    for (const [action, implementation] of Object.entries(actions)) {
      const problem = unrunnable(action, implementation, port) ?? catalogued(mounted, action, implementation);
      if (problem) unmet.push(problem);
    }
    unmet.push(...unclaimedWrites(mounted, workflow, actions));
    unmet.push(...misboundWrites(mounted, actions));
    unmet.push(...unclassifiableActionBindings(mounted, actions));
  }


  return unmet;
}

/**
 * The declaration rule: a workflow's claimed tracker writes are the only
 * surface its runtime may reach. The claim is written by hand, never derived,
 * so a declared tracker-mutating action it does not claim is refused at boot,
 * naming the action and the capability, before any tracker call log records
 * a write.
 */
function unclaimedWrites(mounted: Mounted, workflow: Workflow<never, never>, actions: Readonly<Record<string, unknown>>): string[] {
  return [
    ...unclaimed(
      "tracker",
      workflow.trackerWrites ?? [],
      TRACKER_WRITE_CAPABILITIES,
      actions,
      (action, implementation) => writeFor(mounted, "tracker", action, implementation, trackerWritesFor, TRACKER_WRITE_FOR_METHOD),
      "trackerWrites",
    ),
    ...unclaimed(
      "code-host",
      workflow.codeHostWrites ?? [],
      CODE_HOST_WRITE_CAPABILITIES,
      actions,
      (action, implementation) => writeFor(mounted, "code-host", action, implementation, (name) => {
        const capability = codeHostWriteFor(name);
        return capability ? [capability] : [];
      }, CODE_HOST_WRITE_FOR_METHOD),
      "codeHostWrites",
    ),
  ];
}

function unclaimed(
  port: string,
  declarations: readonly string[],
  supported: readonly string[],
  actions: Readonly<Record<string, unknown>>,
  capabilitiesFor: (action: string, implementation: unknown) => readonly string[],
  field: string,
): string[] {
  const unmet: string[] = [];
  const claimed = new Set(declarations);
  for (const capability of claimed) {
    if (supported.includes(capability)) continue;
    unmet.push(
      `the workflow claims the ${port} write \`${capability}\`, which is not one a mounted ${port} could honour — ${describeCapabilities(supported)}`,
    );
  }
  for (const [action, implementation] of Object.entries(actions)) {
    for (const capability of capabilitiesFor(action, implementation)) {
      if (claimed.has(capability)) continue;
      unmet.push(
        `action \`${action}\` writes the ${port} (\`${capability}\`), ` +
          `but the workflow does not claim that capability — add \`${capability}\` to its \`${field}\``,
      );
    }
  }
  return unmet;
}

/** A bound action names its write by its actual port method; handlers use the core catalogue. */
function writeFor(
  mounted: Mounted,
  port: PortKind,
  action: string,
  implementation: unknown,
  coreWritesFor: (action: string) => readonly string[],
  writeForMethod: Readonly<Record<string, string>>,
): readonly string[] {
  const bound = declaredBinding(implementation);
  if (bound) {
    // A port binding is executable as written, even when its action name is a
    // core name. The method table, not that name or a consumer-facing alias,
    // identifies the declaration it needs.
    if (bindingPortKind(mounted, bound) !== port) return [];
    const capability = writeForMethod[bound.method];
    return capability ? [capability] : [];
  }
  return CORE_ACTIONS[action]?.port === port ? coreWritesFor(action) : [];
}

/** Resolve a binding by its mounted target, not by a method another port owns. */
function bindingPortKind(mounted: Mounted, binding: ActionSpec): MutablePortKind | undefined {
  if (binding.port === "tracker" || binding.port === "code-host") return binding.port;
  const adapter = mounted.ports.get(binding.port);
  if (!adapter) return undefined;
  for (const kind of ["tracker", "code-host"] as const) {
    if (mounted.ports.get(kind) === adapter) return kind;
  }
  if (TRACKER_WRITE_FOR_METHOD[binding.method]) return "tracker";
  if (CODE_HOST_WRITE_FOR_METHOD[binding.method]) return "code-host";
  return acceptsActionMethod(adapter, binding.method) ? "unknown" : undefined;
}

/** A known writer from one mutable contract may not be wired to the other. */
function misboundWrites(mounted: Mounted, actions: Readonly<Record<string, unknown>>): string[] {
  const problems: string[] = [];
  for (const [action, declared] of Object.entries(actions)) {
    const implementation = declaredBinding(declared);
    if (!implementation || !mounted.actions.has(action)) continue;
    const kind = bindingPortKind(mounted, implementation);
    const opposite = kind === "tracker"
      ? CODE_HOST_WRITE_FOR_METHOD[implementation.method]
      : kind === "code-host"
        ? TRACKER_WRITE_FOR_METHOD[implementation.method]
        : undefined;
    if (opposite) {
      problems.push(
        `action \`${action}\` binds the ${kind} port to \`${implementation.method}\`, ` +
          `a write only the ${kind === "tracker" ? "code-host" : "tracker"} contract defines`,
      );
    }
  }
  return problems;
}

/** Reject dispatched methods that cannot be represented by their core port view. */
function unclassifiableActionBindings(mounted: Mounted, actions: Readonly<Record<string, unknown>>): string[] {
  const problems: string[] = [];
  for (const [action, declared] of Object.entries(actions)) {
    const implementation = declaredBinding(declared);
    if (!implementation) continue;
    if (catalogued(mounted, action, implementation) !== null) continue;
    const kind = bindingPortKind(mounted, implementation);
    // A method belonging to the opposite contract receives the more precise
    // misboundWrites diagnostic below. Every other unknown method would be
    // hidden by the workflow's closed concrete-port view after boot.
    if (kind !== "unknown" && (kind === undefined || contractMethod(kind, implementation.method) || foreignWrite(kind, implementation.method))) continue;
    problems.push(
      `action \`${action}\` binds unrecognised mutable port \`${implementation.port}.${implementation.method}\`; ` +
      "give it a tracker or code-host contract method before a workflow may dispatch it",
    );
  }
  return problems;
}

function contractMethod(kind: Exclude<MutablePortKind, "unknown">, method: string): boolean {
  return kind === "tracker"
    ? TRACKER_READ_METHODS.has(method) || Boolean(TRACKER_WRITE_FOR_METHOD[method])
    : CODE_HOST_READ_METHODS.has(method) || Boolean(CODE_HOST_WRITE_FOR_METHOD[method]);
}

function foreignWrite(kind: Exclude<MutablePortKind, "unknown">, method: string): boolean {
  return kind === "tracker" ? Boolean(CODE_HOST_WRITE_FOR_METHOD[method]) : Boolean(TRACKER_WRITE_FOR_METHOD[method]);
}

function describeCapabilities(capabilities: readonly string[]): string {
  const names = capabilities.map((capability) => `\`${capability}\``);
  return names.length < 2 ? names.join("") : `${names.slice(0, -1).join(", ")} or ${names.at(-1)}`;
}

/**
 * The runtime's action map, or `null` with the reason pushed when there is
 * none to read.
 *
 * A package still written against the old contract is named with its fix,
 * because a boot that refused it any other way would read as a missing port.
 */
function declaredOn(
  mounted: Mounted,
  workflow: Workflow<never, never>,
  unmet: string[],
): Readonly<Record<string, unknown>> | null {
  if (Object.hasOwn(workflow, "usesActions")) {
    unmet.push(
      `the workflow \`${workflow.name}\` still declares \`usesActions\`, which is now the keys of its runtime's \`actions\` — delete it and key each action there, beside what runs it`,
    );
  }

  const runtime = mountedRuntime(mounted, workflow);
  if (!runtime) {
    unmet.push(
      `the workflow \`${workflow.name}\` contributed no runtime to \`${WORKFLOW_RUNTIME}\`, so nothing can run its actions`,
    );
    return null;
  }

  let actions: unknown;
  try {
    actions = runtime.actions;
  } catch (error) {
    unmet.push(
      `the workflow \`${workflow.name}\`: its actions could not be read — ${error instanceof Error ? error.message : String(error)}`,
    );
    return null;
  }

  if (actions === null || typeof actions !== "object") {
    const legacy = typeof (runtime as { handlers?: unknown }).handlers === "function";
    unmet.push(
      legacy
        ? `the workflow \`${workflow.name}\` still has \`handlers()\`, which is now \`actions\`: one map whose keys are the actions it emits and whose values run them`
        : `the workflow \`${workflow.name}\` declares no \`actions\` on its runtime`,
    );
    return null;
  }
  return unmet.length > 0 ? null : (actions as Readonly<Record<string, unknown>>);
}

/**
 * Whether the catalogue agrees with how an action is implemented.
 *
 * A handler runs an action the catalogue names, because the catalogue is
 * what tells the budget which actions spend an agent and the tracker check
 * which ones write. A port and a method names its own port, so it may run an
 * action nobody catalogued — but not one the catalogue sends elsewhere.
 */
function catalogued(mounted: Mounted, action: string, implementation: unknown): string | null {
  const spec = mounted.actions.get(action);
  const bound = declaredBinding(implementation);
  if (bound) {
    if (!spec || spec.port === bound.port) return null;
    return `action \`${action}\` is wired to the \`${bound.port}\` port, but the catalogue runs it on \`${spec.port}\``;
  }
  if (!spec) return `action \`${action}\`: nothing defines it`;
  if (!mounted.ports.has(spec.port)) {
    return `action \`${action}\`: needs the \`${spec.port}\` port, which nothing mounted`;
  }
  return null;
}

import { Conversation } from "./ports/Conversation.js";
import { Notifier } from "./ports/Notifier.js";

/** Where something said to the operator went. */
export type OperatorChannel = "thread" | "notifier";

export interface OperatorChannels {
  /** The work's own thread, when an install mounted one. */
  conversation?: Conversation;
  notifier: Notifier;
}

/**
 * Says one thing to the operator: in the work's own thread when there is
 * one, and through the notifier otherwise.
 *
 * Every workflow that talks to its operator made this choice for itself, and
 * the ones that made it differently put a question in one place and listened
 * for the answer in another. The thread is preferred because a reply there is
 * something a workflow can read back; a notification is only ever heard.
 */
export async function sayToOperator(
  channels: OperatorChannels,
  message: { text: string; workId: string; title: string; state: string },
): Promise<OperatorChannel> {
  if (channels.conversation) {
    const thread = await channels.conversation.open(message.workId, message.title);
    await channels.conversation.post(thread, { text: message.text });
    return "thread";
  }
  await channels.notifier.announce({ text: message.text, workId: message.workId, state: message.state });
  return "notifier";
}

import { ActionSpec, PortKind } from "./actions.js";
import { Checkouts } from "./checkouts.js";
import { PluginCheck, PluginCommand, PluginFile, PluginSetup } from "./commands.js";
import { CommandRunner } from "./ports/CommandRunner.js";
import { EventLog } from "./ports/EventLog.js";
import { ConfigOf, ConfigSchema } from "./config-schema.js";
import { Deferred } from "./deferred.js";
import { Diagram } from "./diagram.js";
import { Plan, WorkRecord } from "./work.js";
import { Queue } from "./ports/Queue.js";
import { Store } from "./ports/Store.js";

/**
 * The project phases a workflow declares, every value the reason the phase
 * it names is absent.
 *
 * A phase present on disk needs no word here: the folders are the part of
 * the declaration amy derives. What a phase that is gone lacks is said in
 * the declaration — `phases: { prove: "a person reviews this work" }` — so
 * a project without it still mounts, saying at every view what it loses
 * (`amy status`, `amy doctor`). A phase neither present nor declared is
 * refused at the mount, naming it.
 */
export interface ProjectPhases {
  readonly brief?: string;
  readonly workflow?: string;
  readonly prove?: string;
}

/**
 * A workflow: the order in which actions happen.
 *
 * It does not define actions, it composes the ones the core ships. `plan` is
 * pure, which is what lets a whole lifecycle be driven in a test with no I/O.
 *
 * Generic over the observation and the policy, so a workflow keeps full type
 * safety over its own domain while the core stays ignorant of it.
 */
export interface Workflow<Observation = unknown, Policy = unknown> {
  readonly name: string;
  readonly states: readonly string[];
  readonly waitingStates: readonly string[];
  readonly initialState: string;
  readonly terminalStates: readonly string[];
  /**
   * The diagram the states were read from, when the workflow has one.
   *
   * What every view draws, and what a move is checked against: an advance to
   * a state it does not connect is still applied, and written to the event
   * log, because refusing it would leave somebody's work stuck on a drawing.
   */
  readonly diagram?: Diagram;
  /**
   * The workflow each call state calls, by state, for a view that draws a
   * call as what it calls. Each is itself composed when it calls others.
   */
  readonly calls?: Readonly<Record<string, Workflow>>;
  /**
   * The actions are not declared here. They are the keys of the runtime's
   * `actions`, where each one is declared and implemented at once — two
   * lists of one fact were how an action came to pass the mount with nothing
   * behind it.
   */

  /**
   * The tracker writes this workflow claims, by capability name.
   *
   * Written by hand and checked against the actions its runtime declares: a
   * workflow that declares no tracker-mutating action claims none and is
   * free to mount beside any tracker; one that declares a mutator without
   * claiming its capability is refused at boot, naming the action and the
   * capability, before any tracker call log records a write.
   */
  readonly trackerWrites?: readonly string[];
  /**
   * The forge writes this workflow claims, by capability name.
   *
   * Like tracker writes, this is a hand-written permission boundary: the host
   * gives this workflow a port whose unclaimed mutations refuse at the call.
   */
  readonly codeHostWrites?: readonly string[];
  /**
   * The project phases the workflow declares, every value the reason the
   * phase it names is absent, when it declares any: what `amy status` and
   * `amy doctor` read to say what a project without that phase loses.
   */
  readonly phases?: ProjectPhases;
  plan(record: WorkRecord, observation: Observation, policy: Policy): Plan;
  /**
   * Every move a record waiting in a fork can make at once, one per lane
   * that is not waiting, for an engine that moves lanes side by side.
   * Undefined when there are not two to make; `plan` then says the one.
   */
  everyLane?(record: WorkRecord, observation: Observation, policy: Policy): readonly Plan[] | undefined;
  /**
   * What the workflow says before any state's own decision — a ticket that
   * left the working status stops where it is — asked even while a record
   * waits in a fork, where the lanes decide and its own decisions do not.
   */
  interrupt?(record: WorkRecord, observation: Observation, policy: Policy): Plan | undefined;
}

/** Advances work. Serial by default, but replaceable like everything else. */
export interface Engine {
  /** Finds work that is not on the queue yet, and returns what it added. */
  discover(): Promise<string[]>;
  /** Advances one item by one move. */
  tick(): Promise<unknown>;
}



export interface HostPaths {
  /** Where the host keeps its own state. */
  readonly state: string;
  /**
   * The directory one profile owns, when this host has profiles.
   *
   * Records and the queue already live under it; a workflow that keeps
   * something beside them — a roster, a settings file a command writes —
   * needs the same directory a command is handed, or `amy roster confirm`
   * would write beside `amy tick`'s reading of it.
   */
  readonly profile?: string;
  /**
   * A host-selected root for artifacts several independently driven workflows
   * share.  The core does not interpret the artifacts or their producers.
   */
  readonly artifacts?: string;
}

/**
 * What the host lends a plugin at mount.
 *
 * A plugin gets its own settings and the few services every plugin would
 * otherwise reimplement, and it gets a *live* view of what other plugins
 * registered. Live matters: a plugin that composes others cannot see
 * contributions made after it, so it reads them when it is used rather than
 * when it is mounted.
 */
export interface PluginContext<Config extends Record<string, unknown> = Record<string, unknown>> {
  readonly config: Config;
  readonly runner: CommandRunner;
  readonly now: () => Date;
  readonly log?: EventLog;
  readonly paths: HostPaths;
  /** This mount may inspect existing state but must not create it. */
  readonly readOnly: boolean;
  /** Everything contributed to a named collection, read when asked. */
  contributions(collection: string): ReadonlyMap<string, object>;
  /** A mounted port, read when asked. */
  port(kind: PortKind): object | undefined;
  /**
   * The checkouts this plugin works in: a `Git` and the layout behind it,
   * answered through the mounted workspace, with this plugin's own
   * `defaultBranch` and `baseBranch` for the branches.
   *
   * The `worktree` port is read whenever a path is asked for, not when this
   * is called, so a worktree plugin listed after this one is still the one
   * used. The workspace itself is read when the checkouts are: a plugin
   * asking for them before the workspace's provider has registered is
   * refused by name, and the machine's own plugin order puts the workplace
   * before everything that captures one. Nothing outside the core
   * constructs a `Git`; this is how a plugin gets one.
   *
   * `who` is what the refusal names — what asked for the checkouts when the
   * machine has no workspace to answer with. A plugin's own context needs
   * no argument; a call site passes the workflow it calls, so the refusal
   * can say whose work stopped.
   */
  checkouts(who?: string): Checkouts;
  /**
   * A mounted port as the selected workflow may use it.
   *
   * Engines use this rather than their plugin context's ordinary `port`: an
   * engine is infrastructure, but it dispatches the workflow's actions.
   */
  workflowPort?(kind: PortKind): object | undefined;
  /**
   * The mounted workflow, read when asked.
   *
   * Live for the same reason the two above are: an engine is mounted by a
   * plugin that may be listed before the workflow's, and mounting order
   * should not be something an operator has to get right.
   */
  workflow(): Workflow<never, never> | undefined;
}

/**
 * What `port`, `engine` and `contribute` accept: the implementation itself,
 * or a `deferred` one the host builds once every plugin has registered.
 */
export type Implementation<T extends object> = T | Deferred<T>;

export interface Registry {
  queue(impl: Queue): void;
  store(impl: Store): void;
  engine(impl: Implementation<Engine>): void;
  workflow(impl: Workflow<never, never>): void;
  /** Mounts a port. Mounting the same kind twice fails loudly. */
  port(kind: PortKind, impl: Implementation<object>): void;
  /**
   * Registers an action the core does not ship, together with the port that
   * runs it. The pair is inseparable on purpose: an action nobody can execute
   * is a promise the machine cannot keep.
   */
  action(name: string, spec: ActionSpec, port: object): void;

  /**
   * Adds to a named collection that some other plugin consumes.
   *
   * The core does not know what a collection means, only that several
   * plugins may add to one and something else will read it. It is how the
   * notification channels reach the fan-out without the core learning the
   * word "channel".
   */
  contribute(collection: string, name: string, impl: Implementation<object>): void;
}

export interface Plugin {
  readonly name: string;

  /**
   * What this plugin's slice of the configuration looks like.
   *
   * Declared here so the host can refuse a typo at boot without knowing what
   * any of the settings mean.
   */
  readonly configSchema?: ConfigSchema;
  /**
   * The environment variables this plugin reads, in its own words.
   *
   * The doctor asks each mounted plugin's need one variable at a time, and a
   * machine that mounted none of them is asked none of them: a checklist
   * every install carries used to be one workflow's credential list, and the
   * install without that workflow failed `amy doctor` on it for no machine's
   * sake.
   */
  readonly environment?: readonly string[];
  /**
   * The commands this plugin brings to the command line.
   *
   * Read after the module is imported and before anything is mounted, so a
   * command works on the machine that will not boot. The host owns the entry
   * point and the parser; what each command means is this plugin's.
   */
  readonly commands?: readonly PluginCommand[];
  /** The checks `amy doctor` runs after its own, under this plugin's name. */
  readonly checks?: readonly PluginCheck[];
  /** The files `amy init` and `amy add` write into the profile's state, once. */
  readonly files?: readonly PluginFile[];
  /** What `amy init` and `amy add` prepare outside amy's state, after the files. */
  readonly setup?: readonly PluginSetup[];
  register(r: Registry, ctx: PluginContext): void | Promise<void>;
  /**
   * Checked once every plugin has registered and every deferred
   * implementation is built, and only for a plugin whose settings cannot be
   * judged before then. Building something early is not what it is for: a
   * `deferred` implementation is already built, and refused, at boot.
   *
   * A plugin that composes others is the case this exists for: it cannot tell
   * whether its configuration makes sense until the plugins it composes have
   * contributed themselves. Throwing here is a refusal at boot, named, which
   * is the same promise `register` makes.
   */
  ready?(ctx: PluginContext): void | Promise<void>;
}

/**
 * Declares a plugin with the exact configuration shape its schema validates.
 *
 * `Plugin` remains available for third-party and legacy implementations that
 * intentionally receive an untyped configuration map.
 */
export function definePlugin<const S extends ConfigSchema>(plugin: {
  readonly name: string;
  readonly configSchema: S;
  readonly environment?: readonly string[];
  readonly commands?: readonly PluginCommand<ConfigOf<S>>[];
  readonly checks?: readonly PluginCheck<ConfigOf<S>>[];
  readonly files?: readonly PluginFile<ConfigOf<S>>[];
  readonly setup?: readonly PluginSetup<ConfigOf<S>>[];
  register(r: Registry, ctx: PluginContext<ConfigOf<S>>): void | Promise<void>;
  ready?(ctx: PluginContext<ConfigOf<S>>): void | Promise<void>;
}): Plugin {
  return plugin as unknown as Plugin;
}

import { AskContext, HarnessReply } from "./Harness.js";

/** A run a workflow can continue from, or one that adds no evidence. */
export type Progress =
  | { kind: "advanced"; key: string }
  | { kind: "unchanged"; key: string; detail: string }
  | { kind: "handoff"; detail: string };

/** What one attempt to write the change produced, gate included. */
export interface AttemptOutcome {
  ok: boolean;
  /** Whatever the agent or the gate said, verbatim, for the next prompt. */
  output: string;
  at: string;
  /** Absent keeps older agents and workflows behaving exactly as they did. */
  progress?: Progress;
}

/**
 * The coding agent, and the only probabilistic thing in the system.
 *
 * A prompt, a directory and a context in; an answer and an account of what
 * it cost out. Without that account there is nothing to escalate on and
 * nothing to budget against, so it is part of the contract.
 *
 * It is one method on purpose. A step — triage, implement, a review — is a
 * prompt and what the workflow does with the answer, and it is built on this
 * in the workflow or with a helper from `@amykit/agent-kit`. A method per
 * step put one workflow's lifecycle into every workflow's contract, and an
 * agent that committed and pushed took a decision that is the workflow's.
 * See docs/design/an-agent-only-answers.md; `L0.THE_AGENT_PORT_ONLY_ASKS`
 * keeps it this way.
 */
export interface Agent {
  ask(prompt: string, cwd: string, context?: AskContext): Promise<HarnessReply>;
}

import { CommandResult, CommandRunner } from "./CommandRunner.js";
import { RepoLayout, baseBranchFor, checkoutFor } from "../git.js";

export interface SearchMatch {
  /** A repository path that `read` accepts. */
  path: string;
  line: number;
  text: string;
}

export interface SearchResult {
  matches: SearchMatch[];
  /** True when `limit` cut the list. A cut list must not read as "nothing else". */
  truncated: boolean;
}

export interface HistoryEntry {
  commit: string;
  at: string;
  subject: string;
  /** Whether the commit raised or lowered the number of occurrences. */
  change: "added" | "removed";
}

export interface HistoryResult {
  /** Newest first. */
  entries: HistoryEntry[];
  /**
   * True when `limit` cut the list. Without it, the oldest entry of a cut
   * list would read as the commit that introduced the text, which is the one
   * claim `history` exists to make.
   */
  truncated: boolean;
}

export interface SearchOptions {
  paths?: string[];
  regex?: boolean;
  limit?: number;
}

export interface HistoryOptions {
  paths?: string[];
  limit?: number;
}

/**
 * A read-only view of one repository at one commit of its base branch.
 *
 * Every method answers at `revision`, so two answers from one snapshot never
 * come from two different commits, and a claim made from it can name the
 * commit it was read at.
 */
export interface BaseSourceSnapshot {
  readonly repo: string;
  readonly baseBranch: string;
  /** The full commit id every method below reads at. */
  readonly revision: string;
  /** When that commit was made, as ISO 8601. */
  readonly committedAt: string;
  /** Reads a tracked file as it exists at `revision`. */
  read(path: string): Promise<string | null>;
  /** Where a text appears at `revision`. Literal by default. */
  search(text: string, options?: SearchOptions): Promise<SearchResult>;
  /** Commits up to `revision` that added or removed occurrences of a text. */
  history(text: string, options?: HistoryOptions): Promise<HistoryResult>;
}

/**
 * The narrow source capability grooming receives.
 *
 * It intentionally exposes neither a checkout path nor Git/worktree operations:
 * a groomer can inspect source at the configured base and cannot repoint the
 * standing checkout, create a branch, commit, or acquire a worktree.
 */
export interface BaseSource {
  snapshot(repo: string): Promise<BaseSourceSnapshot>;
}

const DEFAULT_SEARCH_LIMIT = 200;
const DEFAULT_HISTORY_LIMIT = 50;

/**
 * Fetches `origin/<base>`, pins the commit it resolves to, and reads Git
 * objects at that commit. No checkout command is issued, so a standing branch
 * remains exactly where its owner left it.
 */
export class GitBaseSource implements BaseSource {
  constructor(
    private readonly runner: CommandRunner,
    private readonly layout: RepoLayout,
  ) {}

  async snapshot(repo: string): Promise<BaseSourceSnapshot> {
    const cwd = checkoutFor(this.layout, repo);
    const baseBranch = baseBranchFor(this.layout, repo);
    // Whole output: a file's content, and a matched line, keep the whitespace they have.
    const git = (args: string[]): Promise<CommandResult> => this.runner.run("git", args, { cwd, trim: false });
    const why = (result: CommandResult): string => result.stderr || result.stdout;

    // The destination is named because a narrowed `remote.origin.fetch` would
    // otherwise fetch the branch and leave origin/<base> where it was.
    const remoteRef = `refs/remotes/origin/${baseBranch}`;
    const fetched = await git(["fetch", "--no-tags", "origin", `+refs/heads/${baseBranch}:${remoteRef}`]);
    if (!fetched.ok) throw new Error(`the grooming source could not fetch ${baseBranch} for ${repo}: ${why(fetched)}`);

    const resolved = await git(["log", "-1", "--no-color", "--format=%H%x00%cI", remoteRef]);
    const [revision, committedAt] = resolved.stdout.trim().split("\0");
    if (!resolved.ok || !revision || !committedAt) throw new Error(`the grooming source cannot read ${repo} at origin/${baseBranch}: ${why(resolved)}`);

    let isShallow: Promise<boolean> | undefined;
    const shallow = (): Promise<boolean> => (isShallow ??= git(["rev-parse", "--is-shallow-repository"]).then((result) => result.stdout.trim() === "true"));

    return {
      repo,
      baseBranch,
      revision,
      committedAt,
      read: async (file) => {
        const result = await git(["show", `${revision}:${file}`]);
        if (result.ok) return result.stdout;
        // A missing file is an ordinary source fact; another failure is not.
        if (result.stderr.includes("does not exist") || result.stderr.includes("exists on disk")) return null;
        throw new Error(`the grooming source could not read ${file} in ${repo}: ${why(result)}`);
      },
      search: async (text, options = {}) => {
        textOf(text);
        const limit = limitOf(options.limit, DEFAULT_SEARCH_LIMIT);
        // The runner buffers everything git prints, so cap each file at the
        // one extra match `truncated` needs rather than read every match there is.
        const args = ["grep", "--no-color", "--no-column", "-n", "-I", "-z", `--max-count=${limit + 1}`, options.regex ? "-E" : "-F", "-e", text, revision, "--", ...(options.paths ?? [])];
        const result = await git(args);
        if (!result.ok && result.exitCode === 1 && !result.stderr) return { matches: [], truncated: false };
        if (!result.ok) throw new Error(`the grooming source could not search ${repo} for ${JSON.stringify(text)}: ${why(result)}`);
        const matches = parseGrep(result.stdout, `${revision}:`);
        return { matches: matches.slice(0, limit), truncated: matches.length > limit };
      },
      history: async (text, options = {}) => {
        textOf(text);
        const limit = limitOf(options.limit, DEFAULT_HISTORY_LIMIT);
        const paths = options.paths ?? [];
        // A shallow clone ends its history at the boundary, and the oldest entry would read as the introduction.
        if (await shallow()) throw new Error(`the grooming source cannot read the history of ${repo}: its checkout is a shallow clone, so the commits before its boundary are missing. Run \`git fetch --unshallow\` there`);
        // One more than asked for: the extra entry is what says the list was cut. A merge is
        // searched, and counted, by what its conflict resolution changed (remerge), so a clean
        // merge does not repeat its branch's commit and a dropped side of a conflict reads as removed.
        // A commit whose matching changes are all binary shows no text line to count and is left
        // out, as search skips binaries; git's -n counts it anyway, so ask again for more until
        // enough text rows are in or git ran out.
        let textual: HistoryRow[];
        for (let asked = limit + 1; ; asked *= 2) {
          const result = await git(["log", "--no-color", "--no-ext-diff", "--no-textconv", "-p", "-U0", "--diff-merges=remerge", `-S${text}`, "-n", String(asked), "--format=%x00%H%x00%cI%x00%s", revision, "--", ...paths]);
          if (!result.ok) throw new Error(`the grooming source could not read the history of ${JSON.stringify(text)} in ${repo}: ${why(result)}`);
          const rows = parseHistory(result.stdout, text);
          textual = rows.filter((row) => row.added + row.removed > 0);
          if (textual.length > limit || rows.length < asked) break;
        }
        const entries = textual.slice(0, limit).map(({ added, removed, ...entry }): HistoryEntry => ({
          ...entry,
          // A move between files changes no total; the text still exists after it, so it did not go away.
          change: added >= removed ? "added" : "removed",
        }));
        return { entries, truncated: textual.length > limit };
      },
    };
  }
}

// An empty text matches every line, and a bare `-S` makes git read the next flag as its argument.
// A newline splits a grep pattern into several, and a line-by-line count can never see it.
function textOf(text: string): void {
  if (text === "") throw new Error("the grooming source needs a text to look for, and was given an empty one");
  if (text.includes("\n")) throw new Error("the grooming source looks for text within one line, and was given one with a newline in it");
}

function limitOf(limit: number | undefined, fallback: number): number {
  if (limit === undefined) return fallback;
  if (!Number.isSafeInteger(limit) || limit < 0) throw new Error(`the grooming source needs a limit that is a whole number of zero or more, not ${limit}`);
  return limit;
}

/**
 * Reads `git log -p -U0 --format=%x00…` output: one record per commit, then the
 * diff `-S` selected it by. Lines that did not change cancel out between the
 * two sides, so the occurrences on `+` and `-` lines are the commit's change.
 */
interface HistoryRow { commit: string; at: string; subject: string; added: number; removed: number }

function parseHistory(output: string, text: string): HistoryRow[] {
  const rows: HistoryRow[] = [];
  let header = false;
  for (const line of output.split("\n")) {
    const row = rows.at(-1);
    if (line.startsWith("\0")) {
      const [, commit = "", at = "", ...subject] = line.split("\0");
      rows.push({ commit, at, subject: subject.join("\0"), added: 0, removed: 0 });
    } else if (line.startsWith("diff ")) {
      header = true;
    } else if (line.startsWith("@@")) {
      header = false;
    } else if (row && !header && line.startsWith("+")) {
      row.added += count(line.slice(1), text);
    } else if (row && !header && line.startsWith("-")) {
      row.removed += count(line.slice(1), text);
    }
  }
  return rows;
}

/** Non-overlapping occurrences, the way `-S` counts them. */
function count(line: string, text: string): number {
  let found = 0;
  for (let at = line.indexOf(text); at >= 0; at = line.indexOf(text, at + text.length)) found++;
  return found;
}

/**
 * Reads `git grep -n -z` output, `<prefix><path>\0<line>\0<text>\n` per match.
 * The path is read up to its NUL rather than split on newlines first, because
 * a path may contain a newline and the matched text never does.
 */
function parseGrep(output: string, prefix: string): SearchMatch[] {
  const matches: SearchMatch[] = [];
  let at = 0;
  while (at < output.length) {
    const pathEnd = output.indexOf("\0", at);
    const lineEnd = pathEnd < 0 ? -1 : output.indexOf("\0", pathEnd + 1);
    if (lineEnd < 0) break;
    const textEnd = output.indexOf("\n", lineEnd + 1);
    const where = output.slice(at, pathEnd);
    matches.push({
      path: where.startsWith(prefix) ? where.slice(prefix.length) : where,
      line: Number(output.slice(pathEnd + 1, lineEnd)),
      text: output.slice(lineEnd + 1, textEnd < 0 ? output.length : textEnd),
    });
    at = textEnd < 0 ? output.length : textEnd + 1;
  }
  return matches;
}

/**
 * One brief: the current statement of the feature a group of work items
 * implements, owned by the workflow that grooms and everything a later
 * ticket step reads.
 *
 * A brief is opaque content with explicit work membership. It does not model
 * acceptance criteria, sources or answers — a workflow decides its own
 * sections and what counts as a source, and the core never parses either.
 * What the core guarantees is narrower and load-bearing: a stable id, a
 * revision that changes when the text does, the work ids it explains, and a
 * read that returns the current version rather than a copy folded into a
 * ticket record.
 */

/** The stable id of a brief, as `amy brief show` and a workflow name it. */
export type BriefId = string;

/** One question a later step appended, carried with its provenance. */
export interface BriefQuestion {
  /** The work id the question is about, which is also who must answer. */
  workId: string;
  /** The question itself, in the asking step's own words. */
  question: string;
  /** When it was asked, as an ISO instant. */
  at: string;
}

/**
 * The current brief as a step reads it: the rendered document and what it
 * took to be current, never a copy stashed at grooming time.
 */
export interface BriefView {
  /** The rendered document, sections and questions in order. */
  text: string;
  /** How many revisions the brief has had, starting at one. */
  revision: number;
}

/** A stored brief, as the persistence port reads it back. */
export interface BriefRecord {
  id: BriefId;
  /** The workflow's declared sections, in the order it declared them. */
  sections: { name: string; body: string }[];
  /** Questions appended by later work, oldest first. */
  questions: BriefQuestion[];
  /** The work ids this brief explains, in the caller's own vocabulary. */
  explains: string[];
  /** When the brief was created, as an ISO instant. */
  createdAt: string;
  /** When the content last changed, as an ISO instant. */
  updatedAt: string;
  /**
   * How many revisions the brief has had, starting at one. Two reads with
   * the same revision carry the same text, so a step that saw revision N
   * and sees N again knows nothing was answered in between.
   */
  revision: number;
}

/**
 * The mounted persistence port behind every brief read and write.
 *
 * The file-backed adapter owns the on-disk layout and the atomic
 * replace/append; this is the seam so a second store can mount without any
 * workflow learning where the first keeps its files. Reads return the
 * current version each time rather than a copy folded into a ticket record,
 * so a revision between ticks cannot be hidden by old state.
 */
export interface BriefStore {
  /** The current brief by id, or null when no such brief exists. */
  get(id: BriefId): Promise<BriefRecord | null>;

  /**
   * Creates a brief, or replaces every section of an existing one. The id
   * is the caller's to choose and stable for the brief's life; an append is
   * a separate operation, so a revision never loses a question.
   */
  write(input: {
    id: BriefId;
    sections: { name: string; body: string }[];
    /** The work ids this brief explains, in the caller's own vocabulary. */
    explains: string[];
    at: string;
  }): Promise<BriefRecord>;

  /**
   * Appends a question, with its work id and time. There is no operation
   * that appends an answer: a question is decided by the workflow that owns
   * the brief, and that decision is a revision, not an append.
   */
  appendQuestion(input: { id: BriefId; question: BriefQuestion; at: string }): Promise<BriefRecord>;

  /**
   * Lists brief ids whose every work id is terminal and older than the
   * store's retention policy, for the retirement sweep. The caller decides
   * what terminal means in its own vocabulary; this only reports what it
   * was told at write time and cannot invent a work state it never knew.
   */
  retired(explainsAreTerminal: (workId: string) => boolean, retentionCutoffMs: number, now: Date): Promise<BriefId[]>;

  /** Removes a brief by id. The event log remains the durable history. */
  remove(id: BriefId): Promise<void>;
}

/**
 * Renders the current brief as a step reads it: sections in the order the
 * workflow declared them, then the questions later work raised.
 *
 * The renderer lives here because every consumer renders the same document
 * the same way — a brief a workflow reads differently than a person does is
 * two briefs — and because a workflow configures sections, not layout.
 */
export function renderBrief(brief: BriefRecord): BriefView {
  const text = [
    ...brief.sections.map((section) => `${section.name}\n${section.body}`),
    ...brief.questions.map(
      (question) =>
        `Question (from ${question.workId}, ${question.at}): ${question.question}`,
    ),
  ].join("\n\n");

  return { text, revision: brief.revision };
}

/** A ceiling over one window. Either measure may be left out, or both set. */
export interface WindowLimit {
  tokens?: number;
  costUsd?: number;
}

/**
 * What an operator is willing to spend, and how close to it work may get.
 *
 * Two ceilings, because they are different currencies. Tokens are what a
 * subscription meters and what blocks at three in the morning; dollars are
 * what matters when the spending goes through an API key.
 */
export interface BudgetLimits {
  /** The rolling five hours a subscription plan meters. */
  perFiveHours?: WindowLimit;
  perWeek?: WindowLimit;
  /** The fraction of a ceiling at which new work stops being started. */
  stopAt: number;
  /** Present only when an operator enabled evidence-progress parking. */
  progress?: { maxUnchanged: number; handoff: "park" };
}

export type BudgetMeasure = "tokens" | "costUsd";

export type BudgetDecision =
  | { ok: true }
  | {
      ok: false;
      /** Which window is spent, named as the operator configured it. */
      window: string;
      measure: BudgetMeasure;
      used: number;
      limit: number;
      stopAt: number;
      /** How long until that window has room again. */
      retryAfterMs: number;
      /** One line, written to be read by a person in the log. */
      reason: string;
    };

/**
 * Whether work that spends an agent may start.
 *
 * Asked before the call rather than after it, because a ceiling checked
 * afterwards is a report, not a brake.
 */
export interface Budget {
  mayStart(now: Date): BudgetDecision;
}

import { CORE_ACTIONS } from "../actions.js";

export type ReviewState = "APPROVED" | "CHANGES_REQUESTED" | "COMMENTED" | "DISMISSED";

export type ReviewDecision = "APPROVED" | "CHANGES_REQUESTED" | "REVIEW_REQUIRED" | null;

export interface ReviewSubmission {
  author: string;
  state: ReviewState;
  /** The head the review was submitted against, so a stale review is visible. */
  commitSha: string;
  submittedAt: string;
}

export interface ReviewThread {
  id: string;
  author: string;
  body: string;
  isResolved: boolean;
  isOutdated: boolean;
  /**
   * The file the thread is on, as the forge names it from the repository
   * root. Absent on a host that has none, or on a conversation about the
   * pull request as a whole. Carried so a workflow can tell whether its
   * change touched the file without asking the forge again per thread.
   */
  path?: string;
  /**
   * The conversation the thread carries, oldest first, opening comment included.
   *
   * `author` and `body` above stay the opening comment's, so a consumer that
   * asks what a thread is *about* keeps its answer whether or not it asked for
   * the conversation. What follows it is what decides whose turn it is —
   * `comments.at(-1)?.author` reads that off the view alone, with no second
   * call — and a correction written inside the thread reaches whoever is
   * handed the whole of it.
   */
  comments: readonly { author: string; body: string; createdAt: string }[];
}

/**
 * What the forge's own checks say. `none` where it runs none at all, which is
 * a different answer from "not passing" and the workflow has to tell them
 * apart: a repository with no CI must not wait forever for a verdict.
 */
export type ChecksState = "passing" | "failing" | "running" | "none";

export interface ChecksView {
  state: ChecksState;
  /**
   * The commit they ran against.
   *
   * Carried for the same reason a review carries one: a green rollup from
   * three pushes ago says nothing about the head, and a workflow that could
   * not tell would hand a broken branch to a person.
   */
  commitSha: string;
}

/**
 * What stands between the branch and its base, as the forge sees it.
 *
 * Only the states a workflow can act on itself, plus not-yet-known — the
 * forge works a merge out asynchronously, and `unknown` is the honest answer
 * while it does rather than a guess in either direction.
 *
 * Everything else a forge reports here — blocked on a required review,
 * unstable because checks are red — is already carried by `reviewDecision`
 * and `checks`. A second name for it would be two fields free to disagree.
 */
export type MergeState = "mergeable" | "conflicting" | "behind" | "unknown";

/** One pull request waiting on somebody's review. */
export interface ReviewRequest {
  repo: string;
  number: number;
  url: string;
  title: string;
  author: string;
  /** The head it is asking about, so a review of an older one is visible. */
  headSha: string;
}

export interface PullRequestView {
  number: number;
  /**
   * Where a person opens it.
   *
   * Carried rather than derived, because deriving it means a workflow
   * knowing which forge this is, and the forge is the one thing here that is
   * meant to be swappable. It is what makes an announcement something you can
   * act on from a phone instead of a number you have to go and look up.
   */
  url: string;
  headSha: string;
  isDraft: boolean;
  /**
   * How big the change is, so a workflow can decide before it spends an agent.
   *
   * Carried here rather than counted from a diff, because the forge already
   * knows and fetching the diff to find out costs the thing the number exists
   * to avoid. A workflow that refuses to hand a five-hundred-file pull request
   * to an agent needs this *before* the call, and every other way of getting
   * it is more expensive than the call it is trying to prevent.
   */
  changedFiles: number;
  additions: number;
  deletions: number;
  reviewDecision: ReviewDecision;
  /** What the forge's own checks say about the head, or null where it runs none. */
  checks: ChecksView | null;
  mergeState: MergeState;
  /**
   * Whether the forge has already merged it, and where it would land.
   *
   * The open-only filter belongs to the by-branch search, so a pull request
   * read by number is readable after the merge too — and what a merged one
   * was against is the fact a stack wants without a second call. Carried
   * from the same node the rest of the view is mapped from, so a caller
   * never asks twice for what arrived together.
   */
  merged: boolean;
  /** The branch it is aimed at, as the forge names it. */
  base: string;
  /**
   * The branch it is opened from. Optional for a host that cannot say, and
   * read by a workflow that found the pull request some other way than by
   * its branch — by title, say — and has to push its fixes where the pull
   * request will see them.
   */
  headBranch?: string;
  reviews: readonly ReviewSubmission[];
  threads: readonly ReviewThread[];
  requestedReviewers: readonly string[];
}

export interface OpenPullRequestRequest {
  repo: string;
  branch: string;
  title: string;
  /**
   * What the pull request is opened against.
   *
   * Absent means the forge's own default, which is the answer an install
   * that named no mapping has always meant. A repository whose base branch
   * is not the forge's default for it names its own here — the lookup is the
   * caller's, because the caller is the one that knows the repository.
   */
  base?: string;
  /**
   * Opened as a draft, which says "look at this when you want to".
   *
   * For work nobody asked for at the moment it lands — an errand — that is
   * the honest state to open in. Work somebody is waiting on is not a draft.
   */
  draft?: boolean;
  /**
   * What the pull request says for itself.
   *
   * Empty where something else is already the description — a ticket the
   * forge links back to — and written out where nothing else would say why
   * the change exists.
   */
  body: string;
}

/**
 * The one parent a stacked pull request needs before it can choose its base.
 *
 * A forge that has no such pull request says so explicitly. The branches are
 * absent in that one case because inventing names for a missing parent is the
 * guess a workflow is here to avoid.
 */
export type PullRequestAncestry =
  | {
      state: "open" | "merged" | "closed-unmerged";
      headBranch: string;
      baseBranch: string;
    }
  | { state: "absent" };

const REFUSAL = Symbol.for("@amykit/core/code-host-refusal");

/**
 * The host answered, and the answer was no: the branch has nothing to merge,
 * a pull request already exists, the repository takes none.
 *
 * Thrown by an adapter instead of a plain error so a workflow can tell an
 * answer from an outage. An outage is retried by the engine, and asking again
 * may well work; a refusal is final, and the reason is something a person
 * should read.
 */
export class CodeHostRefusal extends Error {
  readonly [REFUSAL] = true;

  constructor(message: string) {
    super(message);
    this.name = "CodeHostRefusal";
  }
}

/** Whether a host's error is its answer rather than its failure, across copies of the core. */
export function isCodeHostRefusal(error: unknown): error is CodeHostRefusal {
  return typeof error === "object" && error !== null && (error as Record<symbol, unknown>)[REFUSAL] === true;
}

/** The capability names a workflow may claim before it mutates the forge. */
export const CODE_HOST_WRITE_CAPABILITIES = [
  "open-pull-request",
  "request-review",
  "resolve-thread",
  "merge",
  "submit-review",
  "create-issue",
] as const;

export type CodeHostWriteCapability = (typeof CODE_HOST_WRITE_CAPABILITIES)[number];

/**
 * The forge: a repository, a branch, a pull request and a login.
 *
 * Not one method here mentions a ticket, a plan or anything else a workflow
 * might be about, which is why it lives in the core rather than in the first
 * workflow that happened to need it. Two workflows mount one adapter behind
 * it instead of one adapter each.
 */
export interface CodeHost {
  findPullRequest(repo: string, branch: string): Promise<PullRequestView | null>;

  /**
   * The forge facts a stacked child needs to choose its base.
   *
   * The workflow decides what to do with each state; it never learns the
   * query or the vocabulary of the forge that answered it.
   */
  pullRequestAncestry?(repo: string, number: number): Promise<PullRequestAncestry | null>;

  /**
   * The pull request whose title names this id as a whole word, open or
   * merged, in one repository.
   *
   * A branch is derived from a title somebody can rename, and a renamed one
   * divorces the two: by branch, its pull request reads as never opened. An
   * id in the title survives the rename. An open one is preferred over a
   * merged one, and one closed without merging is not an answer at all.
   * Optional, because a host whose search cannot do this says so by not
   * offering it rather than by guessing.
   */
  findPullRequestMentioning?(repo: string, id: string): Promise<PullRequestView | null>;

  /** Throws a `CodeHostRefusal` when the host answers that it will not; any other throw is a failure. */
  openPullRequest(request: OpenPullRequestRequest): Promise<number>;

  requestReview(repo: string, pullRequestNumber: number, host: string): Promise<void>;

  /**
   * Closes one review thread, by its own id, in one act.
   *
   * The id is the one `findPullRequest` already carried on the thread, so a
   * caller never has to know which forge it is talking to — the same reason
   * the thread carries a `url` nobody derives.
   *
   * Settling a thread is the forge's word for "this is answered", and it is
   * the one act a state whose exit reads "no open thread" was missing: without
   * it, code that answers a review still leaves the conversation open for
   * somebody to close by hand.
   */
  resolveReviewThread(threadId: string): Promise<void>;

  /**
   * Puts a closed thread back, for a fix that was reverted.
   *
   * Mounted beside `resolveReviewThread` rather than invented for a day that
   * may never come, because the two are one capability — a forge either lets
   * this machine speak in a thread's lifecycle or it does not.
   */
  unresolveReviewThread(threadId: string): Promise<void>;

  /**
   * Open reviews per login, counted across every given repository.
   *
   * Counting one repository would send every review to whoever happens to be
   * quiet in that one.
   */
  reviewLoad(repos: readonly string[]): Promise<Record<string, number>>;

  /**
   * The open pull requests waiting on one login's review, in these
   * repositories and no others.
   *
   * Scoped to the list because a forge search is account-wide: asked without
   * it, this machine would pick up work from every repository its credential
   * can see, including ones nobody meant it to touch. `reviewLoad` answers
   * "how buried is each reviewer"; this answers "what is waiting on me", and
   * the second cannot be derived from the first — it counts, it does not say
   * which.
   */
  reviewsRequestedOf(login: string, repos: readonly string[]): Promise<ReviewRequest[]>;

  /**
   * The open pull requests one login's review left changes requested on, in
   * these repositories and no others.
   *
   * The mirror of `reviewsRequestedOf`: that answers "what is waiting on
   * me", this answers "where did my review leave changes requested", and a
   * discovery by review state is the second of the two. Scoped for the same
   * account-wide reason, and returning views rather than a count for the
   * same reason — the caller filters by what the review state means, which
   * is policy, and the port only says what the forge reports.
   */
  changesRequestedOf(login: string, repos: readonly string[]): Promise<ReviewRequest[]>;

  /**
   * The open pull requests one login authored that somebody asked to change,
   * in these repositories and no others.
   *
   * `changesRequestedOf` answers from the reviewer's side. A workflow driving
   * its own work needs the author's: those pull requests have usually left
   * the tracker's working status, so discovery by status never sees them
   * again. Scoped for the same account-wide reason as its twins, and decided
   * by the pull request's standing decision rather than by any one review,
   * because a later approval from the same reviewer settles it.
   */
  authoredWithChangesRequested?(login: string, repos: readonly string[]): Promise<ReviewRequest[]>;

  /**
   * One pull request by its number, merged or not.
   *
   * `findPullRequest` is a search, and a search is a filter: a review request
   * only ever knows a number, and a number can be a pull request that has
   * already landed — which is exactly when a stack still wants to read what
   * it sits on. The open-only filter belongs to the by-branch search, and
   * stays there.
   */
  pullRequest(repo: string, number: number): Promise<PullRequestView | null>;

  /**
   * Merges it, by the method the caller named.
   *
   * Which method a repository's ruleset allows is the caller's to decide —
   * that is policy, and it differs per repository and per team. The forge
   * only has to carry out what was asked and refuse honestly where it will
   * not: a refused merge comes back as a failed call, not as a quiet no-op.
   */
  merge(repo: string, number: number, method: "merge" | "squash" | "rebase"): Promise<void>;

  /**
   * Submits a review of it, in the state the caller decided on.
   *
   * The state is forge vocabulary — the same words every review in the view
   * is already carried as — and whether to submit one at all is the
   * workflow's, which is the same split that leaves thread-closing policy
   * in the workflow while the port makes it possible.
   */
  submitReview(
    repo: string,
    number: number,
    review: { state: ReviewState; body: string },
  ): Promise<void>;

  /**
   * Files an issue in the repository, as the forge writes one.
   *
   * A tracker port is a ticket somebody is driving; this is the repository's
   * own defect list, and a workflow that reports a finding to the forge
   * should not need a second key or a second client to say it.
   */
  createIssue(repo: string, issue: { title: string; body: string }): Promise<number>;

  /**
   * The statuses the forge recorded on one commit, as a list.
   *
   * A freeze is one reader's conclusion over this list — which names which
   * statuses count and which are noise — and the list is the port's
   * contribution. Reading it here, rather than beside the plugin, is what
   * keeps the second reader from shelling out on its own.
   */
  commitStatuses(repo: string, sha: string): Promise<
    { context: string; state: "passing" | "failing" | "running" }[]
  >;
}

/** The declaration capability for each mutating forge method. */
export const CODE_HOST_WRITE_FOR_METHOD: Readonly<Record<string, CodeHostWriteCapability>> = {
  openPullRequest: "open-pull-request",
  requestReview: "request-review",
  resolveReviewThread: "resolve-thread",
  unresolveReviewThread: "resolve-thread",
  merge: "merge",
  submitReview: "submit-review",
  createIssue: "create-issue",
};

/** The declaration capability an action needs when it dispatches to the forge. */
export function codeHostWriteFor(action: string): CodeHostWriteCapability | undefined {
  return CODE_HOST_WRITE_FOR_METHOD[CORE_ACTIONS[action]?.method ?? ""];
}

import type { ChildProcessWithoutNullStreams } from "node:child_process";

export interface CommandResult {
  ok: boolean;
  exitCode: number | null;
  stdout: string;
  stderr: string;
}

export interface RunOptions {
  cwd?: string;
  stdin?: string;
  timeoutMs?: number;
  env?: Record<string, string>;
  /**
   * Whether stdout is trimmed, which it is unless this is `false`. A caller
   * that reads whitespace as data, such as a file's content, asks for it whole.
   */
  trim?: boolean;
}

/**
 * Running a child process, behind a port.
 *
 * Every adapter that shells out goes through this, so each one can be tested
 * against a scripted runner instead of the real `gh`, `claude` or `git`.
 */
export interface CommandRunner {
  run(command: string, args: readonly string[], options?: RunOptions): Promise<CommandResult>;
  /** So protocol children stop through the same handbrake as ordinary commands. */
  spawn?(command: string, args: readonly string[], options?: Pick<RunOptions, "cwd" | "env">): ChildProcessWithoutNullStreams;
}

/**
 * What one command run produced.
 *
 * The output is kept verbatim and both streams are in it, because whatever
 * reads this next is usually an agent being told what happened, and a
 * summary is the part that loses the line that mattered.
 */
export interface CommandOutcome {
  /** The name from the allowlist, not the command line it stands for. */
  name: string;
  ok: boolean;
  /** Null when it was killed rather than exiting, which a timeout is. */
  exitCode: number | null;
  output: string;
  at: string;
}

/**
 * Any command line tool, reached by a name somebody put in the config.
 *
 * The port exists so a workflow can reach `pup`, `ntn`, `kubectl` or next
 * year's CLI without a plugin per tool and without the machine learning what
 * any of them mean. A workflow says *which* named command and with what
 * arguments; the config is the only place that says what that name runs.
 *
 * That split is the whole security model. A command line assembled from a
 * ticket, an agent's answer or anything else the outside world wrote would be
 * a machine that runs whatever a stranger can type into an issue.
 */
export interface Commands {
  run(name: string, args?: readonly string[], options?: { cwd?: string }): Promise<CommandOutcome>;
  /** What the config allows, for a refusal that names the alternatives. */
  available(): readonly string[];
}

/** A durable thread owned by one piece of work. */
export interface ThreadRef {
  id: string;
}

/**
 * What a reply is, when its medium let the person say: a turn in a
 * discussion, or the decision that ends one.
 */
export type ReplyKind = "discussion" | "decision";

/** One operator reply, including files the adapter downloaded locally. */
export interface Reply {
  at: string;
  author: string;
  text: string;
  files: string[];
  /**
   * Set only when the person marked it — a reaction, a button, a command.
   * Text alone carries none: what an unmarked reply means is the workflow's
   * policy, never the adapter's guess.
   */
  kind?: ReplyKind;
}

/** Where an operator and one piece of work talk without using the tracker. */
export interface Conversation {
  /** Opens the work's remembered thread, creating it only on first use. */
  open(workId: string, title: string): Promise<ThreadRef>;
  post(thread: ThreadRef, message: { text: string; files?: string[] }): Promise<string>;
  /** Replies after `since`, oldest first. Files are readable local paths. */
  replies(thread: ThreadRef, since: string): Promise<Reply[]>;
}

export type EventKind =
  /** The engine took an item off the queue, or found nothing due. */
  | "run.claimed"
  | "run.idle"
  /** A workflow decided, and what it decided. */
  | "work.planned"
  | "work.advanced"
  | "work.waiting"
  | "work.settled"
  | "work.failed"
  /** A dependency went down under this work, and then came back. */
  | "work.degraded"
  | "work.recovered"
  /** One action, and how it went. */
  | "action.started"
  | "action.finished"
  | "action.failed"
  /** An agent ran: which harness, which model, what it cost. */
  | "agent.run"
  /** An agent was handed over to another one, and why. */
  | "agent.handoff"
  /** The operator pulled the handbrake, and the engine obeyed. */
  | "stop.requested"
  | "stop.enforced"
  /** Work was parked because a budget window is nearly spent. */
  | "budget.parked"
  /** Work was parked because another agent run would add no evidence. */
  | "progress.parked"
  /** An announcement never reached anybody, and what it was going to say. */
  | "notify.failed"
  /** A worktree was removed, and why it was safe to remove. */
  | "worktree.removed"
  /** A worktree removal was asked for and refused, and why. */
  | "worktree.retained"
  /** A move the workflow's diagram does not draw, applied rather than refused. */
  | "workflow.undrawn_transition";

/**
 * Every kind, with the one line that says what it means.
 *
 * `Record<EventKind, string>` welds the two directions: dropping a member of
 * the union leaves a key here with nowhere to go, and adding one leaves this
 * table missing a property. Neither compiles, so the names cannot drift.
 *
 * The shape of each `detail` is declared in `events.json` and checked by
 * `checkEvent`. This table exists for the names, which is the part a
 * compiler can hold.
 */
export const EVENT_KINDS: Readonly<Record<EventKind, string>> = {
  "run.claimed": "the engine took an item off the queue",
  "run.idle": "nothing was due",
  "work.planned": "a workflow decided what to do next",
  "work.advanced": "the work moved to another state",
  "work.waiting": "the work stayed put, to be looked at again later",
  "work.settled": "the work reached a terminal state",
  "work.failed": "one attempt at this work threw",
  "work.degraded": "this work started failing, and is being retried",
  "work.recovered": "this work is moving again after failing",
  "action.started": "one action began",
  "action.finished": "one action finished",
  "action.failed": "one action threw",
  "agent.run": "an agent ran, and what it cost",
  "agent.handoff": "an agent was handed over to another one",
  "stop.requested": "the operator pulled the handbrake",
  "stop.enforced": "the engine obeyed the handbrake",
  "budget.parked": "work was parked against a budget window",
  "progress.parked": "work was parked because another run would add no evidence",
  "notify.failed": "an announcement never reached anybody",
  "worktree.removed": "a worktree was removed, and why it was safe to",
  "worktree.retained": "a worktree removal was refused, and why",
  "workflow.undrawn_transition": "the work moved where the workflow's diagram draws no arrow",
};

/**
 * Whether a string names a kind this build knows.
 *
 * Used when reading, never when appending. A log written by a newer build may
 * carry kinds this one has never heard of, and the honest thing for an
 * aggregate to do with a line it cannot read is leave it out.
 */
export function isEventKind(value: string): value is EventKind {
  return Object.prototype.hasOwnProperty.call(EVENT_KINDS, value);
}

export interface Event {
  at: string;
  kind: EventKind;
  workId?: string;
  state?: string;
  /**
   * Which build wrote this line.
   *
   * Set by the log rather than by callers, because a field every caller has
   * to remember is a field that goes missing. Without it, "we improved the
   * repo" and "what failed yesterday" stop being comparable, and a report
   * that aggregates several builds into one number is worse than no report.
   */
  build?: string;
  /**
   * Whatever the event needs to be readable later.
   *
   * This log is local and may name the work it is about. Anything leaving the
   * machine is projected and scrubbed at that boundary, never here, so the
   * operator's own view is not crippled to protect a report.
   */
  detail?: Record<string, unknown>;
}

/**
 * The append-only record of everything that happened.
 *
 * One source, several readers: `amy budget` aggregates it, a harness reads
 * it to know what a run cost, and a reporter projects it. Giving each of
 * those its own state is how they end up disagreeing with each other.
 */
export interface EventLog {
  append(event: Event): void;
  /** Events at or after the given instant, oldest first. */
  read(since?: Date): Event[];
  /**
   * Every event at or after `since`, oldest first, then every event any
   * process appends afterwards, until the returned function is called.
   *
   * Optional because a log may be a sink nobody can watch: `watchEvents`
   * reads one of those by polling instead.
   */
  watch?(since: Date, onEvent: (event: Event) => void): () => void;
}

export interface WatchOptions {
  /** How often a log without `watch` is read again. */
  everyMs?: number;
  /**
   * Called once, when the log cannot be watched and is polled instead. The
   * caller words it: the core words nothing a person reads.
   */
  onPolling?: (everyMs: number) => void;
}

/**
 * Watch any log: through its own `watch` when it has one, by polling `read`
 * when it does not.
 *
 * The poll keeps a cursor at the last instant it delivered and remembers the
 * lines it delivered at that instant, so two events stamped the same
 * millisecond are both delivered and neither twice. A line appended later
 * with an instant older than the cursor is not seen; a log that can be
 * watched has no such gap.
 */
export function watchEvents(
  log: EventLog,
  since: Date,
  onEvent: (event: Event) => void,
  options: WatchOptions = {},
): () => void {
  if (log.watch) return log.watch(since, onEvent);

  const everyMs = options.everyMs ?? DEFAULT_POLL_MS;
  options.onPolling?.(everyMs);

  let cursor = since.getTime();
  let atCursor = new Map<string, number>();
  let stopped = false;
  const poll = (): void => {
    const already = new Map(atCursor);
    for (const event of log.read(new Date(cursor))) {
      // A callback that stops the watch stops the rest of this batch too.
      if (stopped) return;
      const line = JSON.stringify(event);
      const at = new Date(event.at).getTime();
      const left = at === cursor ? (already.get(line) ?? 0) : 0;
      if (left > 0) {
        already.set(line, left - 1);
        continue;
      }
      if (at !== cursor) {
        cursor = at;
        atCursor = new Map();
      }
      atCursor.set(line, (atCursor.get(line) ?? 0) + 1);
      onEvent(event);
    }
  };

  poll();
  const timer = setInterval(poll, everyMs);
  return () => {
    stopped = true;
    clearInterval(timer);
  };
}

const DEFAULT_POLL_MS = 1_000;

import { AttemptOutcome } from "./Agent.js";

/** Where one piece of work happens: its repository, and its own tree in it. */
export interface Workplace {
  repo: string;
  workId: string;
}

/**
 * The gate: the check that decides whether an implementation holds, before
 * anything is published for a person to read.
 *
 * What the answer means is a workflow's to weigh, but what a gate *is*
 * belongs below every workflow, so a second workflow's own check slots into
 * the same seam. It takes the workplace rather than the work: a gate needs a
 * directory, and any kind of work has one.
 */
export interface Gate {
  /**
   * Runs the gate in the work's own tree, and says what happened.
   *
   * `ok` is the verdict; `output` is the evidence, verbatim, so a retry can
   * be handed the reason it is retrying rather than a summary of it.
   */
  run(workplace: Workplace): Promise<AttemptOutcome>;
}

/**
 * A GraphQL endpoint, behind a port.
 *
 * Keeping the transport out of the adapter means the adapter's queries and
 * its mapping can be tested without a network or an API key.
 */
export interface GraphQLClient {
  request<T>(query: string, variables?: Record<string, unknown>): Promise<T>;
}

import { AgentRun } from "../agent-run.js";

export interface HarnessReply {
  /** Just the answer, with whatever envelope carried it stripped away. */
  text: string;
  run: AgentRun;
}

/**
 * What a caller knows about a question that a relay might need and the CLI
 * answering it never does.
 *
 * Both fields are for whoever composes harnesses rather than for the harness
 * itself: one ties the account to the work it was spent on, the other lets a
 * skill named for a step be the thing that answers. A single-harness install
 * ignores both, which is why they are optional.
 */
export interface AskContext {
  workId?: string;
  /** The action being performed, in the workflow's own vocabulary. */
  step?: string;
  /**
   * The current brief the work belongs to, rendered, when there is one.
   *
   * A workflow-declared half-step — a self-review, say — is a generic `ask`
   * with no ticket in it, so without this field it would be the one step
   * blind to the reason the work exists. A caller with no brief passes
   * nothing, and the prompt is unchanged.
   */
  brief?: string;
  /**
   * Says whether a run that completed actually holds, while a relay can still
   * hand the step to the next rung.
   *
   * A run can complete and still not be the answer — an implementation that
   * changed no file is the case. Called by a relay after each completed run;
   * what it returns is the run the relay climbs on, so a step that turns the
   * outcome to `failed` gets the stronger model or the next skill.
   */
  verify?: (reply: HarnessReply) => Promise<HarnessReply>;
  /**
   * The run may read the checkout and must change nothing in it. A harness
   * that can enforce this does, through its own sandbox; one that cannot
   * refuses the run rather than relying on the prompt asking nicely.
   */
  readOnly?: boolean;
  /**
   * The skill the prompt is addressed to, and the directory its `SKILL.md`
   * is in.
   *
   * Set by a relay that addressed the prompt to a skill. A harness that runs
   * apart from the operator's own setup sees none of their skills, so it is
   * handed this one by place rather than trusting it to be found.
   */
  skill?: { readonly name: string; readonly path: string };
}

/**
 * One coding agent CLI, reduced to the only thing that differs between them.
 *
 * A prompt, a directory, and an account of what the answer cost. Nothing here
 * names a ticket, a plan or a review, which is why it is a port of the core:
 * the workflow-shaped things an agent does are built *on* this, one layer up,
 * and a second workflow wants this rather than the first workflow's prompts.
 */
export interface Harness {
  readonly name: string;
  ask(prompt: string, cwd: string, context?: AskContext): Promise<HarnessReply>;
}

/**
 * What sort of announcement this is.
 *
 * Carried so a channel can decide whether it wants one, and kept to the three
 * the engine can honestly tell apart: it is retrying, it has stopped, or the
 * work is moving again. The distinction earns its place — a step that failed
 * once and worked on the second attempt is not worth writing down, and a
 * channel with only "something went wrong" to go on would file it anyway.
 *
 * Optional, and absent means "nothing special": a workflow saying why it is
 * holding is not a failure of any kind.
 */
export type AnnouncementKind = "failing" | "gave-up" | "recovered";

export interface Announcement {
  text: string;
  workId: string;
  /** Where the machine is stuck, for a human deciding whether to care. */
  state: string;
  kind?: AnnouncementKind;
}

/** How the machine reaches the operator when it needs them. */
export interface Notifier {
  announce(announcement: Announcement): Promise<void>;
}

import { QueueItem } from "../queue-item.js";

export interface EnqueueRequest {
  workId: string;
  reason: string;
  /** Milliseconds to hold the item back. Zero means the next look is immediate. */
  delayMs?: number;
  attempt?: number;
  /** How urgent, smaller first. A queue that does not order by it keeps it and ignores it. */
  priority?: number;
  progress?: Record<string, { count: number; detail: string }>;
}

export interface Queue {
  enqueue(request: EnqueueRequest, now: Date): QueueItem;

  /**
   * Takes the earliest item that is due, and marks it as being worked on so a
   * second worker cannot take it too. Returns null when nothing is due, which
   * is different from the queue being empty.
   */
  claim(now: Date): QueueItem | null;

  complete(item: QueueItem): void;

  /** Puts a claimed item back, for a worker that could not finish it. */
  release(item: QueueItem): void;

  /**
   * Brings every look at one piece of work that is still held back forward to
   * now, and says how many moved.
   *
   * The queue is the schedule, so something arriving earlier than expected —
   * a review comment, a webhook, somebody who does not want to wait — has to
   * move the look that already exists rather than add one beside it. Two
   * items for one piece of work would each chain their own successor, and the
   * queue would fork into two chains that both spend an agent.
   *
   * A look that is already due is left alone: it is not held back, so there
   * is nothing to bring forward.
   */
  promote(workId: string, now: Date): number;

  /**
   * Sets the urgency of every look at one piece of work still waiting, and
   * says how many changed.
   *
   * Discovery reads urgency fresh each time, and a ticket somebody raised to
   * urgent this morning must not wait behind what was urgent yesterday.
   * Optional, because a queue that keeps no order has nothing to refresh.
   */
  reprioritize?(workId: string, priority: number | undefined): number;

  /** Returns items abandoned by a dead worker so they get picked up again. */
  recover(olderThanMs: number, now: Date): QueueItem[];

  /** Deletes finished items past their retention, so the directory stays small. */
  prune(retentionDays: number, now: Date): number;

  ready(now: Date): QueueItem[];
  pending(): QueueItem[];
}

/**
 * The handbrake.
 *
 * Deliberately not a plugin: a switch that depends on plugins loading cannot
 * stop a run whose plugins are what went wrong.
 */
export interface StopSwitch {
  isRequested(): boolean;
  reason(): string | null;
  request(reason: string): void;
  clear(): void;
  /**
   * Calls back as soon as a stop is requested, and returns the function that
   * stops watching.
   *
   * Checking at boundaries alone is not enough: an agent call can run for
   * half an hour, and a handbrake nobody pulls until the next boundary is not
   * a handbrake.
   */
  watch(onRequested: (reason: string) => void): () => void;
}

import { WorkRecord } from "../work.js";

/**
 * Where the record of one piece of work is kept between looks.
 *
 * Generic over the record, because the shape past the four fields the core
 * reads belongs to whichever workflow is mounted.
 */
export interface Store<R extends WorkRecord = WorkRecord> {
  load(workId: string): R | null;
  save(record: R): void;
  all(): R[];
}

import { CORE_ACTIONS } from "../actions.js";

/**
 * One comment on a ticket, as the tracker holds it.
 *
 * `fromAmy` is the tracker's answer, not a guess by whatever reads the
 * conversation: amy authenticates with a key issued to a person, so *which*
 * account wrote a comment is a fact only the tracker knows.
 */
export interface Comment {
  /** Who wrote it, as the tracker names them. */
  author: string;
  body: string;
  /** When it was written, as an ISO instant. */
  at: string;
  /** Whether the machine's own account wrote it. */
  fromAmy: boolean;
}

export interface FollowUpRequest {
  parentTicketId: string;
  title: string;
  body: string;
}

/**
 * What a ticket is, carried to every step that reads one. The id is the
 * identifier the tracker and the PR title spell it, e.g. `PROJ-1239`.
 */
export interface Ticket {
  id: string;
  title: string;
  /** The tracker's team, where it has one. Linear does; GitHub Issues does not. */
  team?: string;
  url: string;

  /**
   * The branch name the tracker itself derived, e.g.
   * `ada/proj-1239-total-is-wrong-on-the-invoice-summary-and-the-list`.
   *
   * Never derive this locally. The tracker owns the slug, it truncates long
   * titles in its own way, and a branch that disagrees with it breaks the
   * tracker's automatic PR linking. Absent where the tracker derives none,
   * and a workflow that needs one refuses the ticket by name.
   */
  branchName?: string;

  /**
   * The status *name*, not its category.
   *
   * Matching on the category would be wrong: the tracker files In Review,
   * In QA, Ready To Release and Triage Review under the same `started`
   * category as In Progress, so a category match picks up tickets that are
   * already past implementation.
   */
  status: string;

  /**
   * The description the tracker fetched, when it fetched one.
   *
   * Absent stays absent: an empty description is a real state and not an
   * error, and a prompt that says so is what lets the agent ask for a body
   * rather than invent one.
   */
  body?: string;

  /**
   * What the team says this ticket *is*, as the tracker's own names.
   *
   * A label is how a team marks what a ticket is for — an epic labelled
   * `Feature` carries its sub-issues as the actual work — and it is the
   * tracker's fact rather than the caller's guess. Empty where the ticket
   * carries none, which is most of them and is a state, not an error.
   */
  labels: string[];

  /** Repository the work belongs to, as `owner/name`. */
  repo: string;

  /**
   * Every repository the work spans, where the tracker can tell, in the
   * order the tracker keeps them — Linear's is label order. Absent where it
   * cannot, which is a ticket in `repo` alone.
   *
   * `repo` is not necessarily in it, nor first: `repo` is where the ticket's
   * work started before anybody named repositories, and the list is what
   * the ticket names now, which may have moved on. A workflow that splits
   * work by repository reads this for membership and order, and one that
   * does not keeps reading `repo`.
   */
  repos?: readonly string[];

  /**
   * Who the ticket is assigned to, as the identity `assign` takes. `null` is
   * nobody; absent is a tracker that does not say, which a workflow cannot
   * read as either.
   */
  assignee?: string | null;

  /**
   * How urgent the tracker says it is, smaller first. Absent where the
   * tracker has no urgency or nobody set one.
   */
  priority?: number;

  /**
   * The brief this ticket's work belongs to, when a grooming workflow kept
   * one: its id, for the workflow's runtime to resolve against the mounted
   * brief store, and the rendered text beside it, so a step that never asks
   * the store still reads the current statement.
   *
   * The tracker's own facts — the parent, say — decide the id; nothing
   * derives it from the body. A ticket with no brief carries neither field,
   * and every prompt built from it is unchanged.
   */
  briefId?: string;
  /**
   * The current statement of the feature this ticket's work belongs to, when
   * a grooming workflow keeps one.
   *
   * A brief is the revisable artifact a group of sibling tickets implement;
   * the ticket's own body is fixed at grooming time and never answers a
   * question asked later. This is the *rendered current text* rather than a
   * pointer, so every step reads what a revision between ticks actually
   * said — but it is a snapshot from one observation, not a live view: a
   * step that needs it again re-observes, the way every other field here is
   * re-read rather than replayed from the record. A ticket with no brief
   * carries none, and every prompt built from one is unchanged.
   */
  brief?: string;
}

/** Reads a tracker answers, and writes only the workflow's declared surface. */
export interface TrackerReads {
  /**
   * Tickets assigned to the operator that sit in the working status.
   *
   * Implementations must match the status by *name*. The tracker files
   * In Review, In QA and Ready To Release under the same category as
   * In Progress, so a category match returns work that is already past
   * implementation.
   */
  inProgress(): Promise<Ticket[]>;

  /** One ticket by id, including after it has left the working status. */
  get(ticketId: string): Promise<Ticket | null>;

  /**
   * The conversation on a ticket, oldest first, up to now.
   *
   * `since` is the instant to read from — a waiting state asks for what
   * arrived after its question, and a prompt rebuild asks for the whole
   * thread. Returning the text is the point: `hasReplyAfter` answers
   * *whether* the ticket was answered, and an answer a caller cannot read is
   * the defect this method exists to close.
   */
  comments(ticketId: string, since?: string): Promise<Comment[]>;

  /** Whether anybody other than the machine has replied since the given instant. */
  hasReplyAfter(ticketId: string, since: string): Promise<boolean>;
}

/**
 * The writes a tracker answers — deliberately its own surface rather than
 * half of one contract.
 *
 * The read half is what discovery and observation need; this half is what
 * changes the outside world. A workflow that promised not to edit the
 * tracker receives only the read half, and a mount that hands a workflow a
 * mutator it never claimed is refused at boot — the refusal is the reason
 * the two halves are separate.
 */
export interface TrackerWrites {
  comment(ticketId: string, body: string): Promise<void>;

  setStatus(ticketId: string, statusName: string): Promise<void>;

  assign(ticketId: string, trackerIdentity: string): Promise<void>;

  createFollowUp(request: FollowUpRequest): Promise<string>;
}

/** The issue tracker that owns the ticket. */
export type Tracker = TrackerReads & TrackerWrites;

/**
 * A feature is a tracker-owned grouping of work, deliberately not a ticket
 * workflow's private parent convention. Any workflow may read it through the
 * same provider that supplies ticket work.
 */
export interface Feature {
  id: string;
  title: string;
  body?: string;
  repos: readonly string[];
}

/** Read-only feature discovery supplied by a tracker provider. */
export interface FeatureTracker {
  features(): Promise<Feature[]>;
  getFeature(id: string): Promise<Feature | null>;
}

/** Work created by a grooming run, with durable grooming provenance. */
export interface GroomedWork {
  id: string;
  featureId: string;
  /** Identifies the grooming workflow, not a brief membership. */
  groomedBy: string;
  title: string;
  body: string;
  retired: boolean;
}

/**
 * Tracker mutations a grooming workflow needs. They are feature-scoped rather
 * than ticket-workflow operations so a provider can implement them without
 * importing or knowing about ticket-to-qa.
 */
export interface FeatureWorkTracker {
  groomedWork(featureId: string, groomedBy: string): Promise<GroomedWork[]>;
  createGroomedWork(input: Omit<GroomedWork, "id" | "retired">): Promise<GroomedWork>;
  updateGroomedWork(id: string, input: Pick<GroomedWork, "title" | "body">): Promise<GroomedWork>;
  retireGroomedWork(id: string): Promise<void>;
}

/** Provider-neutral capability needed by a feature grooming workflow. */
export type GroomingTracker = FeatureTracker & FeatureWorkTracker;

/**
 * What one workflow declares about the writes it may make, named so a boot
 * refusal can quote it back.
 *
 * The core knows the names; a workflow's policy decides which to claim. A
 * mount refuses a workflow that declares a tracker-mutating action while
 * claiming none, naming the action and the capability before any tick.
 */
export const TRACKER_WRITE_CAPABILITIES = [
  "comment",
  "set-status",
  "assign",
  "create-follow-up",
] as const;

export type TrackerWriteCapability = (typeof TRACKER_WRITE_CAPABILITIES)[number];

/**
 * The tracker action a core action resolves to, so a mount can ask whether a
 * declared action mutates without learning what any action means.
 *
 * Derived from `CORE_ACTIONS` at read time except where an action's handler
 * makes additional mutations beyond its dispatch method.
 */
export function trackerWritesFor(action: string): TrackerWriteCapability[] {
  // The hand-off handler changes both status and assignee. Its catalogue entry
  // names the dispatch method, while this table names every external mutation
  // the action performs so boot can reject an incomplete declaration.
  if (action === "hand-off-to-qa") return ["set-status", "assign"];
  const capability = TRACKER_WRITE_FOR_METHOD[CORE_ACTIONS[action]?.method ?? ""];
  return capability ? [capability] : [];
}

export function trackerWriteFor(action: string): TrackerWriteCapability | undefined {
  return trackerWritesFor(action)[0];
}

export const TRACKER_WRITE_FOR_METHOD: Readonly<Record<string, TrackerWriteCapability>> = {
  comment: "comment",
  createFollowUp: "create-follow-up",
  setStatus: "set-status",
  assign: "assign",
};

/**
 * What a workflow declares it may do to the tracker: every tracker-mutating
 * core action it uses, as capabilities, or nothing at all.
 *
 * Derived from the actions it declares rather than written by hand, so the
 * claim cannot drift from the table it is checked against.
 */
export function trackerCapabilitiesFor(usesActions: readonly string[]): TrackerWriteCapability[] {
  return TRACKER_WRITE_CAPABILITIES.filter((capability) =>
    usesActions.some((action) => trackerWritesFor(action).includes(capability)),
  );
}

/** The port kind the workplace is mounted under: the provider is the machine's workspace. */
export const WORKSPACE_PORT = "workspace";

/**
 * The workplace, answered by the plugin whose slice names it.
 *
 * One plugin owns the machine's workspace: the repositories, where their
 * standing checkouts live, the branches, the worktrees. Nothing outside that
 * plugin's slice carries the vocabulary, and `PluginContext.checkouts()`
 * answers through what this port's provider holds, so a plugin works in the
 * same workplace the worktrees and the doctor see.
 */
export interface Workspace {
  /** Where the standing checkouts the workflows and gates work in live. */
  readonly workspaceRoot: string;
  /**
   * Where one repository's checkout is, instead of under the root.
   *
   * A repository named here is never looked for under the root at all, so
   * work can span repositories two unrelated parents hold.
   */
  readonly checkouts: Readonly<Record<string, string>>;
}

/**
 * One isolated checkout per piece of work, or none.
 *
 * A shared checkout is one mutable tree everything contends for: two tickets
 * on one repository cannot implement at the same time, an interrupted run
 * leaves the tree dirty under the next item's gate, and preparing an item can
 * repoint a branch an existing pull request is built on. This port is the
 * seam underneath all of that — a workflow never shells out to `git worktree`
 * on its own, and never invents cleanup, discovery or recovery.
 *
 * The provider mounts the port unconditionally; the consumer reads it as
 * `Worktree | undefined` and runs unchanged when nothing mounted one, which
 * is what keeps a shared-checkout install a real install.
 */

/** What a tree is, as the manager holds it on disk. */
export interface WorktreeInfo {
  /** The work the tree belongs to, as the queue and the record name it. */
  workId: string;
  /** The repository the work is in, as `owner/name`. */
  repo: string;
  /** The workflow that acquired it, which is also the first path segment. */
  workflow: string;
  /** Where the tree lives, outside every repository. */
  path: string;
  /**
   * Whether the work is still going. `in-flight` is a record the store still
   * holds in a non-terminal state; `terminal` is work that finished; `orphaned`
   * is a tree whose work id is no longer in the store at all — offered for
   * recovery before any prune touches it.
   */
  state: "in-flight" | "terminal" | "orphaned";
  /** Whether the tree holds no uncommitted change. */
  clean: boolean;
  /** The branch the tree is on, as the tracker named it. */
  branch: string;
  /** When the tree was created, and when it was last used. */
  acquiredAt: string;
  updatedAt: string;
  /** Whether the tree is past its retention window. */
  retentionEligible: boolean;
  /**
   * Whether an automatic prune may remove it: terminal, clean, and past
   * retention. Everything else — a crash, an escalation, a dirty tree, work
   * still going — is retained, and the only way out is a named command.
   */
  prunable: boolean;
}

/**
 * Checkout isolation for one install.
 *
 * Trees are predictable paths under one root, created or reused, never
 * reset. Acquisition never touches the standing checkout: not its files, not
 * its uncommitted work, not the branch it is sitting on.
 */
export interface Worktree {
  /**
   * The path of this item's own tree, creating it when it does not exist and
   * reusing it when it does. A new tree is cut from the default branch; the
   * item's branch is prepared there by `Git`, which owns branch vocabulary.
   */
  acquire(workId: string, repo: string): Promise<string>;

  /**
   * The path this item's tree would live at, without touching the disk.
   *
   * What a caller reads when it needs the path for an agent step and the
   * tree's existence is the acquire's business, not its own.
   */
  pathFor(workId: string, repo: string): string;

  /** Every tree this machine holds, and what state each is in. */
  states(): Promise<WorktreeInfo[]>;

  /**
   * Removes a tree that has become safe to remove, and says whether it did.
   *
   * An in-flight or dirty tree is refused, naming the reason, unless the
   * caller forces it — the escape hatch is a named command, never a predicate.
   * Every removal that happens is logged.
   */
  release(workId: string, repo: string, options?: { force?: boolean }): Promise<boolean>;

  /**
   * Removes every tree the retention predicate allows, and leaves every other
   * one exactly as it was.
   *
   * Safe to call at any time, from the daemon's startup and after terminal
   * work alike: the predicates below decide, never the caller.
   */
  prune(now: Date): Promise<string[]>;
}

export interface QueueItem {
  /** Sortable, so the queue has a stable order without an index. */
  id: string;
  workId: string;
  enqueuedAt: string;
  /** The queue will not hand this out before this instant. */
  notBefore: string;
  attempt: number;
  /** Why this item exists, for reading the log later. */
  reason: string;
  /**
   * How urgent the work is, smaller first, where whoever found it said.
   *
   * Carried on the item rather than looked up at claim time, so a queue that
   * orders by it reads one directory and asks nobody. Absent is after every
   * item that has one.
   */
  priority?: number;
  /** Consecutive no-evidence attempts, durable across worker processes. */
  progress?: Record<string, { count: number; detail: string }>;
}

export function isReady(item: QueueItem, now: Date): boolean {
  return new Date(item.notBefore).getTime() <= now.getTime();
}

import { ActionSpec } from "./actions.js";
import { Action, Moved, Plan, WorkRecord } from "./work.js";

/** The evidence policy an opting-in workflow asks the engine to enforce. */
export interface ProgressPolicy {
  maxUnchanged: number;
  handoff: "park";
}

/**
 * The collection a workflow contributes its runtime to.
 *
 * Named here rather than by the engine that reads it, because a workflow
 * should not have to know which engine will drive it — and an engine should
 * not have to name the workflow. The same reasoning as the notification
 * channels, one level up.
 */
export const WORKFLOW_RUNTIME = "workflow-runtime";

/**
 * What one action needs to do its work, and where it writes what happened.
 *
 * `outcomes` is a bag the workflow owns at both ends: its handlers fill it
 * and its `apply` reads it. The engine only carries it between the two,
 * which is why it is typed as loosely here as it is.
 */
export interface ActionContext<R extends WorkRecord = WorkRecord, O = unknown> {
  readonly record: R;
  readonly observation: O;
  readonly outcomes: Record<string, unknown>;
}

export type ActionHandler<R extends WorkRecord = WorkRecord, O = unknown> = (
  action: Action,
  context: ActionContext<R, O>,
) => Promise<void>;

/**
 * How one declared action runs: a handler the workflow wrote, or a port and
 * a method the host calls for it.
 *
 * A port-and-method is called with the action and its context, and whatever
 * it returns is written to `outcomes` under the action's name. Only a method
 * marked with `acceptsAction` can be reached this way; one that wants its own
 * arguments is reached through a handler instead.
 */
export type ActionImplementation<R extends WorkRecord = WorkRecord, O = unknown> =
  | ActionHandler<R, O>
  | ActionSpec;

/** One piece of work discovery found, with how urgent its source says it is. */
export interface FoundWork {
  workId: string;
  /** Smaller first; absent is after every piece of work that has one. */
  priority?: number;
}

/**
 * How a workflow's actions actually run.
 *
 * The decision — `Workflow.plan` — is pure and says *what* should happen. This
 * is the other half: what the outside world looks like before deciding, what
 * each action does, and how what it produced folds back into the record. All
 * three are domain knowledge, and none of them belongs in an engine.
 *
 * An engine that takes this drives any workflow. One that reaches for a
 * tracker or a pull request itself drives exactly one, whatever its types
 * say.
 */
export interface WorkflowRuntime<R extends WorkRecord = WorkRecord, O = unknown> {
  /**
   * What the decision function is given as its policy.
   *
   * Carried here because a policy is written in the workflow's own
   * vocabulary — attempt ceilings, backoffs, how many open reviews one person
   * may be handed — and an engine that held it would be an engine that has an
   * opinion about all three.
   */
  readonly policy: unknown;
  /** Opt-in evidence accounting; omitted means the workflow behaves as before. */
  readonly progress?: ProgressPolicy;
  /**
   * Work that exists and is not on the queue yet, by id — or by id with how
   * urgent it is, for a runtime whose source says. A plain id is work with
   * no urgency, which is every runtime that never heard of one.
   */
  found(): Promise<readonly (string | FoundWork)[]>;
  /** The record a work id starts with, before anything has happened to it. */
  newRecord(workId: string, now: Date): R;
  /** A snapshot of the outside world for one record, gathered before deciding. */
  observe(record: R): Promise<O>;
  /**
   * Every action this workflow can emit, and what runs it.
   *
   * The key is the declaration and the value the implementation, so an
   * action cannot be declared without something behind it, nor implemented
   * without being declared. The mount reads the keys as the workflow's reach
   * and refuses, at boot and by name, a key whose implementation is missing
   * or points at a port nothing mounted.
   */
  readonly actions: Readonly<Record<string, ActionImplementation<R, O>>>;
  /**
   * Folds what the actions produced, and what was observed, into the record.
   *
   * The engine has already folded the state, the attempt count and the
   * history through `applyPlan`; it cannot fold the rest, because it does not
   * know what a triage or a gate result is. The observation is here because
   * not everything a record learns comes from an action — an answer somebody
   * left elsewhere arrives as an observation, and a fold that could not see
   * one would leave the record waiting on it forever.
   *
   * `record` has already been advanced, so its `state` is where the work is
   * going. Where it came from is `moved.from` — `null` when the plan did not
   * advance — and a fold that remembers where it was interrupted reads that,
   * never `record.state`.
   */
  apply(
    record: R,
    plan: Plan,
    outcomes: Record<string, unknown>,
    observation: O,
    now: Date,
    moved: Moved | null,
  ): R;
}

/**
 * An action the core knows how to dispatch.
 *
 * Deliberately open: the core owns the *catalogue* of action names, and a
 * workflow composes them. The typed payload for each one lives in the
 * workflow package that emits it, so the core never learns a domain.
 */
export type Action = { type: string } & Record<string, unknown>;

export interface Transition {
  at: string;
  from: string;
  to: string;
  why: string;
}

/**
 * What the core remembers about one piece of work.
 *
 * A workflow extends this with whatever else it needs. The core only ever
 * reads and writes the fields declared here.
 */
export interface WorkRecord {
  id: string;
  /** The workflow enumerates its states. The core treats this as a label. */
  state: string;
  updatedAt: string;
  /** Counts only work that was actually tried, so a ceiling speaks about failures. */
  attempts: Record<string, number>;
  /**
   * Counts every look in a state. Optional while records written before this
   * field existed are still on disk; their attempts are their best-known
   * looks until the next saved move writes an explicit count.
   */
  looks?: Record<string, number>;
  /**
   * Set when the engine let this work go at its attempt ceiling. Kept on the
   * record rather than inferred from the queue, because queue history is
   * pruned and history is not: without it, a pruned item would be discovered
   * again at attempt zero and fail forever. `amy look <id>` clears it.
   */
  gaveUp?: { at: string; reason: string };
  history: Transition[];
  /**
   * Every call this record has made, by id (`TBO-1/REVIEW#1`), each a whole
   * record of the callee's own. Kept after the call returns, so a second
   * entry into the same state never reuses the first's history.
   */
  calls?: Record<string, WorkRecord>;
  /** The call this record is waiting on, while it is in a call state. */
  calling?: string;
  /** What a callee was called with, for a record a caller started. */
  input?: Record<string, unknown>;
  /**
   * The lanes this record started at the fork it last entered, by lane state:
   * which call each one is, and once it has ended, where and with what.
   * Kept after the join, so what each lane found is still there to read.
   */
  lanes?: Record<string, Lane>;
  /**
   * The commit a caller lent this record to check, for a lane bound with
   * `revision`. It is checked in a tree detached at that commit, read-only.
   */
  revision?: string;
  /**
   * The lanes a record left running when it moved out of their fork other
   * than through the join, by their records' ids: the trees they were lent
   * go back on its next look.
   */
  abandoned?: string[];
}

/** One lane of a fork, as its caller holds it. */
export interface Lane {
  /** The id of the lane's own record, in the caller's `calls`. */
  readonly call: string;
  /** The terminal state the lane ended in, once it has. */
  readonly end?: string;
  /** What the lane's workflow returned at that end, if anything. */
  readonly output?: unknown;
}

export type Plan<State extends string = string, Effect extends Action = Action> =
  /**
   * Do the work, stay in this state, and look again straight away. The next
   * look sees whatever the actions recorded, which is how a pure decision
   * function drives work that takes minutes or hours.
   */
  | { kind: "act"; effects: Effect[]; why: string; attempt?: boolean }
  | { kind: "advance"; to: State; effects: Effect[]; why: string }
  /**
   * Nothing to do until the outside world moves. May still carry actions, so
   * a workflow can say why it is stuck without leaving the state.
   */
  | { kind: "wait"; retryAfterMs: number; why: string; effects: Effect[] }
  /** Terminal, do not queue anything else. */
  | { kind: "settled"; why: string };

/**
 * The move one look made, handed to the workflow's fold beside the record.
 *
 * The record the fold receives has already been advanced, so its `state` is
 * where the work went, not where the look started — the obvious reading of it
 * is the wrong one. This says both, and is `null` for a look that stayed put.
 */
export interface Moved {
  readonly from: string;
  readonly to: string;
}

/** What `plan` moved `record` by, read before the record is advanced. */
export function movedBy(record: WorkRecord, plan: Plan): Moved | null {
  return plan.kind === "advance" ? { from: record.state, to: plan.to } : null;
}

export function actionsOf(plan: Plan): readonly Action[] {
  switch (plan.kind) {
    case "act":
    case "advance":
    case "wait":
      return plan.effects;
    case "settled":
      return [];
  }
}

/** The tries a state has actually spent. */
export function attemptsIn(record: WorkRecord, state: string): number {
  return record.attempts[state] ?? 0;
}

/** Every look a state took, including waits and work that prepared a later try. */
export function looksIn(record: WorkRecord, state: string): number {
  return record.looks?.[state] ?? attemptsIn(record, state);
}

/** An action's outcome can say that the attempt charged before it ran never happened. */
export interface NotATry {
  notATry: true;
  retryAfterMs?: number;
}

/** Reads the generic outcome without learning any workflow's domain result. */
export function notATryIn(outcomes: object): NotATry | undefined {
  return Object.values(outcomes).find((outcome): outcome is NotATry =>
    !!outcome && typeof outcome === "object" && (outcome as Record<string, unknown>).notATry === true,
  );
}

/**
 * Folds a plan into the next record: the state, the attempt count and the
 * history, and nothing else.
 *
 * Whatever a workflow's actions produced is folded in by the workflow, not
 * here, because the core does not know what a triage or a gate result is.
 * Generic over the record so a workflow's richer type survives the call.
 */
export function applyPlan<R extends WorkRecord>(record: R, plan: Plan, now: Date, outcomes: object = {}): R {
  const looks = { ...(record.looks ?? record.attempts) };
  const next: R = {
    ...record,
    attempts: { ...record.attempts },
    looks,
    history: [...record.history],
    updatedAt: now.toISOString(),
  };

  // A look includes waiting and logistics. Only a real `act` spends a try;
  // transition actions are one-shot and are not retried.
  if (plan.kind === "act" || plan.kind === "wait") {
    looks[record.state] = looksIn(record, record.state) + 1;
  }
  if (plan.kind === "act" && plan.attempt !== false && !notATryIn(outcomes)) {
    next.attempts[record.state] = attemptsIn(record, record.state) + 1;
  }

  if (plan.kind === "advance") {
    next.state = plan.to;
    next.history.push({ at: now.toISOString(), from: record.state, to: plan.to, why: plan.why });
  }

  return next;
}

